"use strict";
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const K={a:'#2453c9',b:'#d9480f',r:'#2b8a3e',d:'#7048e8',w:'#c92a2a',f:'#e67700',ink:'#1c2230',mut:'#5d6577',ax:'#9aa1b0',gr:'#eeeae0',line:'#e3ddcf',soft:'#e6ecfb'};
const TAU=Math.PI*2;

/* ---------- vistas ---------- */
{const st=document.createElement('style');st.textContent=".np-chk{display:inline-flex;align-items:center;gap:6px;font-size:.88rem;color:var(--muted);cursor:pointer}\n.np-chk input{accent-color:var(--fis);width:16px;height:16px}\n.np-sel{font:500 .9rem Inter,sans-serif;border:1px solid var(--line);border-radius:10px;padding:7px 10px;background:var(--kl-raise);color:var(--ink);max-width:100%}\n.view[data-view^=\"np-\"] .canvas-box canvas{cursor:default}\n.np-rel{border-left:4px solid var(--fis);padding:12px 16px}\n.np-rel p{margin:0}\n";document.head.appendChild(st);}
{const anchor=document.querySelector('.view[data-view="ejercicios"]');const tmp=document.createElement('div');tmp.innerHTML="<section class=\"view\" data-view=\"nuclear-particulas\">\n  <div class=\"eyebrow\">F\u00edsica \u00b7 Nivel Krane, <i>Introductory Nuclear Physics</i> \u00b7 Griffiths, <i>Introduction to Elementary Particles</i></div>\n  <h1>F\u00edsica nuclear y de part\u00edculas</h1>\n  <p class=\"lead\">Del n\u00facleo at\u00f3mico al Modelo Est\u00e1ndar. La primera mitad sigue a Krane: tama\u00f1o y masa del n\u00facleo, la fuerza nuclear, los modelos de capas y colectivo, las desintegraciones \u03b1, \u03b2 y \u03b3, las reacciones, la fisi\u00f3n y la fusi\u00f3n. La segunda mitad sigue a Griffiths: simetr\u00edas y quarks, diagramas de Feynman, la interacci\u00f3n d\u00e9bil y las oscilaciones de neutrinos. Cada tema tiene resumen, laboratorio interactivo, leyes, ejemplo resuelto y teor\u00eda desarrollada.</p>\n  <a class=\"ex-banner\" href=\"#nuclear-particulas-ejercicios\"><div class=\"bi\">\u270e</div><div><b>Ejercicios resueltos</b><span>12 ejercicios de F\u00edsica nuclear y de part\u00edculas con soluci\u00f3n paso a paso</span></div><span class=\"go\">Practicar \u2192</span></a>\n\n  <h2 class=\"unit-h\">Unidad I \u00b7 Propiedades del n\u00facleo</h2>\n  <div class=\"topics unit-g\">\n    <a class=\"topic\" href=\"#np-tamano\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><line x1=\"30\" y1=\"125\" x2=\"280\" y2=\"125\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><line x1=\"30\" y1=\"125\" x2=\"30\" y2=\"15\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><path d=\"M30,35 L120,35 C150,35 160,120 200,123 L280,125\" fill=\"none\" stroke=\"#2453c9\" stroke-width=\"3.5\"/><line x1=\"152\" y1=\"20\" x2=\"152\" y2=\"125\" stroke=\"#d9480f\" stroke-dasharray=\"5 4\" stroke-width=\"2\"/><text x=\"158\" y=\"30\" font-family=\"Inter\" font-size=\"15\" font-weight=\"700\" fill=\"#d9480f\">R = R\u2080A^1/3</text><text x=\"40\" y=\"28\" font-family=\"Inter\" font-size=\"14\" font-weight=\"700\" fill=\"#2453c9\">\u03c1(r)</text></svg></div>\n      <div class=\"body\"><h3>Tama\u00f1o y distribuci\u00f3n de carga</h3><p>Dispersi\u00f3n de electrones, factor de forma, distribuci\u00f3n de Fermi, R = R\u2080A<sup>1/3</sup> y densidad nuclear constante.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n    <a class=\"topic\" href=\"#np-enlace\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><line x1=\"30\" y1=\"130\" x2=\"285\" y2=\"130\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><line x1=\"30\" y1=\"130\" x2=\"30\" y2=\"12\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><path d=\"M32,120 C40,60 55,40 80,32 C110,24 130,22 150,24 C200,30 240,38 280,46\" fill=\"none\" stroke=\"#2453c9\" stroke-width=\"3.5\"/><g fill=\"#d9480f\"><circle cx=\"45\" cy=\"70\" r=\"4\"/><circle cx=\"62\" cy=\"38\" r=\"4\"/><circle cx=\"100\" cy=\"26\" r=\"4\"/><circle cx=\"125\" cy=\"22\" r=\"4\"/><circle cx=\"190\" cy=\"29\" r=\"4\"/><circle cx=\"262\" cy=\"44\" r=\"4\"/></g><text x=\"160\" y=\"80\" font-family=\"Inter\" font-size=\"16\" font-weight=\"700\" fill=\"#1c2230\">B/A</text></svg></div>\n      <div class=\"body\"><h3>Masa y energ\u00eda de enlace</h3><p>Defecto de masa, curva B/A, f\u00f3rmula semiemp\u00edrica de la gota l\u00edquida, par\u00e1bolas isob\u00e1ricas y valle de estabilidad.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n    <a class=\"topic\" href=\"#np-fuerza\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><line x1=\"20\" y1=\"60\" x2=\"285\" y2=\"60\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><path d=\"M30,60 L30,125 L110,125 L110,60\" fill=\"none\" stroke=\"#1c2230\" stroke-width=\"3\"/><path d=\"M30,60 C60,25 95,22 110,38 C140,62 200,60 285,60\" fill=\"none\" stroke=\"#2453c9\" stroke-width=\"3\"/><line x1=\"30\" y1=\"112\" x2=\"285\" y2=\"112\" stroke=\"#d9480f\" stroke-dasharray=\"5 4\" stroke-width=\"2\"/><text x=\"190\" y=\"105\" font-family=\"Inter\" font-size=\"14\" font-weight=\"700\" fill=\"#d9480f\">\u2212B = \u22122,22 MeV</text><text x=\"150\" y=\"40\" font-family=\"Inter\" font-size=\"14\" font-weight=\"700\" fill=\"#2453c9\">u(r)</text></svg></div>\n      <div class=\"body\"><h3>Fuerza nuclear y deuter\u00f3n</h3><p>Pozo cuadrado para el deuter\u00f3n, dependencia de spin, fuerza tensorial, independencia de carga y potencial de Yukawa.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n  </div>\n\n  <h2 class=\"unit-h\">Unidad II \u00b7 Modelos nucleares</h2>\n  <div class=\"topics unit-g\">\n    <a class=\"topic\" href=\"#np-capas\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><g stroke=\"#2453c9\" stroke-width=\"3\"><line x1=\"40\" y1=\"130\" x2=\"130\" y2=\"130\"/><line x1=\"40\" y1=\"105\" x2=\"130\" y2=\"105\"/><line x1=\"40\" y1=\"98\" x2=\"130\" y2=\"98\"/><line x1=\"40\" y1=\"70\" x2=\"130\" y2=\"70\"/><line x1=\"40\" y1=\"62\" x2=\"130\" y2=\"62\"/><line x1=\"40\" y1=\"56\" x2=\"130\" y2=\"56\"/><line x1=\"40\" y1=\"30\" x2=\"130\" y2=\"30\"/></g><g font-family=\"Inter\" font-size=\"13\" font-weight=\"700\" fill=\"#d9480f\"><text x=\"150\" y=\"122\">2</text><text x=\"150\" y=\"90\">8</text><text x=\"150\" y=\"48\">20</text><text x=\"150\" y=\"24\">28</text></g><text x=\"190\" y=\"80\" font-family=\"Inter\" font-size=\"16\" font-weight=\"700\" fill=\"#1c2230\">\u2113\u00b7s</text></svg></div>\n      <div class=\"body\"><h3>Modelo de capas</h3><p>N\u00fameros m\u00e1gicos, potencial medio, acoplamiento spin-\u00f3rbita, esp\u00edn y paridad del estado fundamental, momentos magn\u00e9ticos.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n    <a class=\"topic\" href=\"#np-colectivos\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><ellipse cx=\"95\" cy=\"75\" rx=\"70\" ry=\"48\" fill=\"#e6ecfb\" stroke=\"#2453c9\" stroke-width=\"3\"/><path d=\"M95,10 L95,140\" stroke=\"#9aa1b0\" stroke-dasharray=\"4 4\"/><path d=\"M60,22 A40,10 0 1,0 130,22\" fill=\"none\" stroke=\"#d9480f\" stroke-width=\"2.5\"/><g stroke=\"#1c2230\" stroke-width=\"2.5\"><line x1=\"200\" y1=\"135\" x2=\"270\" y2=\"135\"/><line x1=\"200\" y1=\"125\" x2=\"270\" y2=\"125\"/><line x1=\"200\" y1=\"100\" x2=\"270\" y2=\"100\"/><line x1=\"200\" y1=\"55\" x2=\"270\" y2=\"55\"/></g><g font-family=\"Inter\" font-size=\"12\" font-weight=\"700\" fill=\"#1c2230\"><text x=\"275\" y=\"139\">0\u207a</text><text x=\"275\" y=\"125\">2\u207a</text><text x=\"275\" y=\"104\">4\u207a</text><text x=\"275\" y=\"59\">6\u207a</text></g></svg></div>\n      <div class=\"body\"><h3>Modelos colectivos</h3><p>Deformaci\u00f3n, vibraciones cuadrupolares, bandas rotacionales E = \u0127\u00b2J(J+1)/2\ud835\udcd8 y momento de inercia nuclear.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n  </div>\n\n  <h2 class=\"unit-h\">Unidad III \u00b7 Desintegraci\u00f3n radiactiva</h2>\n  <div class=\"topics unit-g\">\n    <a class=\"topic\" href=\"#np-decaimiento\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><line x1=\"30\" y1=\"130\" x2=\"285\" y2=\"130\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><line x1=\"30\" y1=\"130\" x2=\"30\" y2=\"12\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><path d=\"M30,20 C80,80 140,115 285,128\" fill=\"none\" stroke=\"#2453c9\" stroke-width=\"3.5\"/><path d=\"M30,130 C60,60 100,55 150,80 C200,105 240,118 285,124\" fill=\"none\" stroke=\"#d9480f\" stroke-width=\"3\"/><path d=\"M30,130 C120,128 180,70 285,40\" fill=\"none\" stroke=\"#2b8a3e\" stroke-width=\"3\"/><text x=\"230\" y=\"35\" font-family=\"Inter\" font-size=\"14\" font-weight=\"700\" fill=\"#2b8a3e\">C</text><text x=\"120\" y=\"62\" font-family=\"Inter\" font-size=\"14\" font-weight=\"700\" fill=\"#d9480f\">B</text><text x=\"50\" y=\"30\" font-family=\"Inter\" font-size=\"14\" font-weight=\"700\" fill=\"#2453c9\">A</text></svg></div>\n      <div class=\"body\"><h3>Ley de decaimiento y cadenas</h3><p>Ley exponencial, actividad, estad\u00edstica de Poisson, ecuaciones de Bateman, equilibrio secular y dataci\u00f3n radiom\u00e9trica.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n    <a class=\"topic\" href=\"#np-alfa\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><line x1=\"20\" y1=\"100\" x2=\"285\" y2=\"100\" stroke=\"#d9480f\" stroke-dasharray=\"5 4\" stroke-width=\"2\"/><path d=\"M20,135 L70,135 L70,20 C110,50 170,80 285,92\" fill=\"none\" stroke=\"#1c2230\" stroke-width=\"3\"/><path d=\"M20,100 C30,85 40,115 50,100 S62,85 70,100 C100,102 110,101 135,100 C150,90 160,110 170,100 S190,90 200,100 S220,110 230,100\" fill=\"none\" stroke=\"#2453c9\" stroke-width=\"2.5\"/><text x=\"150\" y=\"40\" font-family=\"Inter\" font-size=\"15\" font-weight=\"700\" fill=\"#1c2230\">e^(\u22122G)</text></svg></div>\n      <div class=\"body\"><h3>Desintegraci\u00f3n alfa</h3><p>Valor Q, barrera de Coulomb, efecto t\u00fanel de Gamow, ley de Geiger\u2013Nuttall y estructura fina del espectro.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n    <a class=\"topic\" href=\"#np-beta\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><line x1=\"30\" y1=\"130\" x2=\"285\" y2=\"130\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><line x1=\"30\" y1=\"130\" x2=\"30\" y2=\"12\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><path d=\"M30,130 C60,40 110,30 150,45 C200,65 240,110 270,130\" fill=\"none\" stroke=\"#2453c9\" stroke-width=\"3.5\"/><line x1=\"270\" y1=\"20\" x2=\"270\" y2=\"130\" stroke=\"#d9480f\" stroke-dasharray=\"5 4\" stroke-width=\"2\"/><text x=\"236\" y=\"20\" font-family=\"Inter\" font-size=\"15\" font-weight=\"700\" fill=\"#d9480f\">Q</text><text x=\"80\" y=\"25\" font-family=\"Inter\" font-size=\"14\" font-weight=\"700\" fill=\"#1c2230\">n \u2192 p e\u207b \u03bd\u0304</text></svg></div>\n      <div class=\"body\"><h3>Desintegraci\u00f3n beta</h3><p>\u03b2\u207b, \u03b2\u207a y captura electr\u00f3nica, el neutrino, regla de oro de Fermi, espectro, gr\u00e1fico de Kurie y valores ft.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n    <a class=\"topic\" href=\"#np-gamma\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><g stroke=\"#1c2230\" stroke-width=\"3\"><line x1=\"40\" y1=\"30\" x2=\"150\" y2=\"30\"/><line x1=\"40\" y1=\"85\" x2=\"150\" y2=\"85\"/><line x1=\"40\" y1=\"130\" x2=\"150\" y2=\"130\"/></g><g stroke=\"#2453c9\" stroke-width=\"2.5\"><line x1=\"70\" y1=\"32\" x2=\"70\" y2=\"82\"/><line x1=\"110\" y1=\"32\" x2=\"110\" y2=\"127\"/><line x1=\"130\" y1=\"87\" x2=\"130\" y2=\"127\"/></g><path d=\"M180,70 q8,-14 16,0 t16,0 t16,0 t16,0 t16,0\" fill=\"none\" stroke=\"#d9480f\" stroke-width=\"3\"/><text x=\"200\" y=\"110\" font-family=\"Inter\" font-size=\"15\" font-weight=\"700\" fill=\"#d9480f\">E2, M1\u2026</text></svg></div>\n      <div class=\"body\"><h3>Desintegraci\u00f3n gamma</h3><p>Multipolos el\u00e9ctricos y magn\u00e9ticos, reglas de selecci\u00f3n, estimaciones de Weisskopf, conversi\u00f3n interna, is\u00f3meros y M\u00f6ssbauer.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n  </div>\n\n  <h2 class=\"unit-h\">Unidad IV \u00b7 Reacciones nucleares</h2>\n  <div class=\"topics unit-g\">\n    <a class=\"topic\" href=\"#np-reacciones\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><circle cx=\"190\" cy=\"75\" r=\"10\" fill=\"#d9480f\"/><g fill=\"none\" stroke=\"#2453c9\" stroke-width=\"2.2\"><path d=\"M10,40 L150,40 C190,40 230,20 290,5\"/><path d=\"M10,60 L150,60 C185,58 200,40 260,5\"/><path d=\"M10,72 L160,72 C180,72 175,45 150,20\"/><path d=\"M10,95 L150,95 C190,95 230,120 290,140\"/></g><text x=\"20\" y=\"130\" font-family=\"Inter\" font-size=\"14\" font-weight=\"700\" fill=\"#1c2230\">d\u03c3/d\u03a9 \u221d 1/sin\u2074(\u03b8/2)</text></svg></div>\n      <div class=\"body\"><h3>Reacciones: valor Q y secci\u00f3n eficaz</h3><p>Cinem\u00e1tica no relativista, energ\u00eda umbral, secci\u00f3n eficaz, Rutherford, n\u00facleo compuesto y resonancia de Breit\u2013Wigner.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n    <a class=\"topic\" href=\"#np-fision-fusion\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><circle cx=\"60\" cy=\"75\" r=\"30\" fill=\"#e6ecfb\" stroke=\"#2453c9\" stroke-width=\"3\"/><circle cx=\"130\" cy=\"45\" r=\"20\" fill=\"#e6ecfb\" stroke=\"#2453c9\" stroke-width=\"2.5\"/><circle cx=\"135\" cy=\"110\" r=\"18\" fill=\"#e6ecfb\" stroke=\"#2453c9\" stroke-width=\"2.5\"/><g fill=\"#d9480f\"><circle cx=\"175\" cy=\"70\" r=\"5\"/><circle cx=\"190\" cy=\"85\" r=\"5\"/></g><circle cx=\"245\" cy=\"75\" r=\"16\" fill=\"#fff1e6\" stroke=\"#d9480f\" stroke-width=\"3\"/><text x=\"232\" y=\"125\" font-family=\"Inter\" font-size=\"13\" font-weight=\"700\" fill=\"#d9480f\">D+T</text></svg></div>\n      <div class=\"body\"><h3>Fisi\u00f3n y fusi\u00f3n</h3><p>Barrera de fisi\u00f3n y Z\u00b2/A, reacci\u00f3n en cadena y factor k, ciclo pp, pico de Gamow y criterio de Lawson.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n  </div>\n\n  <h2 class=\"unit-h\">Unidad V \u00b7 Part\u00edculas elementales</h2>\n  <div class=\"block np-rel\">\n    <p><b>Antes de empezar.</b> Esta unidad usa 4-momentos y la masa invariante \\(M^2c^4 = \\left(\\sum E\\right)^2 - \\left|\\sum \\vec p\\,c\\right|^2\\). No se repite aqu\u00ed: <a href=\"#fm-dinamica\">Repasar en relatividad especial \u2192</a> (F\u00edsica moderna, Unidad I) \u00b7 teor\u00eda: <a class=\"kw\" href=\"#t-emc2\">din\u00e1mica relativista</a>, <a class=\"kw\" href=\"#t-cuadrivectores\">cuadrivectores</a> \u00b7 tambi\u00e9n en <a href=\"#mc-relatividad\">Mec\u00e1nica cl\u00e1sica, cap. 14</a>.</p>\n  </div>\n  <div class=\"topics unit-g\">\n    <a class=\"topic\" href=\"#np-simetrias\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><polygon points=\"150,15 215,52 215,112 150,140 85,112 85,52\" fill=\"none\" stroke=\"#2453c9\" stroke-width=\"2.5\"/><g fill=\"#d9480f\"><circle cx=\"150\" cy=\"15\" r=\"7\"/><circle cx=\"215\" cy=\"52\" r=\"7\"/><circle cx=\"215\" cy=\"112\" r=\"7\"/><circle cx=\"150\" cy=\"140\" r=\"7\"/><circle cx=\"85\" cy=\"112\" r=\"7\"/><circle cx=\"85\" cy=\"52\" r=\"7\"/><circle cx=\"140\" cy=\"78\" r=\"7\"/><circle cx=\"160\" cy=\"78\" r=\"7\"/></g><text x=\"235\" y=\"80\" font-family=\"Inter\" font-size=\"15\" font-weight=\"700\" fill=\"#1c2230\">SU(3)</text></svg></div>\n      <div class=\"body\"><h3>Simetr\u00edas, quarks y conservaci\u00f3n</h3><p>N\u00fameros cu\u00e1nticos conservados, P, C, T y CPT, isosp\u00edn, SU(3) de sabor, octetes y decuplete, color y la \u03a9\u207b.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n    <a class=\"topic\" href=\"#np-feynman\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><g stroke=\"#2453c9\" stroke-width=\"3\"><line x1=\"40\" y1=\"20\" x2=\"110\" y2=\"75\"/><line x1=\"40\" y1=\"130\" x2=\"110\" y2=\"75\"/><line x1=\"190\" y1=\"75\" x2=\"260\" y2=\"20\"/><line x1=\"190\" y1=\"75\" x2=\"260\" y2=\"130\"/></g><path d=\"M110,75 q10,-12 20,0 t20,0 t20,0 t20,0\" fill=\"none\" stroke=\"#d9480f\" stroke-width=\"3\"/><text x=\"130\" y=\"110\" font-family=\"Inter\" font-size=\"15\" font-weight=\"700\" fill=\"#d9480f\">\u03b3*</text><text x=\"22\" y=\"20\" font-family=\"Inter\" font-size=\"13\" font-weight=\"700\" fill=\"#1c2230\">e\u207b</text><text x=\"266\" y=\"20\" font-family=\"Inter\" font-size=\"13\" font-weight=\"700\" fill=\"#1c2230\">\u03bc\u207b</text></svg></div>\n      <div class=\"body\"><h3>Diagramas de Feynman</h3><p>V\u00e9rtices y propagadores, QED a nivel \u00e1rbol, e\u207ae\u207b \u2192 \u03bc\u207a\u03bc\u207b, la raz\u00f3n R y la evidencia de tres colores.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n  </div>\n\n  <h2 class=\"unit-h\">Unidad VI \u00b7 Interacciones y Modelo Est\u00e1ndar</h2>\n  <div class=\"topics unit-g\">\n    <a class=\"topic\" href=\"#np-debil\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><line x1=\"30\" y1=\"130\" x2=\"285\" y2=\"130\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><g fill=\"#2453c9\"><rect x=\"40\" y=\"122\" width=\"16\" height=\"8\"/><rect x=\"58\" y=\"118\" width=\"16\" height=\"12\"/><rect x=\"76\" y=\"114\" width=\"16\" height=\"16\"/><rect x=\"94\" y=\"104\" width=\"16\" height=\"26\"/><rect x=\"112\" y=\"72\" width=\"16\" height=\"58\"/><rect x=\"130\" y=\"20\" width=\"16\" height=\"110\"/><rect x=\"148\" y=\"40\" width=\"16\" height=\"90\"/><rect x=\"166\" y=\"92\" width=\"16\" height=\"38\"/><rect x=\"184\" y=\"112\" width=\"16\" height=\"18\"/><rect x=\"202\" y=\"120\" width=\"16\" height=\"10\"/></g><text x=\"200\" y=\"40\" font-family=\"Inter\" font-size=\"16\" font-weight=\"700\" fill=\"#d9480f\">Z\u2070</text></svg></div>\n      <div class=\"body\"><h3>Interacci\u00f3n d\u00e9bil</h3><p>W y Z, teor\u00eda V\u2212A, violaci\u00f3n de paridad (Wu), helicidad, desintegraci\u00f3n del mu\u00f3n, CKM y la resonancia del Z.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n    <a class=\"topic\" href=\"#np-neutrinos-me\">\n      <div class=\"thumb\"><svg viewBox=\"0 0 300 150\" aria-hidden=\"true\"><line x1=\"20\" y1=\"130\" x2=\"285\" y2=\"130\" stroke=\"#9aa1b0\" stroke-width=\"2\"/><path d=\"M20,30 C50,30 60,128 90,128 S130,30 160,30 S200,128 230,128 S270,30 285,30\" fill=\"none\" stroke=\"#2453c9\" stroke-width=\"3\"/><path d=\"M20,128 C50,128 60,30 90,30 S130,128 160,128 S200,30 230,30 S270,128 285,128\" fill=\"none\" stroke=\"#d9480f\" stroke-width=\"3\" opacity=\".8\"/><text x=\"100\" y=\"80\" font-family=\"Inter\" font-size=\"15\" font-weight=\"700\" fill=\"#1c2230\">\u03bd_\u03bc \u21c4 \u03bd_\u03c4</text></svg></div>\n      <div class=\"body\"><h3>Oscilaciones de neutrinos y Modelo Est\u00e1ndar</h3><p>Mezcla de sabores, P(L/E), matriz PMNS, evidencias solares, atmosf\u00e9ricas y de reactores, y el panorama del Modelo Est\u00e1ndar.</p><span class=\"go\">Abrir tema \u2192</span></div>\n    </a>\n  </div>\n\n  <div class=\"block\">\n    <h2><span class=\"ico\">\u2630</span>Temario y prerrequisitos</h2>\n    <ul class=\"keypoints\">\n      <li><b>Unidades I\u2013II \u00b7 El n\u00facleo (Krane, caps. 3\u20135).</b> Necesitas la mec\u00e1nica cu\u00e1ntica de <a href=\"#fisica-moderna\">F\u00edsica moderna</a>: pozo finito, oscilador arm\u00f3nico, \u00e1tomo de hidr\u00f3geno y spin.</li>\n      <li><b>Unidad III \u00b7 Desintegraciones (caps. 6, 8\u201310).</b> Usa el <a href=\"#fm-tunel\">efecto t\u00fanel</a>, ecuaciones diferenciales lineales (<a href=\"#ecuaciones-diferenciales\">Ecuaciones diferenciales</a>) y multipolos de <a href=\"#electromagnetismo\">Electromagnetismo</a>.</li>\n      <li><b>Unidad IV \u00b7 Reacciones (caps. 11, 13, 14).</b> Conservaci\u00f3n de energ\u00eda y momento, secci\u00f3n eficaz y dispersi\u00f3n de Rutherford (tambi\u00e9n en <a href=\"#fm-bohr\">F\u00edsica moderna</a>).</li>\n      <li><b>Unidades V\u2013VI \u00b7 Part\u00edculas (Griffiths, caps. 1\u20134, 6, 9\u201311).</b> Usan relatividad especial, que no se repite aqu\u00ed: <a href=\"#fm-dinamica\">rep\u00e1sala en F\u00edsica moderna</a>. Tambi\u00e9n usan grupos de simetr\u00eda y matrices unitarias (<a href=\"#algebra-lineal\">\u00c1lgebra lineal</a>).</li>\n    </ul>\n    <p class=\"hint\" style=\"margin-top:10px\">Fuentes: K. S. Krane, <i>Introductory Nuclear Physics</i> (Wiley, 1988); D. Griffiths, <i>Introduction to Elementary Particles</i>, 2.\u00aa ed. (Wiley-VCH, 2008); complemento: B. R. Martin y G. Shaw, <i>Nuclear and Particle Physics</i>, 3.\u00aa ed. (Wiley, 2019). Datos num\u00e9ricos: Particle Data Group (<i>Review of Particle Physics</i>) y Atomic Mass Evaluation (AME2020).</p>\n  </div>\n</section>\n<!-- ============ NP \u00b7 TAMA\u00d1O ============ -->\n<section class=\"view\" data-view=\"np-tamano\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad I \u00b7 Propiedades del n\u00facleo</div>\n  <h1>Tama\u00f1o y distribuci\u00f3n de carga del n\u00facleo</h1>\n  <p class=\"lead\">\u00bfQu\u00e9 tan grande es un n\u00facleo y c\u00f3mo se reparte su carga? Para \"verlo\" hace falta una sonda con longitud de onda menor que unos pocos femt\u00f3metros. Los electrones de alta energ\u00eda son ideales: solo sienten la fuerza electromagn\u00e9tica, que se conoce exactamente.</p>\n  <div class=\"toc\"><a href=\"#nta-res\" data-scroll>Resumen</a><a href=\"#nta-lab\" data-scroll>Visualiza</a><a href=\"#nta-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nta-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nta-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>La sonda.</b> Para resolver detalles de tama\u00f1o \\(R\\) se necesita \\(\\lambda \\lesssim R\\), es decir \\(p \\gtrsim \\hbar/R\\). Con \\(\\hbar c = 197{,}3\\ \\text{MeV\u00b7fm}\\) y \\(R \\sim 5\\ \\text{fm}\\), hacen falta electrones de unos cientos de MeV.</li>\n      <li><b>Factor de forma.</b> La secci\u00f3n eficaz medida es la de una carga puntual (Mott) multiplicada por \\(|F(q)|^2\\), donde \\(F(q) = \\frac{1}{Ze}\\int \\rho(\\vec r)\\,e^{i\\vec q\\cdot\\vec r}\\,d^3r\\) es la transformada de Fourier de la carga y \\(\\hbar q = 2p\\sin(\\theta/2)\\) el momento transferido.</li>\n      <li><b>Distribuci\u00f3n de Fermi.</b> Los datos se ajustan con \\(\\rho(r) = \\dfrac{\\rho_0}{1+e^{(r-R)/a}}\\): densidad casi constante en el interior y una \"piel\" de espesor \\(t = 4{,}4\\,a \\approx 2{,}3\\ \\text{fm}\\) igual para todos los n\u00facleos.</li>\n      <li><b>Radio nuclear.</b> \\(R = R_0A^{1/3}\\) con \\(R_0 \\approx 1{,}2\\ \\text{fm}\\). El volumen crece proporcional a \\(A\\): la densidad nuclear es la misma en todos los n\u00facleos (<i>saturaci\u00f3n</i>), como en una gota de l\u00edquido.</li>\n      <li><b>Densidad nuclear.</b> \\(\\rho_N \\approx 0{,}16\\ \\text{nucleones/fm}^3 \\approx 2\\times10^{17}\\ \\text{kg/m}^3\\): una cucharadita de materia nuclear pesar\u00eda cientos de millones de toneladas (estrellas de neutrones).</li>\n      <li><b>M\u00ednimos de difracci\u00f3n.</b> Un n\u00facleo de borde n\u00edtido difracta electrones como un disco difracta luz: \\(|F|^2\\) tiene ceros cerca de \\(qR \\approx 4{,}49,\\ 7{,}73,\\dots\\) El primer m\u00ednimo mide \\(R\\) directamente.</li>\n      <li><b>Otras medidas.</b> \u00c1tomos mu\u00f3nicos (el mu\u00f3n, 207 veces m\u00e1s pesado, orbita dentro del n\u00facleo), desplazamiento isot\u00f3pico de l\u00edneas at\u00f3micas y energ\u00eda de Coulomb de n\u00facleos espejo dan el mismo \\(R_0\\).</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nta-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"rho\" class=\"on\">Distribuci\u00f3n de Fermi</button><button data-t=\"ff\">Factor de forma</button></div>\n    <div class=\"tabpane on\" data-pane=\"rho\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nta-cv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">A <input type=\"range\" id=\"nta-A\" min=\"4\" max=\"240\" step=\"1\" value=\"208\"><b></b></label>\n            <label class=\"slider\">a (fm) <input type=\"range\" id=\"nta-a\" min=\"0.05\" max=\"1\" step=\"0.01\" value=\"0.55\"><b></b></label>\n            <label class=\"slider\">R\u2080 (fm) <input type=\"range\" id=\"nta-r0\" min=\"1\" max=\"1.4\" step=\"0.01\" value=\"1.2\"><b></b></label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nta-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Curva azul: densidad de carga normalizada a \\(Ze\\). Las l\u00edneas naranjas marcan d\u00f3nde \\(\\rho\\) cae del 90 % al 10 % de \\(\\rho_0\\) (espesor de piel). Gris: esfera uniforme del mismo radio. Arriba, comparaci\u00f3n de tama\u00f1os de varios n\u00facleos a escala.</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"ff\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nta-fv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">E del electr\u00f3n (MeV) <input type=\"range\" id=\"nta-E\" min=\"100\" max=\"800\" step=\"10\" value=\"420\"><b></b></label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nta-fread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">\\(|F(q)|^2\\) en escala logar\u00edtmica para la distribuci\u00f3n de Fermi (azul) y para una esfera uniforme (gris), con los par\u00e1metros de la otra pesta\u00f1a. La piel difusa suaviza los ceros y hace caer \\(|F|^2\\) m\u00e1s r\u00e1pido. El eje superior indica el \u00e1ngulo de dispersi\u00f3n para la energ\u00eda elegida.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nta-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Radio nuclear</h3><div class=\"eq\">\\[ R = R_0A^{1/3},\\qquad R_0 \\approx 1{,}2\\ \\text{fm} \\]</div><p>V\u00e1lido para \\(A \\gtrsim 10\\). Densidad nuclear constante.</p></div>\n      <div class=\"law\"><h3>Distribuci\u00f3n de Fermi</h3><div class=\"eq\">\\[ \\rho(r) = \\frac{\\rho_0}{1+e^{(r-R)/a}} \\]</div><p>\\(a \\approx 0{,}55\\ \\text{fm}\\); espesor 90 %\u219210 %: \\(t = 4\\ln 3\\,a \\approx 4{,}4\\,a\\).</p></div>\n      <div class=\"law\"><h3>Secci\u00f3n eficaz de Mott</h3><div class=\"eq\">\\[ \\left(\\frac{d\\sigma}{d\\Omega}\\right)_{\\!M} = \\left(\\frac{Z\\alpha\\hbar c}{2E}\\right)^{\\!2}\\frac{\\cos^2(\\theta/2)}{\\sin^4(\\theta/2)} \\]</div><p>Electr\u00f3n ultrarrelativista sobre carga puntual, sin retroceso.</p></div>\n      <div class=\"law\"><h3>Factor de forma</h3><div class=\"eq\">\\[ \\frac{d\\sigma}{d\\Omega} = \\left(\\frac{d\\sigma}{d\\Omega}\\right)_{\\!M}|F(q)|^2,\\quad F(q) = \\frac{4\\pi}{Zeq}\\int_0^\\infty \\rho(r)\\,r\\sin(qr)\\,dr \\]</div><p>\\(\\hbar q = 2p\\sin(\\theta/2)\\). Para \\(q\\to0\\), \\(F \\to 1 - q^2\\langle r^2\\rangle/6\\).</p></div>\n      <div class=\"law\"><h3>Esfera uniforme</h3><div class=\"eq\">\\[ F(q) = \\frac{3\\,[\\sin(qR) - qR\\cos(qR)]}{(qR)^3} \\]</div><p>Primer cero en \\(qR = 4{,}493\\); \\(\\langle r^2\\rangle = \\tfrac35R^2\\).</p></div>\n      <div class=\"law\"><h3>N\u00facleos espejo</h3><div class=\"eq\">\\[ \\Delta E_C = \\frac{3}{5}\\frac{e^2}{4\\pi\\varepsilon_0R}\\,(A-1) \\]</div><p>Diferencia de energ\u00eda de Coulomb entre \\((Z,N)=(\\tfrac{A+1}{2},\\tfrac{A-1}{2})\\) y su espejo.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nta-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>Estima la densidad de masa de la materia nuclear y comp\u00e1rala con la del agua. (Basado en Krane, \u00a73.1.)</b></p>\n      <ol><li>Un n\u00facleo de \\(A\\) nucleones tiene masa \\(\\approx A\\,m_N\\) con \\(m_N \\approx 1{,}66\\times10^{-27}\\ \\text{kg}\\) (1 u) y volumen \\(\\tfrac43\\pi R^3 = \\tfrac43\\pi R_0^3A\\).</li><li>La densidad no depende de \\(A\\): \\(\\rho = \\dfrac{A\\,m_N}{\\tfrac43\\pi R_0^3A} = \\dfrac{3m_N}{4\\pi R_0^3}\\).</li><li>Con \\(R_0 = 1{,}2\\times10^{-15}\\ \\text{m}\\): \\(\\rho = \\dfrac{3(1{,}66\\times10^{-27})}{4\\pi(1{,}728\\times10^{-45})} \\approx 2{,}3\\times10^{17}\\ \\text{kg/m}^3\\).</li><li>En n\u00famero de nucleones: \\(n = 3/(4\\pi R_0^3) = 0{,}14\\ \\text{fm}^{-3}\\) (el valor central de la distribuci\u00f3n de Fermi es algo mayor, \\(0{,}16\\ \\text{fm}^{-3}\\)).</li></ol>\n      <p>Es \\(2\\times10^{14}\\) veces la densidad del agua. Una estrella de neutrones de 1,4 masas solares con esta densidad tiene un radio de solo \\(\\approx 14\\) km.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#nuclear-particulas\"><small>\u2190 Volver</small>F\u00edsica nuclear y de part\u00edculas</a><a class=\"next\" href=\"#np-enlace\"><small>Siguiente \u2192</small>Masa y energ\u00eda de enlace</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, cap. 3 (\u00a73.1\u20133.2). Redacci\u00f3n y simulaciones propias.</p>\n</section>\n\n<!-- ============ NP \u00b7 ENLACE ============ -->\n<section class=\"view\" data-view=\"np-enlace\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad I \u00b7 Propiedades del n\u00facleo</div>\n  <h1>Masa y energ\u00eda de enlace: la f\u00f3rmula semiemp\u00edrica</h1>\n  <p class=\"lead\">Un n\u00facleo pesa menos que la suma de sus protones y neutrones. Esa diferencia, multiplicada por \\(c^2\\), es la energ\u00eda que lo mantiene unido. Su dependencia con \\(A\\) y \\(Z\\) explica por qu\u00e9 brillan las estrellas, por qu\u00e9 existen los reactores y qu\u00e9 n\u00facleos son estables.</p>\n  <div class=\"toc\"><a href=\"#nen-res\" data-scroll>Resumen</a><a href=\"#nen-lab\" data-scroll>Visualiza</a><a href=\"#nen-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nen-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nen-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Defecto de masa.</b> \\(B = [Z\\,m(^1\\text{H}) + N\\,m_n - m(^A\\text{X})]\\,c^2\\), con masas <i>at\u00f3micas</i> (las masas de los electrones se cancelan). \\(1\\ \\text{u} = 931{,}494\\ \\text{MeV}/c^2\\). La relaci\u00f3n masa-energ\u00eda se <a href=\"#fm-dinamica\">repasa en relatividad especial</a>.</li>\n      <li><b>Curva B/A.</b> Para \\(A \\gtrsim 20\\) la energ\u00eda de enlace por nucle\u00f3n es casi constante, \\(\\approx 8\\ \\text{MeV}\\), con m\u00e1ximo de \\(8{,}79\\ \\text{MeV}\\) en \\(^{56}\\)Fe\u2013\\(^{62}\\)Ni. Unir n\u00facleos ligeros (fusi\u00f3n) o partir pesados (fisi\u00f3n) libera energ\u00eda.</li>\n      <li><b>F\u00f3rmula semiemp\u00edrica.</b> El modelo de la gota l\u00edquida da \\(B = a_vA - a_sA^{2/3} - a_c\\dfrac{Z(Z-1)}{A^{1/3}} - a_{a}\\dfrac{(A-2Z)^2}{A} + \\delta\\), con solo cinco par\u00e1metros ajustados a cientos de masas.</li>\n      <li><b>Origen de cada t\u00e9rmino.</b> Volumen: cada nucle\u00f3n solo interact\u00faa con sus vecinos (saturaci\u00f3n). Superficie: los de la superficie tienen menos vecinos. Coulomb: repulsi\u00f3n de una esfera cargada. Asimetr\u00eda: el principio de Pauli favorece \\(N \\approx Z\\). Apareamiento: los nucleones se acoplan en pares.</li>\n      <li><b>Par\u00e1bolas isob\u00e1ricas.</b> Con \\(A\\) fijo, \\(M(Z)\\) es una par\u00e1bola. Los n\u00facleos de cada lado bajan por desintegraci\u00f3n \u03b2 hacia el m\u00ednimo. Con \\(A\\) par hay dos par\u00e1bolas (par-par y impar-impar) separadas \\(2\\delta\\).</li>\n      <li><b>Valle de estabilidad.</b> El m\u00ednimo est\u00e1 en \\(Z_0 \\approx \\dfrac{A}{2 + (a_c/2a_a)A^{2/3}}\\). Para n\u00facleos pesados la repulsi\u00f3n de Coulomb exige \\(N > Z\\): \\(^{208}\\)Pb tiene 126 neutrones y 82 protones.</li>\n      <li><b>Energ\u00edas de separaci\u00f3n.</b> \\(S_n = B(^A\\text{X}) - B(^{A-1}\\text{X})\\) es lo que cuesta arrancar un neutr\u00f3n. Sus saltos bruscos en ciertos n\u00fameros de nucleones anuncian el <a href=\"#np-capas\">modelo de capas</a>.</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nen-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"ba\" class=\"on\">Curva B/A</button><button data-t=\"carta\">Carta de n\u00faclidos</button></div>\n    <div class=\"tabpane on\" data-pane=\"ba\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nen-cv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">a<sub>v</sub> (MeV) <input type=\"range\" id=\"nen-av\" min=\"12\" max=\"18\" step=\"0.1\" value=\"15.5\"><b></b></label>\n            <label class=\"slider\">a<sub>s</sub> (MeV) <input type=\"range\" id=\"nen-as\" min=\"12\" max=\"22\" step=\"0.1\" value=\"16.8\"><b></b></label>\n            <label class=\"slider\">a<sub>c</sub> (MeV) <input type=\"range\" id=\"nen-ac\" min=\"0.4\" max=\"1\" step=\"0.01\" value=\"0.72\"><b></b></label>\n            <label class=\"slider\">a<sub>a</sub> (MeV) <input type=\"range\" id=\"nen-aa\" min=\"15\" max=\"30\" step=\"0.1\" value=\"23\"><b></b></label>\n            <label class=\"slider\">A destacado <input type=\"range\" id=\"nen-A\" min=\"10\" max=\"240\" step=\"1\" value=\"56\"><b></b></label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nen-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Azul: \\(B/A\\) de la f\u00f3rmula para el is\u00f3baro m\u00e1s ligado de cada \\(A\\). Puntos naranjas: valores experimentales (AME2020). Las l\u00edneas punteadas acumulan los t\u00e9rminos: volumen + superficie, luego + Coulomb; lo que falta hasta la curva azul es asimetr\u00eda y apareamiento. Mueve los coeficientes y mira c\u00f3mo cambia el ajuste.</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"carta\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nen-ch\"></canvas></div>\n          <div class=\"controls\"><div class=\"seg\" id=\"nen-mode\"><button data-m=\"ba\" class=\"on\">Color: B/A</button><button data-m=\"dec\">Color: modo de desintegraci\u00f3n</button></div></div></div>\n        <div><div class=\"readout\" id=\"nen-cread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Carta \\(N\\)\u2013\\(Z\\) calculada con la f\u00f3rmula semiemp\u00edrica. La l\u00ednea negra es \\(N = Z\\); la blanca, el valle \\(Z_0(A)\\). Haz clic sobre un n\u00facleo para ver su energ\u00eda de enlace y hacia d\u00f3nde se desintegra (predicci\u00f3n del modelo: \u03b2\u207b, \u03b2\u207a/CE o \u03b1).</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nen-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Energ\u00eda de enlace</h3><div class=\"eq\">\\[ B = \\left[Z\\,m(^1\\text{H}) + N\\,m_n - m(^A\\text{X})\\right]c^2 \\]</div><p>\\(m(^1\\text{H}) = 1{,}007825\\ \\text{u}\\), \\(m_n = 1{,}008665\\ \\text{u}\\).</p></div>\n      <div class=\"law\"><h3>F\u00f3rmula semiemp\u00edrica</h3><div class=\"eq\">\\[ B = a_vA - a_sA^{2/3} - a_c\\frac{Z(Z-1)}{A^{1/3}} - a_a\\frac{(A-2Z)^2}{A} + \\delta \\]</div><p>Krane: \\(a_v = 15{,}5\\), \\(a_s = 16{,}8\\), \\(a_c = 0{,}72\\), \\(a_a = 23\\) MeV.</p></div>\n      <div class=\"law\"><h3>T\u00e9rmino de apareamiento</h3><div class=\"eq\">\\[ \\delta = \\begin{cases} +a_pA^{-3/4} & Z,N \\text{ pares}\\\\ 0 & A \\text{ impar}\\\\ -a_pA^{-3/4} & Z,N \\text{ impares}\\end{cases} \\]</div><p>\\(a_p = 34\\ \\text{MeV}\\).</p></div>\n      <div class=\"law\"><h3>Coeficiente de Coulomb</h3><div class=\"eq\">\\[ a_c = \\frac{3}{5}\\frac{e^2}{4\\pi\\varepsilon_0R_0} \\approx 0{,}72\\ \\text{MeV} \\]</div><p>Energ\u00eda de una esfera uniformemente cargada, con \\(e^2/4\\pi\\varepsilon_0 = 1{,}44\\ \\text{MeV\u00b7fm}\\).</p></div>\n      <div class=\"law\"><h3>Valle de estabilidad</h3><div class=\"eq\">\\[ Z_0 = \\frac{A}{2 + \\dfrac{a_c}{2a_a}A^{2/3}} \\approx \\frac{A}{2 + 0{,}0157A^{2/3}} \\]</div><p>De \\(\\partial B/\\partial Z = 0\\) a \\(A\\) fijo (despreciando \\(m_n - m_p\\)).</p></div>\n      <div class=\"law\"><h3>Energ\u00eda de separaci\u00f3n</h3><div class=\"eq\">\\[ S_n = B(^A_Z\\text{X}_N) - B(^{A-1}_{\\ \\ Z}\\text{X}_{N-1}) \\]</div><p>An\u00e1logo para \\(S_p\\). Pares: \\(S_n\\) mayor con \\(N\\) par.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nen-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>Usa la f\u00f3rmula semiemp\u00edrica para estimar la energ\u00eda liberada en la fisi\u00f3n sim\u00e9trica \\(^{236}\\text{U}\\to 2\\,^{118}\\text{Pd}\\). (Basado en Krane, \u00a73.3 y cap. 13.)</b></p>\n      <ol><li>Para \\(^{236}\\)U (\\(Z = 92\\), \\(N = 144\\), par-par): volumen \\(15{,}5(236) = 3658{,}0\\); superficie \\(-16{,}8(236)^{2/3} = -641{,}6\\); Coulomb \\(-0{,}72\\,\\frac{92\\cdot91}{236^{1/3}} = -975{,}4\\); asimetr\u00eda \\(-23\\,\\frac{52^2}{236} = -263{,}5\\); apareamiento \\(+34(236)^{-3/4} = +0{,}6\\). Total: \\(B \\approx 1778{,}0\\ \\text{MeV}\\).</li><li>Para \\(^{118}\\)Pd (\\(Z = 46\\), \\(N = 72\\), par-par): \\(1829{,}0 - 404{,}2 - 303{,}9 - 131{,}8 + 0{,}9 = 990{,}2\\ \\text{MeV}\\).</li><li>\\(Q = 2B(\\text{Pd}) - B(\\text{U}) = 1980{,}3 - 1778{,}0 \\approx 202\\ \\text{MeV}\\).</li><li>Casi todo viene del t\u00e9rmino de Coulomb: la repulsi\u00f3n baja de 975 MeV a \\(2\\times304 = 608\\) MeV (ganancia de 367 MeV), mientras la superficie cuesta \\(2\\times404 - 642 = 167\\) MeV m\u00e1s.</li></ol>\n      <p>El valor medido para la fisi\u00f3n de \\(^{235}\\text{U}+n\\) es \\(\\approx 200\\ \\text{MeV}\\): unas 50 millones de veces la energ\u00eda de una reacci\u00f3n qu\u00edmica.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-tamano\"><small>\u2190 Anterior</small>Tama\u00f1o y distribuci\u00f3n de carga</a><a class=\"next\" href=\"#np-fuerza\"><small>Siguiente \u2192</small>Fuerza nuclear y deuter\u00f3n</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, cap. 3 (\u00a73.3). Masas experimentales: AME2020. Redacci\u00f3n y simulaciones propias.</p>\n</section>\n\n<!-- ============ NP \u00b7 FUERZA ============ -->\n<section class=\"view\" data-view=\"np-fuerza\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad I \u00b7 Propiedades del n\u00facleo</div>\n  <h1>La fuerza nuclear y el deuter\u00f3n</h1>\n  <p class=\"lead\">No existe una \"ley de Coulomb\" de la fuerza nuclear: se infiere de sistemas simples. El m\u00e1s simple es el deuter\u00f3n, un prot\u00f3n y un neutr\u00f3n apenas ligados. Su \u00fanico estado ligado, su spin y sus momentos dicen mucho sobre la interacci\u00f3n nucle\u00f3n-nucle\u00f3n.</p>\n  <div class=\"toc\"><a href=\"#nfu-res\" data-scroll>Resumen</a><a href=\"#nfu-lab\" data-scroll>Visualiza</a><a href=\"#nfu-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nfu-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nfu-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>El deuter\u00f3n.</b> \u00danico estado ligado n\u2013p: \\(B_d = 2{,}224\\ \\text{MeV}\\), \\(J^\\pi = 1^+\\). No tiene estados excitados, y no existen el dineutr\u00f3n ni el diprot\u00f3n ligados.</li>\n      <li><b>Pozo cuadrado.</b> Con \\(V = -V_0\\) para \\(r < R\\), la funci\u00f3n radial \\(u = rR(r)\\) es \\(A\\sin kr\\) dentro y \\(Be^{-\\kappa r}\\) fuera. Empalmar \\(u'/u\\) en \\(r = R\\) da la condici\u00f3n \\(k\\cot kR = -\\kappa\\).</li>\n      <li><b>D\u00e9bilmente ligado.</b> \\(1/\\kappa = \\hbar/\\sqrt{2\\mu B_d} = 4{,}3\\ \\text{fm}\\), mayor que el alcance de la fuerza: la mitad de la probabilidad est\u00e1 fuera del pozo. Con \\(R = 2{,}1\\ \\text{fm}\\) hace falta \\(V_0 \\approx 34\\ \\text{MeV}\\), apenas por encima del m\u00ednimo para ligar.</li>\n      <li><b>Dependencia de spin.</b> El deuter\u00f3n tiene spins paralelos (\\(S = 1\\)); el estado singlete (\\(S = 0\\)) no est\u00e1 ligado. La fuerza depende de la orientaci\u00f3n relativa de los spins.</li>\n      <li><b>Fuerza tensorial.</b> El momento magn\u00e9tico \\(\\mu_d = 0{,}857\\,\\mu_N\\) no es exactamente \\(\\mu_p + \\mu_n = 0{,}880\\,\\mu_N\\), y el cuadrupolar \\(Q = 0{,}286\\ e\\,\\text{fm}^2 \\ne 0\\): hay \\(\\approx 4\\%\\) de onda \\(D\\). La fuerza no es central.</li>\n      <li><b>Propiedades generales.</b> Atractiva entre 1 y 2 fm, n\u00facleo repulsivo por debajo de \\(\\approx 0{,}5\\ \\text{fm}\\), alcance corto, independiente de la carga (\\(pp \\approx nn \\approx np\\) en el mismo estado) y con t\u00e9rmino spin-\u00f3rbita.</li>\n      <li><b>Potencial de Yukawa.</b> Un mes\u00f3n de masa \\(m\\) intercambiado da \\(V(r) \\propto -\\dfrac{e^{-r/a}}{r}\\) con alcance \\(a = \\hbar/mc\\). Para el pion, \\(a = 197{,}3/139{,}6 = 1{,}41\\ \\text{fm}\\).</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nfu-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"pozo\" class=\"on\">Deuter\u00f3n en un pozo cuadrado</button><button data-t=\"yuk\">Yukawa frente a Coulomb</button></div>\n    <div class=\"tabpane on\" data-pane=\"pozo\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nfu-cv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">V\u2080 (MeV) <input type=\"range\" id=\"nfu-V\" min=\"10\" max=\"80\" step=\"0.1\" value=\"33.7\"><b></b></label>\n            <label class=\"slider\">R (fm) <input type=\"range\" id=\"nfu-R\" min=\"1\" max=\"3.5\" step=\"0.05\" value=\"2.1\"><b></b></label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nfu-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Se resuelve \\(k\\cot kR = -\\kappa\\) para el estado \\(\\ell = 0\\) m\u00e1s ligado. Azul: \\(u(r)\\) normalizada; la parte sombreada est\u00e1 fuera del pozo. Si \\(V_0R^2\\) cae por debajo de \\(\\pi^2\\hbar^2/8\\mu\\), el estado desaparece.</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"yuk\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nfu-yv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">masa del mes\u00f3n (MeV/c\u00b2) <input type=\"range\" id=\"nfu-m\" min=\"0\" max=\"800\" step=\"5\" value=\"140\"><b></b></label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nfu-yread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">\\(rV(r)\\) normalizado: para Coulomb (\\(m = 0\\)) es constante; para Yukawa cae como \\(e^{-r/a}\\). Con \\(m = 140\\) se obtiene el alcance del pion; con 783 (mes\u00f3n \u03c9), el n\u00facleo repulsivo de corto alcance.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nfu-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Ecuaci\u00f3n radial (\u2113 = 0)</h3><div class=\"eq\">\\[ -\\frac{\\hbar^2}{2\\mu}\\frac{d^2u}{dr^2} + V(r)\\,u = E\\,u,\\qquad \\mu = \\frac{m_pm_n}{m_p+m_n} \\]</div><p>\\(u(0) = 0\\), \\(u(\\infty) = 0\\).</p></div>\n      <div class=\"law\"><h3>Condici\u00f3n de empalme</h3><div class=\"eq\">\\[ k\\cot kR = -\\kappa,\\quad k = \\frac{\\sqrt{2\\mu(V_0 - B)}}{\\hbar},\\ \\kappa = \\frac{\\sqrt{2\\mu B}}{\\hbar} \\]</div><p>Exige \\(kR > \\pi/2\\).</p></div>\n      <div class=\"law\"><h3>Profundidad m\u00ednima</h3><div class=\"eq\">\\[ V_0R^2 > \\frac{\\pi^2\\hbar^2}{8\\mu} \\]</div><p>Para \\(R = 2{,}1\\ \\text{fm}\\): \\(V_0 > 23{,}2\\ \\text{MeV}\\).</p></div>\n      <div class=\"law\"><h3>Momento magn\u00e9tico</h3><div class=\"eq\">\\[ \\mu_d = 0{,}8574\\,\\mu_N \\ne \\mu_p + \\mu_n = 0{,}8798\\,\\mu_N \\]</div><p>Mezcla \\(^3S_1\\) + \\(\\approx4\\%\\ ^3D_1\\).</p></div>\n      <div class=\"law\"><h3>Potencial de Yukawa</h3><div class=\"eq\">\\[ V(r) = -\\frac{g^2}{4\\pi}\\frac{e^{-r/a}}{r},\\qquad a = \\frac{\\hbar}{mc} \\]</div><p>Coulomb es el caso \\(m = 0\\).</p></div>\n      <div class=\"law\"><h3>Dispersi\u00f3n n\u2013p a baja energ\u00eda</h3><div class=\"eq\">\\[ \\sigma = \\pi\\left(3a_t^2 + a_s^2\\right) \\approx 20{,}4\\ \\text{b} \\]</div><p>Longitudes de dispersi\u00f3n: triplete \\(a_t = 5{,}4\\ \\text{fm}\\), singlete \\(a_s = -23{,}7\\ \\text{fm}\\).</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nfu-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>Con un pozo cuadrado de radio \\(R = 2{,}1\\ \\text{fm}\\), \u00bfqu\u00e9 profundidad reproduce \\(B_d = 2{,}224\\ \\text{MeV}\\)? \u00bfCu\u00e1l es la profundidad m\u00ednima para que exista un estado ligado? (Basado en Krane, \u00a74.1.)</b></p>\n      <ol><li>Masa reducida: \\(\\mu c^2 = 938{,}9/2 = 469{,}5\\ \\text{MeV}\\). Entonces \\(\\kappa = \\sqrt{2(469{,}5)(2{,}224)}/197{,}3 = 0{,}2316\\ \\text{fm}^{-1}\\) y \\(\\kappa R = 0{,}486\\).</li><li>Hay que resolver \\(x\\cot x = -0{,}486\\) con \\(x = kR\\). Como el lado derecho es peque\u00f1o, \\(x\\) est\u00e1 apenas por encima de \\(\\pi/2\\): num\u00e9ricamente \\(x = 1{,}830\\).</li><li>\\(k = 1{,}830/2{,}1 = 0{,}8716\\ \\text{fm}^{-1}\\), as\u00ed que \\(V_0 - B = \\dfrac{(\\hbar ck)^2}{2\\mu c^2} = \\dfrac{(172{,}0)^2}{939} = 31{,}5\\ \\text{MeV}\\) y \\(V_0 \\approx 33{,}7\\ \\text{MeV}\\).</li><li>Umbral de ligadura (\\(B \\to 0\\), \\(kR = \\pi/2\\)): \\(V_0^{\\min} = \\dfrac{\\pi^2(\\hbar c)^2}{8\\mu c^2R^2} = \\dfrac{9{,}87(38\\,938)}{8(469{,}5)(4{,}41)} = 23{,}2\\ \\text{MeV}\\).</li></ol>\n      <p>El pozo real es solo un 45 % m\u00e1s profundo que el m\u00ednimo: por eso el deuter\u00f3n no tiene estados excitados y una fuerza algo m\u00e1s d\u00e9bil (el estado singlete) ya no liga.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-enlace\"><small>\u2190 Anterior</small>Masa y energ\u00eda de enlace</a><a class=\"next\" href=\"#np-capas\"><small>Siguiente \u2192</small>Modelo de capas</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, cap. 4 (\u00a74.1\u20134.5). Redacci\u00f3n y simulaciones propias.</p>\n</section>\n<!-- ============ NP \u00b7 CAPAS ============ -->\n<section class=\"view\" data-view=\"np-capas\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad II \u00b7 Modelos nucleares</div>\n  <h1>El modelo de capas</h1>\n  <p class=\"lead\">Ciertos n\u00fameros de protones o neutrones (2, 8, 20, 28, 50, 82, 126) hacen a los n\u00facleos especialmente estables, como los gases nobles en qu\u00edmica. Mayer y Jensen lo explicaron en 1949: cada nucle\u00f3n se mueve en un potencial medio, y un fuerte acoplamiento spin-\u00f3rbita reordena los niveles.</p>\n  <div class=\"toc\"><a href=\"#nca-res\" data-scroll>Resumen</a><a href=\"#nca-lab\" data-scroll>Visualiza</a><a href=\"#nca-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nca-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nca-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>N\u00fameros m\u00e1gicos.</b> Con \\(Z\\) o \\(N\\) igual a 2, 8, 20, 28, 50, 82 o 126 aparecen saltos en las energ\u00edas de separaci\u00f3n, m\u00e1s is\u00f3topos estables, primeros estados excitados muy altos y secciones eficaces de captura de neutrones peque\u00f1as. \\(^{208}\\)Pb (\\(Z = 82\\), \\(N = 126\\)) es doblemente m\u00e1gico.</li>\n      <li><b>Potencial medio.</b> Cada nucle\u00f3n siente el promedio de los dem\u00e1s, por ejemplo un Woods-Saxon \\(V(r) = -V_0/[1+e^{(r-R)/a}]\\). Los niveles se etiquetan \\(n\\ell_j\\) y en cada uno caben \\(2j+1\\) nucleones de cada tipo.</li>\n      <li><b>Oscilador arm\u00f3nico.</b> Aproxima el pozo con \\(E = \\hbar\\omega(N + \\tfrac32)\\) y degeneraci\u00f3n \\((N+1)(N+2)\\). Da capas cerradas en 2, 8, 20, 40, 70, 112: solo acierta las tres primeras.</li>\n      <li><b>Acoplamiento spin-\u00f3rbita.</b> Un t\u00e9rmino \\(V_{so}(r)\\,\\vec\\ell\\cdot\\vec s\\) separa \\(j = \\ell\\pm\\tfrac12\\) en una cantidad proporcional a \\(2\\ell+1\\), con \\(j = \\ell+\\tfrac12\\) m\u00e1s ligado. Los niveles \\(1f_{7/2}\\), \\(1g_{9/2}\\), \\(1h_{11/2}\\) y \\(1i_{13/2}\\) bajan a la capa anterior y producen 28, 50, 82 y 126.</li>\n      <li><b>Estado fundamental.</b> N\u00facleos par-par: \\(J^\\pi = 0^+\\) (los nucleones se aparean). N\u00facleos de \\(A\\) impar: \\(J\\) es el \\(j\\) del nucle\u00f3n desapareado y la paridad es \\(\\pi = (-1)^\\ell\\).</li>\n      <li><b>Momentos magn\u00e9ticos.</b> Para \\(A\\) impar, \\(\\mu = g_j\\,j\\,\\mu_N\\) con el \\(g_j\\) de un solo nucle\u00f3n (l\u00edneas de Schmidt). Los valores medidos caen entre las dos l\u00edneas: el modelo da la tendencia, no el valor exacto.</li>\n      <li><b>L\u00edmites.</b> Funciona cerca de capas cerradas. A medio camino entre ellas muchos nucleones act\u00faan juntos, el n\u00facleo se deforma y hace falta el <a href=\"#np-colectivos\">modelo colectivo</a>.</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nca-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"two\">\n      <div><div class=\"canvas-box\"><canvas id=\"nca-cv\"></canvas></div>\n        <div class=\"controls\">\n          <label class=\"slider\">intensidad spin-\u00f3rbita <input type=\"range\" id=\"nca-s\" min=\"0\" max=\"1\" step=\"0.01\" value=\"1\"><b></b></label>\n          <label class=\"slider\">n\u00famero de nucleones (Z o N) <input type=\"range\" id=\"nca-n\" min=\"1\" max=\"126\" step=\"1\" value=\"9\"><b></b></label>\n        </div></div>\n      <div><div class=\"readout\" id=\"nca-read\"></div>\n        <p class=\"hint\" style=\"margin-top:12px\">Niveles de un oscilador arm\u00f3nico con t\u00e9rmino \\(\\ell^2\\) y spin-\u00f3rbita (parametrizaci\u00f3n esf\u00e9rica de Nilsson). Con intensidad 0 las capas cierran en 2, 8, 20, 40, 70, 112; con intensidad 1 aparecen los n\u00fameros m\u00e1gicos reales. Los c\u00edrculos llenos son los nucleones colocados; el naranja es el \u00faltimo. Se predice \\(J^\\pi\\) para un n\u00facleo con un nucle\u00f3n desapareado de ese tipo.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nca-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Oscilador arm\u00f3nico 3D</h3><div class=\"eq\">\\[ E_N = \\hbar\\omega\\left(N+\\tfrac32\\right),\\quad N = 2(n-1)+\\ell \\]</div><p>Degeneraci\u00f3n con spin: \\((N+1)(N+2)\\). \\(\\hbar\\omega \\approx 41A^{-1/3}\\ \\text{MeV}\\).</p></div>\n      <div class=\"law\"><h3>Valor medio de \u2113\u00b7s</h3><div class=\"eq\">\\[ \\langle\\vec\\ell\\cdot\\vec s\\rangle = \\frac{\\hbar^2}{2}\\left[j(j+1) - \\ell(\\ell+1) - \\tfrac34\\right] \\]</div><p>\\(= \\tfrac{\\ell}{2}\\hbar^2\\) si \\(j = \\ell+\\tfrac12\\); \\(= -\\tfrac{\\ell+1}{2}\\hbar^2\\) si \\(j = \\ell-\\tfrac12\\).</p></div>\n      <div class=\"law\"><h3>Desdoblamiento spin-\u00f3rbita</h3><div class=\"eq\">\\[ \\Delta E_{so} = \\frac{2\\ell+1}{2}\\,\\hbar^2\\,\\langle V_{so}\\rangle \\]</div><p>Crece con \\(\\ell\\): por eso afecta sobre todo a los niveles altos.</p></div>\n      <div class=\"law\"><h3>Esp\u00edn y paridad</h3><div class=\"eq\">\\[ J = j_{\\text{\u00faltimo}},\\qquad \\pi = (-1)^{\\ell} \\]</div><p>Para \\(A\\) impar. Un hueco en un nivel lleno da el mismo \\(j^\\pi\\) que una part\u00edcula.</p></div>\n      <div class=\"law\"><h3>L\u00edneas de Schmidt</h3><div class=\"eq\">\\[ \\mu = \\begin{cases} \\left[g_\\ell(j-\\tfrac12) + \\tfrac12g_s\\right]\\mu_N & j = \\ell+\\tfrac12\\\\[2pt] \\left[g_\\ell\\frac{j(j+\\frac32)}{j+1} - \\frac{g_s}{2(j+1)}\\,j\\right]\\mu_N & j = \\ell-\\tfrac12 \\end{cases} \\]</div><p>Prot\u00f3n: \\(g_\\ell = 1\\), \\(g_s = 5{,}586\\). Neutr\u00f3n: \\(g_\\ell = 0\\), \\(g_s = -3{,}826\\).</p></div>\n      <div class=\"law\"><h3>Capas con spin-\u00f3rbita</h3><div class=\"eq\">\\[ 2,\\ 8,\\ 20,\\ 28,\\ 50,\\ 82,\\ 126 \\]</div><p>Cada n\u00famero cierra un grupo de niveles separado por un hueco grande del siguiente.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nca-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>Predice el esp\u00edn y la paridad del estado fundamental de \\(^{17}\\)O y de \\(^{41}\\)Ca. (Basado en Krane, \u00a75.1.)</b></p>\n      <ol><li>Orden de llenado: \\(1s_{1/2}\\,(2)\\), \\(1p_{3/2}\\,(4)\\), \\(1p_{1/2}\\,(2)\\) \u2192 8; \\(1d_{5/2}\\,(6)\\), \\(2s_{1/2}\\,(2)\\), \\(1d_{3/2}\\,(4)\\) \u2192 20; \\(1f_{7/2}\\,(8)\\) \u2192 28.</li><li>\\(^{17}\\)O: \\(Z = 8\\) (capa cerrada, aporta \\(0^+\\)) y \\(N = 9\\). El noveno neutr\u00f3n va al \\(1d_{5/2}\\): \\(\\ell = 2\\), \\(j = 5/2\\), \\(\\pi = (-1)^2 = +\\). Predicci\u00f3n: \\(5/2^+\\). Medido: \\(5/2^+\\). \u2713</li><li>\\(^{41}\\)Ca: \\(Z = 20\\) (cerrada) y \\(N = 21\\). El neutr\u00f3n 21 abre el \\(1f_{7/2}\\): \\(\\ell = 3\\), \\(\\pi = -\\). Predicci\u00f3n: \\(7/2^-\\). Medido: \\(7/2^-\\). \u2713</li><li>Momento magn\u00e9tico de \\(^{17}\\)O (neutr\u00f3n, \\(j = \\ell+\\tfrac12\\)): \\(\\mu = \\tfrac12g_s\\mu_N = -1{,}91\\,\\mu_N\\). Medido: \\(-1{,}89\\,\\mu_N\\).</li></ol>\n      <p>Que \\(1f_{7/2}\\) forme una capa propia (hasta 28) es la huella directa del acoplamiento spin-\u00f3rbita: sin \u00e9l, \\(1f\\) y \\(2p\\) estar\u00edan en la misma capa hasta 40.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-fuerza\"><small>\u2190 Anterior</small>Fuerza nuclear y deuter\u00f3n</a><a class=\"next\" href=\"#np-colectivos\"><small>Siguiente \u2192</small>Modelos colectivos</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, cap. 5 (\u00a75.1). Niveles: oscilador modificado de Nilsson con \\(\\kappa = 0{,}0637\\). Redacci\u00f3n y simulaciones propias.</p>\n</section>\n\n<!-- ============ NP \u00b7 COLECTIVOS ============ -->\n<section class=\"view\" data-view=\"np-colectivos\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad II \u00b7 Modelos nucleares</div>\n  <h1>Modelos colectivos: vibraciones y rotaciones</h1>\n  <p class=\"lead\">Lejos de las capas cerradas, los espectros de los n\u00facleos par-par se ven como los de una gota que vibra o un trompo que gira. Muchos nucleones se mueven coherentemente, y la forma del n\u00facleo pasa a ser una variable din\u00e1mica.</p>\n  <div class=\"toc\"><a href=\"#nco-res\" data-scroll>Resumen</a><a href=\"#nco-lab\" data-scroll>Visualiza</a><a href=\"#nco-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nco-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nco-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Deformaci\u00f3n.</b> Para \\(150 < A < 190\\) y \\(A > 220\\) los n\u00facleos son elipsoides de revoluci\u00f3n: \\(R(\\theta) = R_{\\text{av}}[1+\\beta Y_{20}(\\theta)]\\). Su momento cuadrupolar intr\u00ednseco es \\(Q_0 = \\frac{3}{\\sqrt{5\\pi}}R_{\\text{av}}^2Z\\beta\\,(1+0{,}16\\beta)\\).</li>\n      <li><b>Vibraciones.</b> Cerca de capas cerradas el n\u00facleo es esf\u00e9rico pero su superficie oscila. El cuanto cuadrupolar (\\(\\lambda = 2\\)) es un estado \\(2^+\\); dos cuantos forman un triplete \\(0^+, 2^+, 4^+\\) a casi el doble de energ\u00eda: \\(E(4^+)/E(2^+) \\approx 2\\).</li>\n      <li><b>Rotaciones.</b> Un n\u00facleo deformado gira de forma colectiva: \\(E_J = \\dfrac{\\hbar^2}{2\\mathcal I}J(J+1)\\) con \\(J = 0, 2, 4, \\dots\\) (la simetr\u00eda de reflexi\u00f3n excluye \\(J\\) impares). Entonces \\(E(4^+)/E(2^+) = 20/6 = 3{,}33\\).</li>\n      <li><b>Momento de inercia.</b> El medido est\u00e1 entre el de un s\u00f3lido r\u00edgido, \\(\\mathcal I_{\\text{rig}} = \\tfrac25AmR^2(1+0{,}31\\beta)\\), y el de un fluido irrotacional, \\(\\mathcal I_{\\text{irr}} = \\frac{9}{8\\pi}AmR^2\\beta^2\\). La materia nuclear es en parte superfluida (apareamiento).</li>\n      <li><b>Transiciones E2.</b> Dentro de una banda los rayos \u03b3 son \\(E2\\) con \\(\\Delta J = 2\\) y energ\u00edas \\(\\frac{\\hbar^2}{2\\mathcal I}(4J-2)\\), que crecen linealmente. Son decenas de veces m\u00e1s r\u00e1pidas que las de un solo nucle\u00f3n: prueba de movimiento colectivo.</li>\n      <li><b>M\u00e1s all\u00e1 del rotor r\u00edgido.</b> A alto \\(J\\) el n\u00facleo se estira (fuerza centr\u00edfuga) y \\(\\mathcal I\\) crece. A veces el apareamiento se rompe y \\(\\mathcal I\\) salta (<i>backbending</i>).</li>\n      <li><b>Modelo de Nilsson.</b> Une las dos im\u00e1genes: nucleones independientes en un pozo deformado. Los niveles de capas se desdoblan seg\u00fan la proyecci\u00f3n \\(K\\) de \\(j\\) sobre el eje de simetr\u00eda.</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nco-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"forma\" class=\"on\">Forma del n\u00facleo</button><button data-t=\"esp\">Espectros: vibrador frente a rotor</button></div>\n    <div class=\"tabpane on\" data-pane=\"forma\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nco-cv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">\u03b2\u2082 <input type=\"range\" id=\"nco-b\" min=\"-0.4\" max=\"0.6\" step=\"0.01\" value=\"0.28\"><b></b></label>\n            <label class=\"slider\">A <input type=\"range\" id=\"nco-A\" min=\"100\" max=\"250\" step=\"1\" value=\"238\"><b></b></label>\n            <label class=\"np-chk\"><input type=\"checkbox\" id=\"nco-rot\" checked> girar</label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nco-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Corte del n\u00facleo \\(R(\\theta) = R_{\\text{av}}[1+\\beta Y_{20}]\\). \\(\\beta > 0\\): prolato (cigarro); \\(\\beta < 0\\): oblato (disco). El c\u00edrculo gris es la esfera del mismo volumen. Al girar alrededor de un eje perpendicular al de simetr\u00eda se forma la banda rotacional.</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"esp\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nco-ev\"></canvas></div>\n          <div class=\"controls\"><select class=\"np-sel\" id=\"nco-nuc\"></select></div></div>\n        <div><div class=\"readout\" id=\"nco-eread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Izquierda: niveles medidos del n\u00facleo elegido. Centro: predicci\u00f3n del rotor con \\(\\hbar^2/2\\mathcal I = E(2^+)/6\\). Derecha: predicci\u00f3n del vibrador. La raz\u00f3n \\(R_{4/2} = E(4^+)/E(2^+)\\) dice qu\u00e9 imagen se aplica.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nco-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Superficie deformada</h3><div class=\"eq\">\\[ R(\\theta,\\phi) = R_{\\text{av}}\\Big[1+\\sum_{\\lambda\\mu}\\alpha_{\\lambda\\mu}Y_{\\lambda\\mu}(\\theta,\\phi)\\Big] \\]</div><p>Deformaci\u00f3n axial cuadrupolar: \\(\\alpha_{20} = \\beta\\).</p></div>\n      <div class=\"law\"><h3>Banda rotacional</h3><div class=\"eq\">\\[ E_J = \\frac{\\hbar^2}{2\\mathcal I}\\,J(J+1),\\quad J = 0,2,4,\\dots \\]</div><p>\\(E_4/E_2 = 10/3\\), \\(E_6/E_2 = 7\\), \\(E_8/E_2 = 12\\).</p></div>\n      <div class=\"law\"><h3>Vibrador arm\u00f3nico</h3><div class=\"eq\">\\[ E_n = n\\,\\hbar\\omega_2,\\qquad E(4^+)/E(2^+) = 2 \\]</div><p>Con dos fonones: triplete \\(0^+, 2^+, 4^+\\).</p></div>\n      <div class=\"law\"><h3>Momento de inercia r\u00edgido</h3><div class=\"eq\">\\[ \\mathcal I_{\\text{rig}} = \\tfrac25AmR_{\\text{av}}^2\\,(1+0{,}31\\beta) \\]</div><p>S\u00f3lido uniforme. El valor medido es \\(\\approx 0{,}3\\)\u2013\\(0{,}5\\,\\mathcal I_{\\text{rig}}\\).</p></div>\n      <div class=\"law\"><h3>Momento cuadrupolar intr\u00ednseco</h3><div class=\"eq\">\\[ Q_0 = \\frac{3}{\\sqrt{5\\pi}}R_{\\text{av}}^2Z\\beta\\,(1+0{,}16\\beta) \\]</div><p>El observado en el laboratorio para un estado \\(J\\) es menor por promediar la rotaci\u00f3n.</p></div>\n      <div class=\"law\"><h3>Energ\u00eda de las transiciones</h3><div class=\"eq\">\\[ E_\\gamma(J\\to J-2) = \\frac{\\hbar^2}{2\\mathcal I}(4J-2) \\]</div><p>Espaciado constante entre rayos \u03b3 sucesivos: \\(8\\,\\hbar^2/2\\mathcal I\\).</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nco-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>El primer estado \\(2^+\\) de \\(^{238}\\)U est\u00e1 a 44,9 keV. Halla \\(\\hbar^2/2\\mathcal I\\), predice \\(E(4^+)\\) y compara \\(\\mathcal I\\) con el de un s\u00f3lido r\u00edgido. (Basado en Krane, \u00a75.2.)</b></p>\n      <ol><li>\\(E(2^+) = 6\\,\\dfrac{\\hbar^2}{2\\mathcal I}\\Rightarrow \\dfrac{\\hbar^2}{2\\mathcal I} = 7{,}48\\ \\text{keV}\\).</li><li>\\(E(4^+) = 20(7{,}48) = 149{,}7\\ \\text{keV}\\). Medido: 148,4 keV (diferencia 0,9 %).</li><li>S\u00f3lido r\u00edgido esf\u00e9rico: \\(R = 1{,}2(238)^{1/3} = 7{,}44\\ \\text{fm}\\), \\(Amc^2 = 238(931{,}5) = 2{,}217\\times10^5\\ \\text{MeV}\\). \\(\\dfrac{\\hbar^2}{2\\mathcal I_{\\text{rig}}} = \\dfrac{(\\hbar c)^2}{2\\cdot\\tfrac25Amc^2R^2} = \\dfrac{38\\,938}{9{,}81\\times10^6}\\ \\text{MeV} = 3{,}97\\ \\text{keV}\\).</li><li>\\(\\mathcal I_{\\exp}/\\mathcal I_{\\text{rig}} = 3{,}97/7{,}48 = 0{,}53\\).</li></ol>\n      <p>El n\u00facleo gira con la mitad de la inercia de un s\u00f3lido: parte de los nucleones (los apareados) no acompa\u00f1a la rotaci\u00f3n, como en un superfluido.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-capas\"><small>\u2190 Anterior</small>Modelo de capas</a><a class=\"next\" href=\"#np-decaimiento\"><small>Siguiente \u2192</small>Ley de decaimiento</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, cap. 5 (\u00a75.2\u20135.3). Energ\u00edas de niveles: NNDC/ENSDF. Redacci\u00f3n y simulaciones propias.</p>\n</section>\n<!-- ============ NP \u00b7 DECAIMIENTO ============ -->\n<section class=\"view\" data-view=\"np-decaimiento\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad III \u00b7 Desintegraci\u00f3n radiactiva</div>\n  <h1>Ley de decaimiento radiactivo y cadenas</h1>\n  <p class=\"lead\">Ning\u00fan n\u00facleo \"envejece\": la probabilidad de que se desintegre en el pr\u00f3ximo segundo es siempre la misma. De esa sola hip\u00f3tesis salen la ley exponencial, las cadenas de desintegraci\u00f3n y los relojes radiom\u00e9tricos que fechan rocas, f\u00f3siles y el sistema solar.</p>\n  <div class=\"toc\"><a href=\"#nde-res\" data-scroll>Resumen</a><a href=\"#nde-lab\" data-scroll>Visualiza</a><a href=\"#nde-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nde-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nde-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Ley exponencial.</b> Si cada n\u00facleo tiene probabilidad \\(\\lambda\\,dt\\) de desintegrarse en \\(dt\\), entonces \\(dN/dt = -\\lambda N\\) y \\(N(t) = N_0e^{-\\lambda t}\\). Vida media \\(\\tau = 1/\\lambda\\); per\u00edodo de semidesintegraci\u00f3n \\(t_{1/2} = \\ln2/\\lambda\\).</li>\n      <li><b>Actividad.</b> \\(\\mathcal A = \\lambda N\\) desintegraciones por segundo. Unidades: becquerel (1 Bq = 1 s\u207b\u00b9) y curie (1 Ci = \\(3{,}7\\times10^{10}\\) Bq, la actividad de 1 g de \\(^{226}\\)Ra).</li>\n      <li><b>Estad\u00edstica.</b> Cada n\u00facleo decae al azar: el n\u00famero de cuentas en un intervalo sigue una distribuci\u00f3n de Poisson con \\(\\sigma = \\sqrt{\\bar n}\\). Con pocos n\u00facleos la curva exponencial solo se ve en promedio.</li>\n      <li><b>Cadenas (Bateman).</b> En \\(A\\to B\\to C\\): \\(\\dot N_B = \\lambda_AN_A - \\lambda_BN_B\\). Con \\(N_B(0) = 0\\), \\(N_B = \\dfrac{\\lambda_AN_{A0}}{\\lambda_B-\\lambda_A}\\big(e^{-\\lambda_At} - e^{-\\lambda_Bt}\\big)\\), que crece, alcanza un m\u00e1ximo y luego decae.</li>\n      <li><b>Equilibrios.</b> Si el padre vive mucho m\u00e1s (\\(\\lambda_A \\ll \\lambda_B\\)), tras unos \\(t_{1/2,B}\\) las actividades se igualan, \\(\\mathcal A_B = \\mathcal A_A\\) (equilibrio secular: serie del uranio). Si viven parecido, \\(\\mathcal A_B/\\mathcal A_A = \\lambda_B/(\\lambda_B-\\lambda_A)\\) (equilibrio transitorio).</li>\n      <li><b>Dataci\u00f3n.</b> Con \\(P\\) padres y \\(D\\) hijos radiog\u00e9nicos: \\(t = \\dfrac{1}{\\lambda}\\ln\\left(1+\\dfrac{D}{P}\\right)\\). El \\(^{14}\\)C (\\(t_{1/2} = 5730\\) a\u00f1os) fecha restos org\u00e1nicos; U\u2013Pb y Rb\u2013Sr, rocas de miles de millones de a\u00f1os.</li>\n      <li><b>Producci\u00f3n.</b> Si una fuente produce n\u00facleos a ritmo \\(R\\) constante (activaci\u00f3n en un reactor), \\(N(t) = \\frac{R}{\\lambda}(1-e^{-\\lambda t})\\): irradiar m\u00e1s de unos pocos \\(t_{1/2}\\) no sirve.</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nde-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"cad\" class=\"on\">Cadena A \u2192 B \u2192 C</button><button data-t=\"mc\">N\u00facleos al azar</button></div>\n    <div class=\"tabpane on\" data-pane=\"cad\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nde-cv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">log\u2081\u2080 t\u00bd(A) <input type=\"range\" id=\"nde-ta\" min=\"-1\" max=\"3\" step=\"0.01\" value=\"1.82\"><b></b></label>\n            <label class=\"slider\">log\u2081\u2080 t\u00bd(B) <input type=\"range\" id=\"nde-tb\" min=\"-1\" max=\"3\" step=\"0.01\" value=\"0.78\"><b></b></label>\n            <div class=\"seg\" id=\"nde-q\"><button data-q=\"n\" class=\"on\">N\u00famero N</button><button data-q=\"a\">Actividad \ud835\udc9c</button></div>\n          </div></div>\n        <div><div class=\"readout\" id=\"nde-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Tiempos en horas. Los valores iniciales son el generador m\u00e9dico \\(^{99}\\)Mo (66 h) \u2192 \\(^{99m}\\)Tc (6,0 h) \u2192 \\(^{99}\\)Tc. La l\u00ednea punteada marca el m\u00e1ximo de \\(N_B\\). Prueba \\(t_{1/2,A} \\gg t_{1/2,B}\\) para ver el equilibrio secular y \\(t_{1/2,A} < t_{1/2,B}\\) para ver que no hay equilibrio.</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"mc\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nde-mv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">N\u2080 <input type=\"range\" id=\"nde-n0\" min=\"20\" max=\"900\" step=\"10\" value=\"400\"><b></b></label>\n            <label class=\"slider\">t\u00bd (s) <input type=\"range\" id=\"nde-th\" min=\"1\" max=\"20\" step=\"0.5\" value=\"5\"><b></b></label>\n            <button class=\"btn\" id=\"nde-go\">Reiniciar</button>\n          </div></div>\n        <div><div class=\"readout\" id=\"nde-mread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Cada cuadradito es un n\u00facleo; en cada paso se desintegra con probabilidad \\(\\lambda\\,\\Delta t\\), sin memoria. La gr\u00e1fica compara el n\u00famero sobreviviente (azul) con \\(N_0e^{-\\lambda t}\\) (gris) y la banda \\(\\pm\\sqrt N\\).</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nde-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Ley de desintegraci\u00f3n</h3><div class=\"eq\">\\[ N(t) = N_0e^{-\\lambda t},\\qquad t_{1/2} = \\frac{\\ln2}{\\lambda} = \\tau\\ln2 \\]</div><p>Actividad \\(\\mathcal A = \\lambda N = \\mathcal A_0e^{-\\lambda t}\\).</p></div>\n      <div class=\"law\"><h3>Ecuaciones de Bateman</h3><div class=\"eq\">\\[ N_B(t) = \\frac{\\lambda_AN_{A0}}{\\lambda_B-\\lambda_A}\\left(e^{-\\lambda_At}-e^{-\\lambda_Bt}\\right) \\]</div><p>Con \\(N_B(0) = 0\\). Forma general para \\(n\\) eslabones: suma de exponenciales.</p></div>\n      <div class=\"law\"><h3>M\u00e1ximo del hijo</h3><div class=\"eq\">\\[ t_{\\max} = \\frac{\\ln(\\lambda_B/\\lambda_A)}{\\lambda_B - \\lambda_A} \\]</div><p>En ese instante \\(\\mathcal A_B = \\mathcal A_A\\).</p></div>\n      <div class=\"law\"><h3>Equilibrio secular</h3><div class=\"eq\">\\[ \\lambda_AN_A = \\lambda_BN_B = \\lambda_CN_C = \\cdots \\]</div><p>Si \\(\\lambda_A \\ll\\) todas las dem\u00e1s.</p></div>\n      <div class=\"law\"><h3>Dataci\u00f3n radiom\u00e9trica</h3><div class=\"eq\">\\[ t = \\frac{1}{\\lambda}\\ln\\!\\left(1+\\frac{D}{P}\\right) \\]</div><p>Para \\(^{14}\\)C: \\(t = \\frac{t_{1/2}}{\\ln2}\\ln\\frac{\\mathcal A_0}{\\mathcal A}\\).</p></div>\n      <div class=\"law\"><h3>Estad\u00edstica de Poisson</h3><div class=\"eq\">\\[ P(n) = \\frac{\\bar n^{\\,n}e^{-\\bar n}}{n!},\\qquad \\sigma = \\sqrt{\\bar n} \\]</div><p>V\u00e1lida si la probabilidad por n\u00facleo es peque\u00f1a y hay muchos n\u00facleos.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nde-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>Un generador de \\(^{99m}\\)Tc contiene \\(^{99}\\)Mo puro (\\(t_{1/2} = 66\\) h). \u00bfCu\u00e1ndo es m\u00e1xima la cantidad de \\(^{99m}\\)Tc (\\(t_{1/2} = 6{,}0\\) h)? (Basado en Krane, \u00a76.4.)</b></p>\n      <ol><li>Constantes: \\(\\lambda_A = \\ln2/66 = 0{,}01050\\ \\text{h}^{-1}\\), \\(\\lambda_B = \\ln2/6{,}0 = 0{,}1155\\ \\text{h}^{-1}\\).</li><li>Derivando \\(N_B(t)\\) e igualando a cero: \\(\\lambda_Ae^{-\\lambda_At} = \\lambda_Be^{-\\lambda_Bt}\\), as\u00ed que \\(t_{\\max} = \\dfrac{\\ln(\\lambda_B/\\lambda_A)}{\\lambda_B-\\lambda_A} = \\dfrac{\\ln 11}{0{,}1050}\\).</li><li>\\(t_{\\max} = 2{,}398/0{,}1050 = 22{,}8\\ \\text{h}\\).</li><li>Despu\u00e9s se llega al equilibrio transitorio: \\(\\mathcal A_B/\\mathcal A_A = \\lambda_B/(\\lambda_B-\\lambda_A) = 1{,}10\\) (sin contar que en la pr\u00e1ctica solo un 88 % del Mo pasa por el estado metaestable).</li></ol>\n      <p>Por eso los hospitales \"orde\u00f1an\" el generador una vez al d\u00eda: cada ~23 h el tecnecio vuelve a su m\u00e1ximo.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-colectivos\"><small>\u2190 Anterior</small>Modelos colectivos</a><a class=\"next\" href=\"#np-alfa\"><small>Siguiente \u2192</small>Desintegraci\u00f3n alfa</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, cap. 6 (\u00a76.1\u20136.7). Redacci\u00f3n y simulaciones propias.</p>\n</section>\n\n<!-- ============ NP \u00b7 ALFA ============ -->\n<section class=\"view\" data-view=\"np-alfa\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad III \u00b7 Desintegraci\u00f3n radiactiva</div>\n  <h1>Desintegraci\u00f3n alfa y el efecto t\u00fanel</h1>\n  <p class=\"lead\">Las energ\u00edas de las part\u00edculas \u03b1 var\u00edan solo entre 4 y 9 MeV, pero sus vidas medias van de microsegundos a miles de millones de a\u00f1os. Gamow, y en paralelo Gurney y Condon, lo explicaron en 1928 con una de las primeras aplicaciones de la mec\u00e1nica cu\u00e1ntica: el efecto t\u00fanel a trav\u00e9s de la barrera de Coulomb.</p>\n  <div class=\"toc\"><a href=\"#nal-res\" data-scroll>Resumen</a><a href=\"#nal-lab\" data-scroll>Visualiza</a><a href=\"#nal-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nal-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nal-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Valor Q.</b> \\(^A_Z\\text{X}\\to\\,^{A-4}_{Z-2}\\text{Y} + \\alpha\\) con \\(Q = [m(\\text{X}) - m(\\text{Y}) - m(^4\\text{He})]c^2\\). Como el retroceso se lleva parte: \\(T_\\alpha = Q\\,\\dfrac{A-4}{A}\\).</li>\n      <li><b>Por qu\u00e9 \u03b1.</b> El \\(^4\\)He est\u00e1 muy ligado (28,3 MeV), as\u00ed que para \\(A \\gtrsim 150\\) la emisi\u00f3n \u03b1 tiene \\(Q > 0\\). Emitir un prot\u00f3n, un deuter\u00f3n o un \\(^{12}\\)C casi nunca es posible o es mucho m\u00e1s lento.</li>\n      <li><b>La barrera.</b> Fuera del n\u00facleo la \u03b1 siente \\(V(r) = \\dfrac{2Z'e^2}{4\\pi\\varepsilon_0r}\\) (\\(Z'\\) del hijo), unos 30 MeV en \\(r = R\\), muy por encima de \\(Q\\). Cl\u00e1sicamente no podr\u00eda salir; sale por <a class=\"kw\" href=\"#t-tunel\">efecto t\u00fanel</a> entre \\(R\\) y \\(b = 2Z'e^2/(4\\pi\\varepsilon_0Q)\\).</li>\n      <li><b>Factor de Gamow.</b> La probabilidad de cruzar en cada intento es \\(P = e^{-2G}\\) con \\(G = \\frac{1}{\\hbar}\\int_R^b\\sqrt{2m[V(r)-Q]}\\,dr\\). Como \\(G\\) est\u00e1 en el exponente y \\(G\\sim 20\\)\u2013\\(45\\), un peque\u00f1o cambio de \\(Q\\) cambia \\(P\\) en muchos \u00f3rdenes.</li>\n      <li><b>Ritmo de desintegraci\u00f3n.</b> \\(\\lambda = f\\,P\\), donde \\(f \\approx v/2R \\sim 10^{21}\\ \\text{s}^{-1}\\) es la frecuencia con que la \u03b1 golpea la pared. Esta estimaci\u00f3n acierta \\(t_{1/2}\\) dentro de un orden de magnitud en un rango de 24 \u00f3rdenes.</li>\n      <li><b>Geiger\u2013Nuttall.</b> Para una cadena de is\u00f3topos, \\(\\log t_{1/2} \\approx a\\,\\dfrac{Z'}{\\sqrt{Q}} + b\\): recta descubierta en 1911 y explicada por Gamow.</li>\n      <li><b>Estructura fina.</b> Si el hijo tiene estados excitados accesibles, hay varios grupos de \u03b1. El m\u00e1s intenso suele ir al estado fundamental (mayor \\(Q\\)); llevar momento angular \\(\\ell\\) a\u00f1ade una barrera centr\u00edfuga \\(\\ell(\\ell+1)\\hbar^2/2mr^2\\).</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nal-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"bar\" class=\"on\">Barrera y t\u00fanel</button><button data-t=\"gn\">Geiger\u2013Nuttall</button></div>\n    <div class=\"tabpane on\" data-pane=\"bar\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nal-cv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">Z del padre <input type=\"range\" id=\"nal-Z\" min=\"60\" max=\"100\" step=\"1\" value=\"92\"><b></b></label>\n            <label class=\"slider\">A del padre <input type=\"range\" id=\"nal-A\" min=\"140\" max=\"260\" step=\"1\" value=\"238\"><b></b></label>\n            <label class=\"slider\">Q (MeV) <input type=\"range\" id=\"nal-Q\" min=\"2\" max=\"10\" step=\"0.01\" value=\"4.27\"><b></b></label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nal-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Negro: pozo nuclear (\\(-V_0 = -35\\) MeV) y barrera de Coulomb. Naranja: energ\u00eda \\(Q\\). Azul: la funci\u00f3n de onda, oscilante dentro, decreciente bajo la barrera y oscilante (con amplitud diminuta, exagerada aqu\u00ed) fuera. El tiempo es una estimaci\u00f3n de orden de magnitud.</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"gn\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nal-gv\"></canvas></div></div>\n        <div><div class=\"readout\" id=\"nal-gread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Puntos: 14 emisores \u03b1 medidos (NNDC). L\u00edneas: teor\u00eda de Gamow para \\(Z'=82\\) (Po) y \\(Z'=90\\) (U). Los n\u00facleos par-par caen sobre las curvas; los de \\(A\\) impar (\\(^{241}\\)Am, \\(^{239}\\)Pu) quedan por encima: est\u00e1n \"impedidos\" porque la \u03b1 arrastra momento angular.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nal-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Energ\u00eda de la part\u00edcula \u03b1</h3><div class=\"eq\">\\[ T_\\alpha = Q\\,\\frac{A-4}{A},\\qquad T_Y = Q\\,\\frac{4}{A} \\]</div><p>Conservaci\u00f3n de momento en un desintegraci\u00f3n a dos cuerpos (no relativista).</p></div>\n      <div class=\"law\"><h3>Altura y anchura de la barrera</h3><div class=\"eq\">\\[ V(R) = \\frac{2Z'(1{,}44\\ \\text{MeV fm})}{R},\\qquad b = \\frac{2Z'(1{,}44\\ \\text{MeV fm})}{Q} \\]</div><p>\\(R \\approx 1{,}2(A'^{1/3} + 4^{1/3})\\) fm.</p></div>\n      <div class=\"law\"><h3>Factor de Gamow</h3><div class=\"eq\">\\[ G = \\sqrt{\\frac{2mQ}{\\hbar^2}}\\;b\\left[\\arccos\\sqrt{x} - \\sqrt{x(1-x)}\\right],\\quad x = \\frac{R}{b} \\]</div><p>Para \\(x \\ll 1\\): \\(G \\approx \\frac{\\pi}{2}\\sqrt{\\frac{2mQ}{\\hbar^2}}\\,b - 2\\sqrt{\\frac{2mQ}{\\hbar^2}}\\sqrt{Rb}\\).</p></div>\n      <div class=\"law\"><h3>Ritmo de desintegraci\u00f3n</h3><div class=\"eq\">\\[ \\lambda = \\frac{v}{2R}\\,e^{-2G},\\qquad t_{1/2} = \\frac{\\ln2}{\\lambda} \\]</div><p>\\(v = \\sqrt{2(Q+V_0)/m}\\) dentro del pozo.</p></div>\n      <div class=\"law\"><h3>Ley de Geiger\u2013Nuttall</h3><div class=\"eq\">\\[ \\log_{10}t_{1/2} = a\\,\\frac{Z'}{\\sqrt{Q}} + b \\]</div><p>Consecuencia directa del t\u00e9rmino dominante \\(\\propto Z'/\\sqrt Q\\) de \\(G\\).</p></div>\n      <div class=\"law\"><h3>Barrera centr\u00edfuga</h3><div class=\"eq\">\\[ V_\\ell(r) = \\frac{\\ell(\\ell+1)\\hbar^2}{2mr^2} \\]</div><p>Paridad: \\(\\pi_i = \\pi_f(-1)^\\ell\\). Cada unidad de \\(\\ell\\) frena la emisi\u00f3n.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nal-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>Compara \\(^{238}\\)U (\\(Q = 4{,}27\\) MeV) con \\(^{212}\\)Po (\\(Q = 8{,}95\\) MeV) usando la teor\u00eda de Gamow. (Basado en Krane, \u00a78.4.)</b></p>\n      <ol><li>\\(^{238}\\)U: hijo \\(Z' = 90\\), \\(A' = 234\\). \\(R = 1{,}2(6{,}16+1{,}59) = 9{,}3\\ \\text{fm}\\), \\(b = 2(90)(1{,}44)/4{,}27 = 60{,}7\\ \\text{fm}\\), \\(x = 0{,}153\\).</li><li>Con \\(mc^2 = 3727(234/238) = 3664\\ \\text{MeV}\\): \\(\\sqrt{2mc^2Q}/\\hbar c = \\sqrt{2(3664)(4{,}27)}/197{,}3 = 0{,}899\\ \\text{fm}^{-1}\\). \\(G = 0{,}899(60{,}7)[\\arccos(0{,}391) - \\sqrt{0{,}153(0{,}847)}] = 54{,}6(1{,}169 - 0{,}360) = 44{,}0\\).</li><li>\\(e^{-2G} = e^{-88} \\approx 6\\times10^{-39}\\). Con \\(f = v/2R \\approx 2{,}4\\times10^{21}\\ \\text{s}^{-1}\\) (\\(v = 0{,}146c\\)): \\(t_{1/2} \\approx 5\\times10^{16}\\ \\text{s} \\approx 1{,}5\\times10^9\\) a\u00f1os. Medido: \\(4{,}5\\times10^9\\) a\u00f1os.</li><li>\\(^{212}\\)Po (hijo \\(Z' = 82\\)): \\(b = 26{,}4\\) fm, \\(G = 16{,}1\\), \\(e^{-2G} \\approx 10^{-14}\\). Resulta \\(t_{1/2} \\approx 3\\times10^{-8}\\) s. Medido: \\(3\\times10^{-7}\\) s.</li></ol>\n      <p>Duplicar \\(Q\\) cambia la vida media en 23 \u00f3rdenes de magnitud, y una teor\u00eda con un solo par\u00e1metro libre (\\(R_0\\)) lo reproduce a menos de un orden.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-decaimiento\"><small>\u2190 Anterior</small>Ley de decaimiento</a><a class=\"next\" href=\"#np-beta\"><small>Siguiente \u2192</small>Desintegraci\u00f3n beta</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, cap. 8 (\u00a78.1\u20138.6). Datos: NNDC. Redacci\u00f3n y simulaciones propias.</p>\n</section>\n\n<!-- ============ NP \u00b7 BETA ============ -->\n<section class=\"view\" data-view=\"np-beta\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad III \u00b7 Desintegraci\u00f3n radiactiva</div>\n  <h1>Desintegraci\u00f3n beta y el neutrino</h1>\n  <p class=\"lead\">En la desintegraci\u00f3n \u03b2 un neutr\u00f3n se convierte en prot\u00f3n (o al rev\u00e9s) y se crean un electr\u00f3n y un antineutrino. El espectro continuo de los electrones llev\u00f3 a Pauli a postular el neutrino en 1930, y a Fermi a escribir en 1934 la primera teor\u00eda de la interacci\u00f3n d\u00e9bil.</p>\n  <div class=\"toc\"><a href=\"#nbe-res\" data-scroll>Resumen</a><a href=\"#nbe-lab\" data-scroll>Visualiza</a><a href=\"#nbe-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nbe-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nbe-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Tres procesos.</b> \\(\\beta^-\\): \\(n\\to p+e^-+\\bar\\nu_e\\). \\(\\beta^+\\): \\(p\\to n+e^++\\nu_e\\) (solo dentro de un n\u00facleo). Captura electr\u00f3nica: \\(p+e^-\\to n+\\nu_e\\). Los tres cambian \\(Z\\) en una unidad con \\(A\\) fijo.</li>\n      <li><b>Valores Q.</b> Con masas at\u00f3micas: \\(Q_{\\beta^-} = [m(\\text{X})-m(\\text{Y})]c^2\\); \\(Q_{\\beta^+} = [m(\\text{X})-m(\\text{Y})-2m_e]c^2\\); \\(Q_{CE} = [m(\\text{X})-m(\\text{Y})]c^2 - B_e\\). Si la diferencia de masas es menor que \\(2m_ec^2\\), solo hay captura.</li>\n      <li><b>El neutrino.</b> Si solo saliera el electr\u00f3n, tendr\u00eda una energ\u00eda fija. El espectro continuo de 0 a \\(Q\\) (y la conservaci\u00f3n del momento angular) exigen una tercera part\u00edcula neutra y casi sin masa. Se detect\u00f3 en 1956 (Cowan y Reines).</li>\n      <li><b>Regla de oro de Fermi.</b> \\(\\lambda = \\dfrac{2\\pi}{\\hbar}|V_{fi}|^2\\rho(E_f)\\): el ritmo es el cuadrado del elemento de matriz por la densidad de estados finales. Para tres cuerpos, el espacio de fases da la forma del espectro.</li>\n      <li><b>Espectro y Kurie.</b> \\(N(p)\\,dp \\propto F(Z',p)\\,p^2(Q-T)^2\\,dp\\). Graficando \\(\\sqrt{N/(p^2F)}\\) frente a \\(T\\) se obtiene una recta que corta el eje en \\(Q\\) (gr\u00e1fico de Kurie). Una masa del neutrino curva el extremo.</li>\n      <li><b>Valores ft.</b> Integrando el espectro, \\(\\lambda \\propto |M_{fi}|^2f(Z',Q)\\) con \\(f \\propto Q^5\\) (regla de Sargent). El producto \\(ft_{1/2}\\) solo depende del elemento de matriz: \\(\\log ft \\approx 3{,}5\\) (superpermitidas), 4\u20137 (permitidas), mayor (prohibidas).</li>\n      <li><b>Reglas de selecci\u00f3n.</b> Permitidas (\\(\\ell = 0\\)): sin cambio de paridad. Fermi (spins e\u2013\u03bd antiparalelos): \\(\\Delta J = 0\\). Gamow\u2013Teller (paralelos): \\(\\Delta J = 0, \\pm1\\), sin \\(0\\to0\\).</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nbe-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"esp\" class=\"on\">Espectro</button><button data-t=\"kur\">Gr\u00e1fico de Kurie</button></div>\n    <div class=\"tabpane on\" data-pane=\"esp\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nbe-cv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">Q (keV) <input type=\"range\" id=\"nbe-Q\" min=\"10\" max=\"3000\" step=\"1\" value=\"782\"><b></b></label>\n            <label class=\"slider\">Z del hijo <input type=\"range\" id=\"nbe-Z\" min=\"1\" max=\"90\" step=\"1\" value=\"1\"><b></b></label>\n            <div class=\"seg\" id=\"nbe-s\"><button data-s=\"-1\" class=\"on\">\u03b2\u207b</button><button data-s=\"1\">\u03b2\u207a</button></div>\n          </div></div>\n        <div><div class=\"readout\" id=\"nbe-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Espectro de energ\u00eda cin\u00e9tica del electr\u00f3n (azul) con la funci\u00f3n de Fermi \\(F(Z',p)\\), y sin ella (gris). La atracci\u00f3n del n\u00facleo desplaza el espectro \u03b2\u207b hacia energ\u00edas bajas; la repulsi\u00f3n lo desplaza en \u03b2\u207a. Inicial: el neutr\u00f3n libre.</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"kur\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nbe-kv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">m<sub>\u03bd</sub>c\u00b2 (eV) <input type=\"range\" id=\"nbe-m\" min=\"0\" max=\"10\" step=\"0.1\" value=\"2\"><b></b></label>\n            <label class=\"np-chk\"><input type=\"checkbox\" id=\"nbe-z\" checked> ampliar el extremo</label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nbe-kread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Gr\u00e1fico de Kurie del tritio (\\(Q = 18{,}59\\) keV). Gris: \\(m_\\nu = 0\\), una recta. Azul: con la masa elegida, la curva se dobla y termina en \\(Q - m_\\nu c^2\\). As\u00ed mide KATRIN la masa del neutrino; su cota actual es \\(m_\\nu < 0{,}45\\ \\text{eV}\\).</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nbe-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Regla de oro de Fermi</h3><div class=\"eq\">\\[ \\lambda = \\frac{2\\pi}{\\hbar}\\,|V_{fi}|^2\\,\\rho(E_f) \\]</div><p>Teor\u00eda de perturbaciones dependiente del tiempo, a primer orden.</p></div>\n      <div class=\"law\"><h3>Forma del espectro</h3><div class=\"eq\">\\[ N(p)\\,dp = C\\,F(Z',p)\\,p^2(Q-T)^2\\,dp \\]</div><p>Permitidas, \\(m_\\nu = 0\\). \\(T = \\sqrt{p^2c^2+m_e^2c^4} - m_ec^2\\).</p></div>\n      <div class=\"law\"><h3>Funci\u00f3n de Fermi (no relativista)</h3><div class=\"eq\">\\[ F(Z',p) \\approx \\frac{2\\pi\\eta}{1-e^{-2\\pi\\eta}},\\qquad \\eta = \\mp\\frac{Z'\\alpha c}{v} \\]</div><p>Signo \u2212 para \u03b2\u207b (atracci\u00f3n) y + para \u03b2\u207a.</p></div>\n      <div class=\"law\"><h3>Gr\u00e1fico de Kurie</h3><div class=\"eq\">\\[ K(T) = \\sqrt{\\frac{N(p)}{p^2F(Z',p)}} \\propto Q - T \\]</div><p>Con masa: \\(K \\propto \\sqrt{(Q-T)\\sqrt{(Q-T)^2 - m_\\nu^2c^4}}\\).</p></div>\n      <div class=\"law\"><h3>Valor ft</h3><div class=\"eq\">\\[ ft_{1/2} = \\frac{\\ln2\\,2\\pi^3\\hbar^7}{g^2m_e^5c^4\\,|M_{fi}|^2} \\]</div><p>\\(f \\propto Q^5\\) para \\(Q \\gg m_ec^2\\) (regla de Sargent).</p></div>\n      <div class=\"law\"><h3>Reglas de selecci\u00f3n permitidas</h3><div class=\"eq\">\\[ \\Delta\\pi = \\text{no},\\quad \\Delta J = 0\\ (\\text{F}),\\ \\ 0,\\pm1\\ (\\text{GT}) \\]</div><p>\\(0^+\\to0^+\\) solo Fermi; sin spin, \\(\\Delta J = 0\\) puro.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nbe-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>Calcula \\(Q\\) para la desintegraci\u00f3n del neutr\u00f3n libre y la energ\u00eda m\u00e1xima del prot\u00f3n de retroceso. (Basado en Krane, \u00a79.1.)</b></p>\n      <ol><li>\\(Q = (m_n - m_p - m_e)c^2 = 939{,}565 - 938{,}272 - 0{,}511 = 0{,}782\\ \\text{MeV}\\).</li><li>El prot\u00f3n recibe la m\u00e1xima energ\u00eda cuando el electr\u00f3n y el neutrino salen juntos en la direcci\u00f3n opuesta, con \\(p_p = p_e + p_\\nu\\). El caso extremo es cuando el electr\u00f3n se lleva todo el momento: \\(T_e \\approx Q\\), \\(p_ec = \\sqrt{T_e(T_e+2m_ec^2)} = \\sqrt{0{,}782(1{,}804)} = 1{,}188\\ \\text{MeV}\\).</li><li>\\(T_p = \\dfrac{(p_pc)^2}{2m_pc^2} = \\dfrac{1{,}188^2}{2(938{,}3)} = 7{,}5\\times10^{-4}\\ \\text{MeV} = 0{,}75\\ \\text{keV}\\).</li><li>El retroceso es despreciable: el electr\u00f3n y el antineutrino se reparten \\(Q\\), por eso el espectro es continuo.</li></ol>\n      <p>Como \\(m_n - m_p = 1{,}29\\ \\text{MeV} > m_e\\), el neutr\u00f3n libre decae (\\(\\tau = 879\\) s). Dentro de un n\u00facleo estable la energ\u00eda de enlace lo impide.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-alfa\"><small>\u2190 Anterior</small>Desintegraci\u00f3n alfa</a><a class=\"next\" href=\"#np-gamma\"><small>Siguiente \u2192</small>Desintegraci\u00f3n gamma</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, cap. 9 (\u00a79.1\u20139.5). Cota de KATRIN: <i>Science</i> 388 (2025). Redacci\u00f3n y simulaciones propias.</p>\n</section>\n\n<!-- ============ NP \u00b7 GAMMA ============ -->\n<section class=\"view\" data-view=\"np-gamma\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad III \u00b7 Desintegraci\u00f3n radiactiva</div>\n  <h1>Desintegraci\u00f3n gamma: multipolos y reglas de selecci\u00f3n</h1>\n  <p class=\"lead\">Tras una desintegraci\u00f3n \u03b1 o \u03b2 el n\u00facleo suele quedar excitado y se relaja emitiendo fotones de keV a MeV, igual que un \u00e1tomo emite luz. Las energ\u00edas de los rayos \u03b3 y sus vidas medias son la principal fuente de informaci\u00f3n sobre los espines y paridades de los niveles nucleares.</p>\n  <div class=\"toc\"><a href=\"#nga-res\" data-scroll>Resumen</a><a href=\"#nga-lab\" data-scroll>Visualiza</a><a href=\"#nga-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nga-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nga-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Energ\u00eda del fot\u00f3n.</b> \\(E_\\gamma = \\Delta E - E_R\\) con retroceso \\(E_R = E_\\gamma^2/2Mc^2\\), de unos eV. Las l\u00edneas \u03b3 miden diferencias de niveles con precisi\u00f3n de eV.</li>\n      <li><b>Multipolos.</b> La radiaci\u00f3n se clasifica por el momento angular \\(L\\) que se lleva: el\u00e9ctrica (\\(EL\\)) o magn\u00e9tica (\\(ML\\)). \\(L = 1\\) dipolo, \\(L = 2\\) cuadrupolo, etc. No hay \\(L = 0\\): el fot\u00f3n tiene spin 1.</li>\n      <li><b>Reglas de selecci\u00f3n.</b> \\(|J_i - J_f| \\le L \\le J_i + J_f\\). Paridad: \\(EL\\) cambia la paridad si \\(L\\) es impar, \\(ML\\) si \\(L\\) es par. Las transiciones \\(0\\to0\\) est\u00e1n prohibidas para un solo fot\u00f3n.</li>\n      <li><b>Estimaciones de Weisskopf.</b> Para un solo prot\u00f3n que cambia de estado, \\(\\lambda(EL) \\propto A^{2L/3}E^{2L+1}\\). Cada unidad de \\(L\\) reduce el ritmo en un factor \\(\\sim10^{-5}\\); \\(ML\\) es unas 10\u2013100 veces m\u00e1s lenta que \\(EL\\). En la pr\u00e1ctica domina el \\(L\\) m\u00ednimo permitido.</li>\n      <li><b>Conversi\u00f3n interna.</b> El n\u00facleo puede ceder la energ\u00eda directamente a un electr\u00f3n at\u00f3mico, que sale con \\(T_e = \\Delta E - B_e\\). El coeficiente \\(\\alpha = \\lambda_e/\\lambda_\\gamma\\) crece con \\(Z\\), con \\(L\\) y al bajar la energ\u00eda. Es la \u00fanica v\u00eda en \\(0^+\\to0^+\\) (junto con pares \\(e^+e^-\\) si \\(\\Delta E > 1{,}022\\) MeV).</li>\n      <li><b>Is\u00f3meros.</b> Si la \u00fanica salida es de baja energ\u00eda y \\(L\\) alto, el estado excitado vive mucho: \\(^{99m}\\)Tc (6 h), \\(^{180m}\\)Ta (estable en la pr\u00e1ctica). Son las \"islas de isomer\u00eda\" bajo los n\u00fameros m\u00e1gicos.</li>\n      <li><b>Efecto M\u00f6ssbauer.</b> El ancho natural \\(\\Gamma = \\hbar/\\tau\\) es mucho menor que \\(E_R\\), as\u00ed que un n\u00facleo libre no reabsorbe su propio \u03b3. En un cristal el retroceso lo toma toda la red y la absorci\u00f3n resonante es posible: mide desplazamientos de \\(10^{-12}\\) eV.</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nga-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"two\">\n      <div><div class=\"canvas-box\"><canvas id=\"nga-cv\"></canvas></div>\n        <div class=\"controls\">\n          <label class=\"slider\">J inicial <input type=\"range\" id=\"nga-Ji\" min=\"0\" max=\"8\" step=\"0.5\" value=\"2\"><b></b></label>\n          <div class=\"seg\" id=\"nga-pi\"><button data-p=\"1\" class=\"on\">\u03c0<sub>i</sub> = +</button><button data-p=\"-1\">\u03c0<sub>i</sub> = \u2212</button></div>\n          <label class=\"slider\">J final <input type=\"range\" id=\"nga-Jf\" min=\"0\" max=\"8\" step=\"0.5\" value=\"0\"><b></b></label>\n          <div class=\"seg\" id=\"nga-pf\"><button data-p=\"1\" class=\"on\">\u03c0<sub>f</sub> = +</button><button data-p=\"-1\">\u03c0<sub>f</sub> = \u2212</button></div>\n          <label class=\"slider\">E<sub>\u03b3</sub> (keV) <input type=\"range\" id=\"nga-E\" min=\"10\" max=\"3000\" step=\"1\" value=\"500\"><b></b></label>\n          <label class=\"slider\">A <input type=\"range\" id=\"nga-A\" min=\"10\" max=\"250\" step=\"1\" value=\"100\"><b></b></label>\n        </div></div>\n      <div><div class=\"readout\" id=\"nga-read\"></div>\n        <p class=\"hint\" style=\"margin-top:12px\">Barras: vida media de Weisskopf de cada multipolaridad permitida, en escala logar\u00edtmica. El tipo m\u00e1s r\u00e1pido (verde) es el que domina. Si \\(J_i\\) y \\(J_f\\) no son ambos enteros o ambos semienteros, la transici\u00f3n no existe. Prueba \\(J_i = 9/2^-\\) \u2192 \\(J_f = 1/2^-\\) con 100 keV para fabricar un is\u00f3mero.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nga-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Energ\u00eda de retroceso</h3><div class=\"eq\">\\[ E_R = \\frac{E_\\gamma^2}{2Mc^2} \\]</div><p>\\(E_\\gamma = \\Delta E - E_R\\) en la emisi\u00f3n y \\(\\Delta E + E_R\\) para absorber.</p></div>\n      <div class=\"law\"><h3>Momento angular</h3><div class=\"eq\">\\[ |J_i - J_f| \\le L \\le J_i + J_f,\\quad L \\ge 1 \\]</div><p>Suma vectorial \\(\\vec J_i = \\vec J_f + \\vec L\\).</p></div>\n      <div class=\"law\"><h3>Paridad</h3><div class=\"eq\">\\[ \\pi(EL) = (-1)^L,\\qquad \\pi(ML) = (-1)^{L+1} \\]</div><p>\\(\\pi_i\\pi_f\\) debe coincidir con la paridad del multipolo.</p></div>\n      <div class=\"law\"><h3>Weisskopf (el\u00e9ctricas)</h3><div class=\"eq\">\\[ \\begin{aligned}\\lambda(E1) &= 1{,}0\\times10^{14}A^{2/3}E^3\\\\ \\lambda(E2) &= 7{,}3\\times10^{7}A^{4/3}E^5\\\\ \\lambda(E3) &= 34\\,A^2E^7\\end{aligned} \\]</div><p>\\(\\lambda\\) en s\u207b\u00b9 y \\(E\\) en MeV. \\(E4\\): \\(1{,}1\\times10^{-5}A^{8/3}E^9\\).</p></div>\n      <div class=\"law\"><h3>Weisskopf (magn\u00e9ticas)</h3><div class=\"eq\">\\[ \\begin{aligned}\\lambda(M1) &= 5{,}6\\times10^{13}E^3\\\\ \\lambda(M2) &= 3{,}5\\times10^{7}A^{2/3}E^5\\\\ \\lambda(M3) &= 16\\,A^{4/3}E^7\\end{aligned} \\]</div><p>\\(M4\\): \\(4{,}5\\times10^{-6}A^2E^9\\).</p></div>\n      <div class=\"law\"><h3>Ancho natural</h3><div class=\"eq\">\\[ \\Gamma = \\frac{\\hbar}{\\tau},\\qquad \\hbar = 6{,}58\\times10^{-16}\\ \\text{eV\u00b7s} \\]</div><p>M\u00f6ssbauer posible si el retroceso libre \\(\\gg\\Gamma\\) se evita con la red.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nga-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>El nivel de 14,4 keV del \\(^{57}\\)Fe vive \\(\\tau = 141\\) ns. Compara su ancho natural con la energ\u00eda de retroceso de un n\u00facleo libre. (Basado en Krane, \u00a710.9.)</b></p>\n      <ol><li>Ancho natural: \\(\\Gamma = \\hbar/\\tau = 6{,}58\\times10^{-16}\\ \\text{eV\u00b7s}/1{,}41\\times10^{-7}\\ \\text{s} = 4{,}7\\times10^{-9}\\ \\text{eV}\\).</li><li>Retroceso: \\(Mc^2 = 57(931{,}5\\ \\text{MeV}) = 5{,}31\\times10^{10}\\ \\text{eV}\\), as\u00ed que \\(E_R = \\dfrac{(1{,}44\\times10^4)^2}{2(5{,}31\\times10^{10})} = 1{,}95\\times10^{-3}\\ \\text{eV}\\).</li><li>\\(E_R/\\Gamma \\approx 4\\times10^5\\): la l\u00ednea emitida y la de absorci\u00f3n est\u00e1n separadas \\(2E_R\\), cientos de miles de anchos. Sin red no hay resonancia.</li><li>En un cristal, una fracci\u00f3n \\(f\\) de las emisiones ocurre sin excitar fonones: el \"\u00e1tomo\" que retrocede es todo el cristal y \\(E_R \\to 0\\).</li></ol>\n      <p>Moviendo la fuente a pocos mm/s se barre la l\u00ednea por efecto Doppler: \\(\\Gamma/E_\\gamma = 3\\times10^{-13}\\). Con esa precisi\u00f3n se miden campos hiperfinos y el estado de oxidaci\u00f3n del hierro; los rovers Spirit y Opportunity llevaron espectr\u00f3metros M\u00f6ssbauer para analizar minerales de Marte.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-beta\"><small>\u2190 Anterior</small>Desintegraci\u00f3n beta</a><a class=\"next\" href=\"#np-reacciones\"><small>Siguiente \u2192</small>Reacciones nucleares</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, cap. 10 (\u00a710.1\u201310.9). Redacci\u00f3n y simulaciones propias.</p>\n</section>\n<!-- ============ NP \u00b7 REACCIONES ============ -->\n<section class=\"view\" data-view=\"np-reacciones\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad IV \u00b7 Reacciones nucleares</div>\n  <h1>Reacciones nucleares: valor Q y secci\u00f3n eficaz</h1>\n  <p class=\"lead\">En 1919 Rutherford bombarde\u00f3 nitr\u00f3geno con part\u00edculas \u03b1 y obtuvo ox\u00edgeno y protones: la primera reacci\u00f3n nuclear provocada. Para describir cualquier reacci\u00f3n hacen falta dos cosas: la cinem\u00e1tica (qu\u00e9 energ\u00edas son posibles) y la secci\u00f3n eficaz (con qu\u00e9 probabilidad ocurre).</p>\n  <div class=\"toc\"><a href=\"#nre-res\" data-scroll>Resumen</a><a href=\"#nre-lab\" data-scroll>Visualiza</a><a href=\"#nre-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nre-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nre-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Notaci\u00f3n y conservaci\u00f3n.</b> \\(a + X \\to Y + b\\) se escribe \\(X(a,b)Y\\). Se conservan energ\u00eda total, momento, carga, n\u00famero de nucleones y momento angular; la paridad se conserva en reacciones fuertes y electromagn\u00e9ticas.</li>\n      <li><b>Valor Q.</b> \\(Q = (m_a + m_X - m_Y - m_b)c^2 = T_Y + T_b - T_a\\). Con \\(Q > 0\\) la reacci\u00f3n libera energ\u00eda (exot\u00e9rmica); con \\(Q < 0\\) hace falta energ\u00eda cin\u00e9tica m\u00ednima (endot\u00e9rmica).</li>\n      <li><b>Energ\u00eda umbral.</b> En el laboratorio no toda la energ\u00eda del proyectil sirve: parte se gasta en mover el centro de masa. Para \\(Q < 0\\): \\(T_{\\text{th}} = -Q\\,\\dfrac{m_Y+m_b}{m_Y+m_b-m_a} \\approx -Q\\left(1+\\dfrac{m_a}{m_X}\\right)\\).</li>\n      <li><b>Secci\u00f3n eficaz.</b> Ritmo de reacciones \\(R = \\sigma\\,I\\,N\\) (\\(I\\) proyectiles/s, \\(N\\) blancos por unidad de \u00e1rea). \\(\\sigma\\) es un \u00e1rea efectiva; la unidad es el barn, \\(1\\ \\text{b} = 10^{-28}\\ \\text{m}^2\\), del orden del \u00e1rea de un n\u00facleo pesado.</li>\n      <li><b>Dispersi\u00f3n de Rutherford.</b> Para la fuerza de Coulomb pura, \\(\\dfrac{d\\sigma}{d\\Omega} \\propto \\dfrac{1}{\\sin^4(\\theta/2)}\\) (desarrollada en la ficha de <a class=\"kw\" href=\"#t-rutherford\">secci\u00f3n eficaz de Rutherford</a>). Las desviaciones a \u00e1ngulos grandes revelan el tama\u00f1o nuclear.</li>\n      <li><b>N\u00facleo compuesto.</b> A bajas energ\u00edas el proyectil se funde con el blanco, la energ\u00eda se reparte entre todos los nucleones y el sistema \"olvida\" c\u00f3mo se form\u00f3 (Bohr, 1936). La formaci\u00f3n y la desintegraci\u00f3n son independientes.</li>\n      <li><b>Resonancias.</b> Cuando la energ\u00eda coincide con un nivel del n\u00facleo compuesto, \\(\\sigma\\) tiene un pico de Breit\u2013Wigner de ancho \\(\\Gamma = \\hbar/\\tau\\). Lejos de resonancias, la captura de neutrones lentos sigue la ley \\(\\sigma \\propto 1/v\\).</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nre-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"ruth\" class=\"on\">Dispersi\u00f3n de Rutherford</button><button data-t=\"bw\">Resonancia de Breit\u2013Wigner</button></div>\n    <div class=\"tabpane on\" data-pane=\"ruth\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nre-cv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">T<sub>\u03b1</sub> (MeV) <input type=\"range\" id=\"nre-T\" min=\"2\" max=\"30\" step=\"0.1\" value=\"7.7\"><b></b></label>\n            <label class=\"slider\">Z del blanco <input type=\"range\" id=\"nre-Z\" min=\"6\" max=\"92\" step=\"1\" value=\"79\"><b></b></label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nre-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Trayectorias hiperb\u00f3licas de part\u00edculas \u03b1 para par\u00e1metros de impacto equiespaciados. El c\u00edrculo naranja es el radio nuclear \\(R = 1{,}2(A^{1/3}+4^{1/3})\\) fm. Si la distancia m\u00ednima \\(d\\) llega a \\(R\\), la fuerza nuclear entra en juego y la f\u00f3rmula de Rutherford falla (sube \\(T\\) con un blanco ligero).</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"bw\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nre-bv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">E<sub>R</sub> (eV) <input type=\"range\" id=\"nre-ER\" min=\"1\" max=\"20\" step=\"0.1\" value=\"6.67\"><b></b></label>\n            <label class=\"slider\">\u0393 (meV) <input type=\"range\" id=\"nre-G\" min=\"5\" max=\"500\" step=\"1\" value=\"27\"><b></b></label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nre-bread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Secci\u00f3n eficaz de captura de neutrones: resonancia de Breit\u2013Wigner sobre el fondo \\(1/v\\) (escala logar\u00edtmica). Valores iniciales: la primera resonancia de \\(^{238}\\)U a 6,67 eV. El ancho es la incertidumbre en energ\u00eda del estado del n\u00facleo compuesto.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nre-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Valor Q</h3><div class=\"eq\">\\[ Q = (m_i - m_f)c^2 = T_f - T_i \\]</div><p>Con masas at\u00f3micas si se conserva el n\u00famero de electrones.</p></div>\n      <div class=\"law\"><h3>Energ\u00eda umbral</h3><div class=\"eq\">\\[ T_{\\text{th}} = -Q\\,\\frac{m_Y+m_b}{m_Y+m_b-m_a} \\]</div><p>No relativista. La versi\u00f3n relativista usa la masa invariante: <a href=\"#fm-dinamica\">repasar en relatividad especial</a>.</p></div>\n      <div class=\"law\"><h3>Ritmo de reacci\u00f3n</h3><div class=\"eq\">\\[ R = \\sigma\\,I\\,N,\\qquad \\sigma = \\int\\frac{d\\sigma}{d\\Omega}\\,d\\Omega \\]</div><p>\\(1\\ \\text{b} = 10^{-28}\\ \\text{m}^2 = 100\\ \\text{fm}^2\\).</p></div>\n      <div class=\"law\"><h3>Rutherford</h3><div class=\"eq\">\\[ \\frac{d\\sigma}{d\\Omega} = \\left(\\frac{zZe^2}{4\\pi\\varepsilon_0}\\right)^{\\!2}\\frac{1}{(4T_a)^2\\sin^4(\\theta/2)} \\]</div><p>Par\u00e1metro de impacto: \\(b = \\frac{d}{2}\\cot\\frac\\theta2\\), con \\(d = \\frac{zZe^2}{4\\pi\\varepsilon_0T_a}\\).</p></div>\n      <div class=\"law\"><h3>Breit\u2013Wigner</h3><div class=\"eq\">\\[ \\sigma(E) = \\pi\\bar\\lambda^2\\,g\\,\\frac{\\Gamma_a\\Gamma_b}{(E-E_R)^2+\\Gamma^2/4} \\]</div><p>\\(g = \\frac{2J+1}{(2s_a+1)(2s_X+1)}\\), \\(\\bar\\lambda = \\hbar/p\\).</p></div>\n      <div class=\"law\"><h3>Ley 1/v</h3><div class=\"eq\">\\[ \\sigma_{\\text{captura}} \\propto \\frac{1}{v} \\propto \\frac{1}{\\sqrt E} \\]</div><p>El neutr\u00f3n pasa m\u00e1s tiempo cerca del n\u00facleo cuanto m\u00e1s lento va.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nre-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>\u00bfCu\u00e1nto se acerca una part\u00edcula \u03b1 de 7,7 MeV a un n\u00facleo de oro en un choque frontal? \u00bfLlega a tocarlo? (Basado en Krane, \u00a711.6, y en el experimento de Geiger y Marsden.)</b></p>\n      <ol><li>En el choque frontal toda la energ\u00eda cin\u00e9tica (en el CM, \\(\\approx T\\) porque el oro es 50 veces m\u00e1s pesado) se convierte en energ\u00eda potencial: \\(T = \\dfrac{zZe^2}{4\\pi\\varepsilon_0d}\\).</li><li>\\(d = \\dfrac{zZ(1{,}44\\ \\text{MeV fm})}{T} = \\dfrac{2(79)(1{,}44)}{7{,}7} = 29{,}5\\ \\text{fm}\\).</li><li>Radio de contacto: \\(R = 1{,}2(197^{1/3} + 4^{1/3}) = 1{,}2(5{,}82+1{,}59) = 8{,}9\\ \\text{fm}\\).</li><li>Como \\(d \\approx 3{,}3\\,R\\), la \u03b1 nunca entra en el alcance de la fuerza nuclear: la dispersi\u00f3n es Coulomb pura y la f\u00f3rmula de Rutherford vale a todos los \u00e1ngulos.</li></ol>\n      <p>Por eso Rutherford pudo deducir un n\u00facleo puntual. Con \u03b1 m\u00e1s energ\u00e9ticas o n\u00facleos ligeros (\\(Z\\) peque\u00f1o), \\(d\\) baja hasta \\(R\\) y se observan desviaciones que miden el radio nuclear.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-gamma\"><small>\u2190 Anterior</small>Desintegraci\u00f3n gamma</a><a class=\"next\" href=\"#np-fision-fusion\"><small>Siguiente \u2192</small>Fisi\u00f3n y fusi\u00f3n</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, cap. 11 (\u00a711.1\u201311.12). Redacci\u00f3n y simulaciones propias.</p>\n</section>\n\n<!-- ============ NP \u00b7 FISI\u00d3N Y FUSI\u00d3N ============ -->\n<section class=\"view\" data-view=\"np-fision-fusion\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad IV \u00b7 Reacciones nucleares</div>\n  <h1>Fisi\u00f3n y fusi\u00f3n</h1>\n  <p class=\"lead\">La curva de energ\u00eda de enlace por nucle\u00f3n tiene un m\u00e1ximo cerca del hierro. Partir un n\u00facleo pesado o unir dos ligeros acerca los productos a ese m\u00e1ximo y libera millones de veces m\u00e1s energ\u00eda que una reacci\u00f3n qu\u00edmica. Aqu\u00ed se ve por qu\u00e9 la fisi\u00f3n necesita neutrones y la fusi\u00f3n, temperaturas de millones de grados.</p>\n  <div class=\"toc\"><a href=\"#nff-res\" data-scroll>Resumen</a><a href=\"#nff-lab\" data-scroll>Visualiza</a><a href=\"#nff-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nff-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nff-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Energ\u00eda de fisi\u00f3n.</b> De \\(B/A \\approx 7{,}6\\) MeV (uranio) a \\(\\approx 8{,}5\\) MeV (fragmentos): unos 200 MeV por fisi\u00f3n. Unos 170 MeV van a energ\u00eda cin\u00e9tica de los fragmentos y el resto a neutrones, rayos \u03b3 y desintegraciones \u03b2 posteriores (incluidos antineutrinos).</li>\n      <li><b>Barrera de fisi\u00f3n.</b> Al deformarse, la superficie crece (cuesta energ\u00eda) y la repulsi\u00f3n de Coulomb baja (libera energ\u00eda). Hay una barrera de \\(\\approx 6\\) MeV, que desaparece cuando \\(Z^2/A \\gtrsim 2a_s/a_c \\approx 47\\).</li>\n      <li><b>Fisi\u00f3n inducida.</b> Un neutr\u00f3n absorbido aporta su energ\u00eda de enlace. En \\(^{235}\\)U (par al capturar) aporta 6,5 MeV, m\u00e1s que la barrera: fisiona con neutrones t\u00e9rmicos. En \\(^{238}\\)U aporta 4,8 MeV: hacen falta neutrones r\u00e1pidos de m\u00e1s de 1 MeV.</li>\n      <li><b>Reacci\u00f3n en cadena.</b> Cada fisi\u00f3n libera \\(\\nu \\approx 2{,}4\\) neutrones. El factor de multiplicaci\u00f3n \\(k\\) es el cociente entre neutrones de generaciones sucesivas: \\(k < 1\\) subcr\u00edtico, \\(k = 1\\) cr\u00edtico, \\(k > 1\\) supercr\u00edtico. Un 0,65 % de neutrones retardados (segundos) hace controlable un reactor.</li>\n      <li><b>Fusi\u00f3n.</b> Dos n\u00facleos ligeros deben acercarse a pocos fm venciendo su repulsi\u00f3n (\\(\\sim\\)0,4 MeV para D+T). En el Sol, con \\(kT \\approx 1{,}3\\) keV, solo es posible por <a class=\"kw\" href=\"#t-tunel\">efecto t\u00fanel</a>.</li>\n      <li><b>Pico de Gamow.</b> El ritmo es el producto de la cola de Maxwell \\(e^{-E/kT}\\) (cae con \\(E\\)) por la penetraci\u00f3n \\(e^{-\\sqrt{E_G/E}}\\) (crece con \\(E\\)). El producto tiene un pico estrecho en \\(E_0 = (E_G(kT)^2/4)^{1/3}\\), varias veces \\(kT\\).</li>\n      <li><b>Sol y reactores.</b> La cadena pp convierte \\(4p\\to\\,^4\\text{He} + 2e^+ + 2\\nu_e\\) con \\(Q = 26{,}7\\) MeV. En la Tierra la reacci\u00f3n m\u00e1s f\u00e1cil es D + T \u2192 \u03b1 (3,5 MeV) + n (14,1 MeV). Para ganar energ\u00eda hace falta \\(n\\tau_E \\gtrsim 10^{20}\\ \\text{s/m}^3\\) a \\(kT \\sim 10\\)\u201320 keV (criterio de Lawson).</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nff-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"cad\" class=\"on\">Reacci\u00f3n en cadena</button><button data-t=\"gam\">Pico de Gamow</button></div>\n    <div class=\"tabpane on\" data-pane=\"cad\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nff-cv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">k (multiplicaci\u00f3n) <input type=\"range\" id=\"nff-k\" min=\"0.6\" max=\"1.6\" step=\"0.01\" value=\"1.05\"><b></b></label>\n            <button class=\"btn\" id=\"nff-go\">Reiniciar</button>\n          </div></div>\n        <div><div class=\"readout\" id=\"nff-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Monte Carlo: cada neutr\u00f3n produce una fisi\u00f3n que libera 0, 1, 2 o 3 neutrones al azar, con media \\(k\\). Arriba, los neutrones vivos; abajo, la poblaci\u00f3n por generaci\u00f3n en escala logar\u00edtmica, con la predicci\u00f3n \\(N_0k^n\\). Con \\(k\\) cerca de 1 las fluctuaciones dominan cuando hay pocos neutrones.</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"gam\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nff-gv\"></canvas></div>\n          <div class=\"controls\">\n            <select class=\"np-sel\" id=\"nff-r\"><option value=\"pp\">p + p (Sol)</option><option value=\"dt\" selected>D + T (reactor)</option><option value=\"pc\">p + \u00b9\u00b2C (ciclo CNO)</option></select>\n            <label class=\"slider\">kT (keV) <input type=\"range\" id=\"nff-T\" min=\"0.5\" max=\"40\" step=\"0.1\" value=\"10\"><b></b></label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nff-gread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Gris: distribuci\u00f3n de Maxwell \\(e^{-E/kT}\\). Azul: probabilidad de t\u00fanel \\(e^{-\\sqrt{E_G/E}}\\). Naranja: su producto (escalado), el pico de Gamow. Las reacciones solo ocurren en esa ventana de energ\u00edas. El n\u00facleo del Sol tiene \\(kT \\approx 1{,}35\\) keV.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nff-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>L\u00edmite de estabilidad ante fisi\u00f3n</h3><div class=\"eq\">\\[ \\frac{Z^2}{A} < \\frac{2a_s}{a_c} \\approx 47 \\]</div><p>Condici\u00f3n de que la deformaci\u00f3n aumente la energ\u00eda (modelo de la gota).</p></div>\n      <div class=\"law\"><h3>Factor de multiplicaci\u00f3n</h3><div class=\"eq\">\\[ k = \\eta\\,\\varepsilon\\,p\\,f,\\qquad N_n = N_0k^n \\]</div><p>F\u00f3rmula de los cuatro factores (medio infinito).</p></div>\n      <div class=\"law\"><h3>Energ\u00eda de Gamow</h3><div class=\"eq\">\\[ E_G = 2\\mu c^2(\\pi\\alpha Z_1Z_2)^2 \\]</div><p>Penetraci\u00f3n \\(\\approx e^{-\\sqrt{E_G/E}}\\). Para p + p: \\(E_G = 493\\) keV.</p></div>\n      <div class=\"law\"><h3>Pico de Gamow</h3><div class=\"eq\">\\[ E_0 = \\left(\\frac{E_G\\,(kT)^2}{4}\\right)^{1/3} \\]</div><p>M\u00e1ximo de \\(e^{-E/kT - \\sqrt{E_G/E}}\\).</p></div>\n      <div class=\"law\"><h3>Cadena pp</h3><div class=\"eq\">\\[ 4\\,^1\\text{H} \\to\\,^4\\text{He} + 2e^+ + 2\\nu_e,\\quad Q = 26{,}73\\ \\text{MeV} \\]</div><p>Los neutrinos se llevan en promedio 0,5 MeV.</p></div>\n      <div class=\"law\"><h3>Criterio de Lawson</h3><div class=\"eq\">\\[ n\\,\\tau_E \\gtrsim 10^{20}\\ \\text{s m}^{-3}\\quad(\\text{D\u2013T}) \\]</div><p>Versi\u00f3n con temperatura: \\(nT\\tau_E \\gtrsim 3\\times10^{21}\\ \\text{keV s m}^{-3}\\).</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nff-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>El Sol emite \\(L = 3{,}83\\times10^{26}\\) W. \u00bfCu\u00e1ntos n\u00facleos de helio forma por segundo y cu\u00e1nta masa de hidr\u00f3geno consume? (Basado en Krane, \u00a714.2.)</b></p>\n      <ol><li>De los 26,73 MeV de cada ciclo pp, los neutrinos escapan con \\(\\approx0{,}5\\) MeV. Al Sol le quedan \\(\\approx26{,}2\\ \\text{MeV} = 4{,}20\\times10^{-12}\\) J por cada \\(^4\\)He.</li><li>Ritmo: \\(\\dfrac{3{,}83\\times10^{26}\\ \\text{W}}{4{,}20\\times10^{-12}\\ \\text{J}} = 9{,}1\\times10^{37}\\) n\u00facleos de He por segundo.</li><li>Cada uno consume 4 protones: \\(3{,}6\\times10^{38}\\ \\text{p/s}\\times1{,}67\\times10^{-27}\\ \\text{kg} = 6{,}1\\times10^{11}\\ \\text{kg/s}\\): unos 600 millones de toneladas por segundo.</li><li>La masa que se convierte en energ\u00eda es \\(L/c^2 = 4{,}3\\times10^9\\ \\text{kg/s}\\), un 0,7 % de la masa de hidr\u00f3geno procesada.</li></ol>\n      <p>Aun as\u00ed, en 4600 millones de a\u00f1os el Sol solo ha consumido una peque\u00f1a parte de su hidr\u00f3geno del n\u00facleo. El pico de Gamow (unos 6 keV) es lo que hace la combusti\u00f3n tan lenta y estable.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-reacciones\"><small>\u2190 Anterior</small>Reacciones nucleares</a><a class=\"next\" href=\"#np-simetrias\"><small>Siguiente \u2192</small>Simetr\u00edas y quarks</a></div>\n  <p class=\"note\">Contenido de referencia: Krane, <i>Introductory Nuclear Physics</i>, caps. 13 y 14. Redacci\u00f3n y simulaciones propias.</p>\n</section>\n<!-- ============ NP \u00b7 SIMETR\u00cdAS ============ -->\n<section class=\"view\" data-view=\"np-simetrias\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad V \u00b7 Part\u00edculas elementales</div>\n  <h1>Simetr\u00edas, quarks y leyes de conservaci\u00f3n</h1>\n  <p class=\"lead\">En los a\u00f1os cincuenta los aceleradores produc\u00edan decenas de part\u00edculas nuevas. El orden lleg\u00f3 con las simetr\u00edas: ciertos n\u00fameros cu\u00e1nticos se conservan y los hadrones se agrupan en familias (octetes, decupletes) que solo se entienden si est\u00e1n hechos de quarks.</p>\n  <div class=\"toc\"><a href=\"#nsi-res\" data-scroll>Resumen</a><a href=\"#nsi-lab\" data-scroll>Visualiza</a><a href=\"#nsi-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nsi-ej\" data-scroll>Ejemplo</a></div>\n  <div class=\"block np-rel\"><p><b>Relatividad especial.</b> Masas en MeV/\\(c^2\\), 4-momentos y masa invariante se usan sin deducirlos: <a href=\"#fm-dinamica\">Repasar en relatividad especial \u2192</a> (F\u00edsica moderna) \u00b7 <a class=\"kw\" href=\"#t-emc2\">din\u00e1mica relativista</a>.</p></div>\n\n  <div class=\"block\" id=\"nsi-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Clasificaci\u00f3n.</b> Leptones (\\(e,\\mu,\\tau\\) y sus neutrinos) no sienten la fuerza fuerte. Hadrones: bariones (\\(qqq\\), spin semientero) y mesones (\\(q\\bar q\\), spin entero). Cada part\u00edcula tiene su antipart\u00edcula.</li>\n      <li><b>Conservaciones absolutas.</b> Energ\u00eda, momento, momento angular, carga el\u00e9ctrica, n\u00famero bari\u00f3nico \\(B\\) (\\(+1\\) bariones, \\(-1\\) antibariones) y n\u00famero lept\u00f3nico. Por \\(B\\), el prot\u00f3n no decae: \\(\\tau_p > 10^{34}\\) a\u00f1os.</li>\n      <li><b>Conservaciones parciales.</b> La extra\u00f1eza \\(S\\) se conserva en las interacciones fuerte y electromagn\u00e9tica, pero no en la d\u00e9bil (\\(|\\Delta S| = 1\\)). Por eso las part\u00edculas extra\u00f1as se producen en pares y viven \\(\\sim10^{-10}\\) s en vez de \\(10^{-23}\\) s.</li>\n      <li><b>Simetr\u00edas discretas.</b> Paridad \\(P\\), conjugaci\u00f3n de carga \\(C\\) e inversi\u00f3n temporal \\(T\\) se conservan en las interacciones fuerte y electromagn\u00e9tica. La d\u00e9bil viola \\(P\\) y \\(C\\) (y en menor medida \\(CP\\)). El teorema \\(CPT\\) garantiza que el producto se conserva siempre.</li>\n      <li><b>Isosp\u00edn.</b> Prot\u00f3n y neutr\u00f3n son dos estados de un nucle\u00f3n con \\(I = \\tfrac12\\) (\\(I_3 = \\pm\\tfrac12\\)); los piones forman un triplete \\(I = 1\\). La fuerza fuerte es invariante bajo rotaciones de isosp\u00edn (grupo SU(2)), lo que explica la independencia de carga.</li>\n      <li><b>SU(3) y quarks.</b> Con tres quarks \\(u, d, s\\): los mesones son \\(3\\otimes\\bar3 = 8\\oplus1\\) y los bariones \\(3\\otimes3\\otimes3 = 10\\oplus8\\oplus8\\oplus1\\). La carga cumple Gell-Mann\u2013Nishijima: \\(Q = I_3 + \\tfrac{Y}{2}\\), con hipercarga \\(Y = B + S\\).</li>\n      <li><b>La \u03a9\u207b y el color.</b> El decuplete \\(3/2^+\\) ten\u00eda un hueco en \\(S = -3\\): Gell-Mann predijo la \\(\\Omega^-\\) (\\(sss\\)) con masa \\(\\approx1680\\) MeV, hallada en 1964 a 1672 MeV. Pero \\(sss\\) o \\(\\Delta^{++} = uuu\\) con spins paralelos violan Pauli: cada quark tiene adem\u00e1s un \"color\" de tres valores, y los hadrones son incoloros.</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nsi-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"two\">\n      <div><div class=\"canvas-box\"><canvas id=\"nsi-cv\"></canvas></div>\n        <div class=\"controls\">\n          <div class=\"seg\" id=\"nsi-m\"><button data-m=\"ps\" class=\"on\">Mesones 0\u207b</button><button data-m=\"oct\">Bariones 1/2\u207a</button><button data-m=\"dec\">Bariones 3/2\u207a</button></div>\n          <div class=\"seg\" id=\"nsi-q\"><button data-q=\"u\">+ u</button><button data-q=\"d\">+ d</button><button data-q=\"s\">+ s</button><button data-q=\"U\">+ \u016b</button><button data-q=\"D\">+ d\u0304</button><button data-q=\"S\">+ s\u0304</button><button data-q=\"x\" class=\"on\">borrar</button></div>\n        </div></div>\n      <div><div class=\"readout\" id=\"nsi-read\"></div>\n        <p class=\"hint\" style=\"margin-top:12px\">Diagrama de pesos en el plano \\((I_3, Y)\\) con las masas medidas (MeV). Construye un hadr\u00f3n con los botones: 2 quarks (\\(q\\bar q\\)) para un mes\u00f3n o 3 quarks para un bari\u00f3n. La p\u00e1gina calcula \\(Q\\), \\(B\\), \\(S\\), \\(I_3\\) y \\(Y\\), y lo ubica en el multiplete. En el decuplete, las masas crecen ~150 MeV por cada quark \\(s\\): as\u00ed se predijo la \\(\\Omega^-\\).</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nsi-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Gell-Mann\u2013Nishijima</h3><div class=\"eq\">\\[ Q = I_3 + \\frac{Y}{2},\\qquad Y = B + S \\]</div><p>Con quarks pesados: \\(Y = B + S + C + \\tilde B + T\\).</p></div>\n      <div class=\"law\"><h3>N\u00fameros cu\u00e1nticos de los quarks</h3><div class=\"eq\">\\[ u:\\ \\left(+\\tfrac23,\\ +\\tfrac12,\\ 0\\right),\\ d:\\ \\left(-\\tfrac13,\\ -\\tfrac12,\\ 0\\right),\\ s:\\ \\left(-\\tfrac13,\\ 0,\\ -1\\right) \\]</div><p>\\((Q, I_3, S)\\); todos con \\(B = \\tfrac13\\) y spin \\(\\tfrac12\\).</p></div>\n      <div class=\"law\"><h3>Multipletes de SU(3)</h3><div class=\"eq\">\\[ 3\\otimes\\bar3 = 8\\oplus1,\\qquad 3\\otimes3\\otimes3 = 10\\oplus8\\oplus8\\oplus1 \\]</div><p>Mesones y bariones de quarks ligeros.</p></div>\n      <div class=\"law\"><h3>Regla de igual espaciado</h3><div class=\"eq\">\\[ M_\\Omega - M_{\\Xi^*} = M_{\\Xi^*} - M_{\\Sigma^*} = M_{\\Sigma^*} - M_\\Delta \\]</div><p>Decuplete (Gell-Mann\u2013Okubo); espaciado \\(\\approx 147\\) MeV.</p></div>\n      <div class=\"law\"><h3>Paridad de un hadr\u00f3n</h3><div class=\"eq\">\\[ P(q\\bar q) = (-1)^{\\ell+1},\\qquad C(q\\bar q) = (-1)^{\\ell+s} \\]</div><p>Mesones pseudoescalares (\\(\\ell = 0\\), \\(s = 0\\)): \\(J^{PC} = 0^{-+}\\).</p></div>\n      <div class=\"law\"><h3>Teorema CPT</h3><div class=\"eq\">\\[ m(\\bar X) = m(X),\\qquad \\tau(\\bar X) = \\tau(X) \\]</div><p>Toda teor\u00eda cu\u00e1ntica de campos local y con invariancia de Lorentz respeta CPT.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nsi-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>(a) Comprueba Gell-Mann\u2013Nishijima para el \\(K^+\\) y el \\(\\Xi^-\\). (b) Con las masas del decuplete \\(\\Delta\\) (1232), \\(\\Sigma^*\\) (1385) y \\(\\Xi^*\\) (1533), predice la masa de la \\(\\Omega^-\\). (Basado en Griffiths, \u00a71.8 y \u00a75.6.)</b></p>\n      <ol><li>\\(K^+ = u\\bar s\\): \\(Q = \\tfrac23 + \\tfrac13 = 1\\); \\(B = 0\\); \\(S = +1\\) (el \\(\\bar s\\) tiene \\(S = +1\\)); \\(I_3 = +\\tfrac12\\). Entonces \\(Y = 1\\) y \\(Q = \\tfrac12 + \\tfrac12 = 1\\). \u2713</li><li>\\(\\Xi^- = dss\\): \\(Q = -\\tfrac13-\\tfrac13-\\tfrac13 = -1\\); \\(B = 1\\), \\(S = -2\\), \\(Y = -1\\); \\(I_3 = -\\tfrac12\\). \\(Q = -\\tfrac12 - \\tfrac12 = -1\\). \u2713</li><li>Espaciados: \\(1385 - 1232 = 153\\) y \\(1533 - 1385 = 148\\) MeV. Promedio \\(\\approx 150\\) MeV por quark \\(s\\) extra.</li><li>\\(M_\\Omega \\approx 1533 + 150 = 1683\\) MeV. Medida: \\(1672{,}5\\) MeV (error del 0,6 %). Adem\u00e1s, con \\(S = -3\\) la \\(\\Omega^-\\) no puede decaer por interacci\u00f3n fuerte a nada m\u00e1s ligero: debe vivir \\(\\sim10^{-10}\\) s y dejar una traza visible.</li></ol>\n      <p>La \\(\\Omega^-\\) apareci\u00f3 en 1964 en una c\u00e1mara de burbujas de Brookhaven exactamente con esas propiedades. Fue el gran triunfo del esquema de SU(3).</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-fision-fusion\"><small>\u2190 Anterior</small>Fisi\u00f3n y fusi\u00f3n</a><a class=\"next\" href=\"#np-feynman\"><small>Siguiente \u2192</small>Diagramas de Feynman</a></div>\n  <p class=\"note\">Contenido de referencia: Griffiths, <i>Introduction to Elementary Particles</i>, 2.\u00aa ed., caps. 1, 4 y 5. Masas: Particle Data Group. Redacci\u00f3n y simulaciones propias.</p>\n</section>\n\n<!-- ============ NP \u00b7 FEYNMAN ============ -->\n<section class=\"view\" data-view=\"np-feynman\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad V \u00b7 Part\u00edculas elementales</div>\n  <h1>Diagramas de Feynman y QED a nivel \u00e1rbol</h1>\n  <p class=\"lead\">Un diagrama de Feynman es a la vez un dibujo y una f\u00f3rmula: cada l\u00ednea y cada v\u00e9rtice aporta un factor a la amplitud \\(\\mathcal M\\), y la regla de oro convierte \\(|\\mathcal M|^2\\) en secciones eficaces y vidas medias medibles. Aqu\u00ed se usan para la electrodin\u00e1mica cu\u00e1ntica y para contar los colores de los quarks.</p>\n  <div class=\"toc\"><a href=\"#nfe-res\" data-scroll>Resumen</a><a href=\"#nfe-lab\" data-scroll>Visualiza</a><a href=\"#nfe-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nfe-ej\" data-scroll>Ejemplo</a></div>\n  <div class=\"block np-rel\"><p><b>Relatividad especial.</b> Las reglas de Feynman se escriben con 4-momentos y la variable \\(s = (p_1+p_2)^2c^2\\) (energ\u00eda total en el centro de masa al cuadrado): <a href=\"#fm-dinamica\">Repasar en relatividad especial \u2192</a> \u00b7 <a class=\"kw\" href=\"#t-cuadrivectores\">cuadrivectores</a>.</p></div>\n\n  <div class=\"block\" id=\"nfe-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Qu\u00e9 es un diagrama.</b> Cada diagrama es un t\u00e9rmino de la serie perturbativa de la amplitud. El tiempo corre (por convenci\u00f3n) hacia la derecha; las l\u00edneas externas son part\u00edculas reales y las internas, virtuales, que no cumplen \\(E^2 = p^2c^2 + m^2c^4\\).</li>\n      <li><b>V\u00e9rtice de QED.</b> Un fot\u00f3n se acopla a una l\u00ednea de fermi\u00f3n cargado con factor \\(\\propto \\sqrt{\\alpha}\\), donde \\(\\alpha = e^2/4\\pi\\varepsilon_0\\hbar c \\approx 1/137\\). Cada par de v\u00e9rtices extra multiplica la amplitud por \\(\\alpha\\): por eso basta el orden m\u00e1s bajo (nivel \u00e1rbol).</li>\n      <li><b>Conservaci\u00f3n en cada v\u00e9rtice.</b> En cada v\u00e9rtice se conservan carga, 4-momento, n\u00famero bari\u00f3nico y n\u00fameros lept\u00f3nicos. Las flechas de fermi\u00f3n no se rompen: una flecha hacia atr\u00e1s en el tiempo es una antipart\u00edcula.</li>\n      <li><b>Propagador.</b> Una l\u00ednea interna de momento \\(q\\) aporta \\(1/(q^2 - M^2c^2)\\). Para el fot\u00f3n (\\(M = 0\\)) da el \\(1/q^2\\) responsable de la f\u00f3rmula de Rutherford; para \\(W\\) y \\(Z\\) (\\(M \\approx 80\\)\u201391 GeV) da interacciones d\u00e9biles y de corto alcance, como un <a class=\"kw\" href=\"#t-yukawa\">potencial de Yukawa</a>.</li>\n      <li><b>De \u2133 a lo medible.</b> La regla de oro de Fermi da \\(d\\sigma/d\\Omega\\) en el centro de masa a partir de \\(|\\mathcal M|^2\\). Para \\(e^+e^-\\to\\mu^+\\mu^-\\) resulta \\(\\dfrac{d\\sigma}{d\\Omega} = \\dfrac{\\alpha^2(\\hbar c)^2}{4s}(1+\\cos^2\\theta)\\) y \\(\\sigma = \\dfrac{4\\pi\\alpha^2(\\hbar c)^2}{3s} = \\dfrac{86{,}8\\ \\text{nb}}{s\\ [\\text{GeV}^2]}\\).</li>\n      <li><b>La raz\u00f3n R.</b> En \\(e^+e^-\\to q\\bar q\\) el diagrama es el mismo con carga \\(Q_q\\) y \\(N_c\\) colores: \\(R = \\sigma(\\text{hadrones})/\\sigma(\\mu^+\\mu^-) = N_c\\sum Q_q^2\\). Los escalones de \\(R\\) al abrirse el charm y el bottom miden \\(N_c = 3\\).</li>\n      <li><b>QCD.</b> Los gluones llevan color y se acoplan entre s\u00ed. La constante \\(\\alpha_s\\) es grande a bajas energ\u00edas (confinamiento) y peque\u00f1a a altas (libertad asint\u00f3tica): \\(\\alpha_s(M_Z) \\approx 0{,}118\\).</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nfe-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"diag\" class=\"on\">Diagramas</button><button data-t=\"R\">La raz\u00f3n R</button></div>\n    <div class=\"tabpane on\" data-pane=\"diag\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nfe-cv\"></canvas></div>\n          <div class=\"controls\"><select class=\"np-sel\" id=\"nfe-p\"></select></div></div>\n        <div><div class=\"readout\" id=\"nfe-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Diagramas de orden m\u00e1s bajo de procesos t\u00edpicos. L\u00edneas rectas con flecha: fermiones (flecha hacia atr\u00e1s = antipart\u00edcula). Onduladas: fot\u00f3n, W o Z. Espirales: gluones. A la derecha, la comprobaci\u00f3n de las leyes de conservaci\u00f3n en cada v\u00e9rtice y el orden en la constante de acoplamiento.</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"R\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nfe-rv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">\u221as (GeV) <input type=\"range\" id=\"nfe-s\" min=\"1\" max=\"40\" step=\"0.1\" value=\"5\"><b></b></label>\n            <label class=\"slider\">N<sub>c</sub> (colores) <input type=\"range\" id=\"nfe-nc\" min=\"1\" max=\"4\" step=\"1\" value=\"3\"><b></b></label>\n            <label class=\"np-chk\"><input type=\"checkbox\" id=\"nfe-qcd\" checked> correcci\u00f3n de QCD (1 + \u03b1<sub>s</sub>/\u03c0)</label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nfe-rread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Escalones de \\(R(\\sqrt s)\\) al cruzar los umbrales \\(2m_qc^2\\) de charm (\\(\\approx3{,}7\\) GeV) y bottom (\\(\\approx10{,}6\\) GeV), con picos de las resonancias \\(J/\\psi\\), \\(\\psi'\\) y \\(\\Upsilon\\) (esquem\u00e1ticos). Las bandas grises son los valores medidos aproximados. Solo \\(N_c = 3\\) los reproduce.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nfe-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Constante de estructura fina</h3><div class=\"eq\">\\[ \\alpha = \\frac{e^2}{4\\pi\\varepsilon_0\\hbar c} \\approx \\frac{1}{137{,}036} \\]</div><p>Cada v\u00e9rtice de QED aporta \\(\\sqrt{\\alpha}\\) a \\(\\mathcal M\\).</p></div>\n      <div class=\"law\"><h3>Secci\u00f3n eficaz en el CM</h3><div class=\"eq\">\\[ \\frac{d\\sigma}{d\\Omega} = \\left(\\frac{\\hbar c}{8\\pi}\\right)^{\\!2}\\frac{S\\,|\\mathcal M|^2}{(E_1+E_2)^2}\\frac{|\\vec p_f|}{|\\vec p_i|} \\]</div><p>\\(S\\): factor estad\u00edstico por part\u00edculas id\u00e9nticas en el estado final.</p></div>\n      <div class=\"law\"><h3>Propagador</h3><div class=\"eq\">\\[ \\frac{1}{q^2 - M^2c^2} \\xrightarrow{\\ |q^2|\\ll M^2c^2\\ } -\\frac{1}{M^2c^2} \\]</div><p>A baja energ\u00eda un bos\u00f3n pesado da una interacci\u00f3n de contacto (Fermi).</p></div>\n      <div class=\"law\"><h3>e\u207ae\u207b \u2192 \u03bc\u207a\u03bc\u207b</h3><div class=\"eq\">\\[ \\frac{d\\sigma}{d\\Omega} = \\frac{\\alpha^2(\\hbar c)^2}{4s}(1+\\cos^2\\theta),\\quad \\sigma = \\frac{4\\pi\\alpha^2(\\hbar c)^2}{3s} \\]</div><p>\\(\\sigma = 86{,}8\\ \\text{nb}/s[\\text{GeV}^2]\\), para \\(\\sqrt s \\gg m_\\mu c^2\\).</p></div>\n      <div class=\"law\"><h3>Raz\u00f3n R</h3><div class=\"eq\">\\[ R = N_c\\sum_q Q_q^2\\,\\left(1+\\frac{\\alpha_s}{\\pi}+\\cdots\\right) \\]</div><p>\\(u,d,s\\): 2; \\(+c\\): 10/3; \\(+b\\): 11/3.</p></div>\n      <div class=\"law\"><h3>Libertad asint\u00f3tica</h3><div class=\"eq\">\\[ \\alpha_s(Q^2) = \\frac{12\\pi}{(33-2n_f)\\ln(Q^2/\\Lambda^2)} \\]</div><p>A un lazo; \\(\\Lambda \\approx 0{,}2\\) GeV, \\(n_f\\) sabores activos.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nfe-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>Calcula \\(R\\) por debajo del umbral del charm y por encima del del bottom, y la secci\u00f3n eficaz de \\(e^+e^-\\to\\mu^+\\mu^-\\) a \\(\\sqrt s = 10\\) GeV. (Basado en Griffiths, \u00a78.2.)</b></p>\n      <ol><li>Por debajo del charm (\\(u, d, s\\)): \\(R = 3\\left[\\left(\\tfrac23\\right)^2 + \\left(-\\tfrac13\\right)^2 + \\left(-\\tfrac13\\right)^2\\right] = 3\\cdot\\tfrac69 = 2\\).</li><li>Por encima del bottom (\\(u, d, s, c, b\\)): \\(R = 3\\left[\\tfrac49+\\tfrac19+\\tfrac19+\\tfrac49+\\tfrac19\\right] = 3\\cdot\\tfrac{11}{9} = \\tfrac{11}{3} \\approx 3{,}67\\). Con la correcci\u00f3n de QCD (\\(\\alpha_s \\approx 0{,}18\\) a 10 GeV) sube a \\(\\approx 3{,}9\\), como se mide.</li><li>\\(\\sigma(\\mu\\mu) = 86{,}8\\ \\text{nb}/(10^2) = 0{,}87\\ \\text{nb} = 8{,}7\\times10^{-37}\\ \\text{m}^2\\).</li><li>Sin color (\\(N_c = 1\\)) se predecir\u00eda \\(R = 11/9 \\approx 1{,}2\\), tres veces menos que lo observado.</li></ol>\n      <p>El mismo factor 3 aparece en la desintegraci\u00f3n \\(\\pi^0\\to\\gamma\\gamma\\), cuyo ritmo es 9 veces mayor que sin color. Dos medidas independientes del n\u00famero de colores.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-simetrias\"><small>\u2190 Anterior</small>Simetr\u00edas y quarks</a><a class=\"next\" href=\"#np-debil\"><small>Siguiente \u2192</small>Interacci\u00f3n d\u00e9bil</a></div>\n  <p class=\"note\">Contenido de referencia: Griffiths, <i>Introduction to Elementary Particles</i>, 2.\u00aa ed., caps. 2, 6, 7 y 8. Redacci\u00f3n y simulaciones propias.</p>\n</section>\n\n<!-- ============ NP \u00b7 D\u00c9BIL ============ -->\n<section class=\"view\" data-view=\"np-debil\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad VI \u00b7 Interacciones y Modelo Est\u00e1ndar</div>\n  <h1>La interacci\u00f3n d\u00e9bil</h1>\n  <p class=\"lead\">La interacci\u00f3n d\u00e9bil es la \u00fanica que cambia el sabor de los quarks y leptones: hace decaer al neutr\u00f3n, al mu\u00f3n y a los piones cargados. Es d\u00e9bil porque sus mediadores, W y Z, son casi cien veces m\u00e1s pesados que un prot\u00f3n, y es la \u00fanica que distingue la izquierda de la derecha.</p>\n  <div class=\"toc\"><a href=\"#ndb-res\" data-scroll>Resumen</a><a href=\"#ndb-lab\" data-scroll>Visualiza</a><a href=\"#ndb-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#ndb-ej\" data-scroll>Ejemplo</a></div>\n  <div class=\"block np-rel\"><p><b>Relatividad especial.</b> El laboratorio del Z reconstruye la masa invariante de dos muones, \\(M^2c^4 = (E_1+E_2)^2 - |\\vec p_1+\\vec p_2|^2c^2\\). La f\u00f3rmula no se deduce aqu\u00ed: <a href=\"#fm-dinamica\">Repasar en relatividad especial \u2192</a> \u00b7 <a class=\"kw\" href=\"#t-emc2\">masa invariante</a>.</p></div>\n\n  <div class=\"block\" id=\"ndb-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Mediadores masivos.</b> \\(W^\\pm\\) (80,37 GeV) para corrientes cargadas y \\(Z^0\\) (91,19 GeV) para corrientes neutras. El alcance es \\(\\hbar/M_Wc \\approx 2{,}5\\times10^{-3}\\) fm, y a bajas energ\u00edas la interacci\u00f3n es de contacto, con la constante de Fermi \\(G_F = 1{,}1664\\times10^{-5}\\ \\text{GeV}^{-2}\\,(\\hbar c)^3\\).</li>\n      <li><b>Violaci\u00f3n de paridad.</b> Lee y Yang (1956) notaron que nada probaba que la d\u00e9bil conservara \\(P\\). Wu (1957) polariz\u00f3 n\u00facleos de \\(^{60}\\)Co y vio que los electrones salen preferentemente opuestos al spin nuclear: el experimento no es igual a su imagen en un espejo.</li>\n      <li><b>Teor\u00eda V\u2212A.</b> Solo las componentes \"izquierdas\" de los fermiones participan en las corrientes cargadas. Los neutrinos tienen helicidad \\(-1\\) y los antineutrinos \\(+1\\) (Goldhaber, 1958). Por eso \\(\\pi^+\\to e^+\\nu_e\\) est\u00e1 suprimida frente a \\(\\pi^+\\to\\mu^+\\nu_\\mu\\) (raz\u00f3n \\(1{,}23\\times10^{-4}\\)).</li>\n      <li><b>Desintegraci\u00f3n del mu\u00f3n.</b> El proceso lept\u00f3nico m\u00e1s limpio: \\(\\mu^-\\to e^-\\bar\\nu_e\\nu_\\mu\\), con \\(\\Gamma = \\dfrac{G_F^2m_\\mu^5c^4}{192\\pi^3\\hbar^7}\\). De \\(\\tau_\\mu = 2{,}197\\ \\mu\\)s se obtiene \\(G_F\\). La misma constante describe la desintegraci\u00f3n \u03b2 (universalidad).</li>\n      <li><b>Mezcla de quarks.</b> El W acopla \\(u\\) con \\(d' = V_{ud}d + V_{us}s + V_{ub}b\\). La matriz CKM es unitaria; con dos generaciones es una rotaci\u00f3n de \u00e1ngulo de Cabibbo \\(\\theta_c \\approx 13^\\circ\\). Con tres generaciones admite una fase compleja que viola \\(CP\\) (descubierta en kaones en 1964).</li>\n      <li><b>Corrientes neutras.</b> Predichas por la teor\u00eda electrod\u00e9bil y vistas en Gargamelle (1973), por ejemplo \\(\\nu_\\mu e^-\\to\\nu_\\mu e^-\\). El \\(Z\\) se descubri\u00f3 en el CERN en 1983.</li>\n      <li><b>La resonancia del Z.</b> En \\(e^+e^-\\) o en colisiones \\(pp\\) con dos muones, la masa invariante muestra un pico de Breit\u2013Wigner en \\(M_Z\\) con ancho \\(\\Gamma_Z = 2{,}495\\) GeV. Su \"ancho invisible\" (decaimientos a neutrinos) cuenta \\(N_\\nu = 2{,}98 \\approx 3\\) familias ligeras.</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"ndb-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"wu\" class=\"on\">Experimento de Wu</button><button data-t=\"z\">Resonancia del Z</button></div>\n    <div class=\"tabpane on\" data-pane=\"wu\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"ndb-cv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">asimetr\u00eda a <input type=\"range\" id=\"ndb-a\" min=\"-1\" max=\"1\" step=\"0.05\" value=\"-1\"><b></b></label>\n            <label class=\"np-chk\"><input type=\"checkbox\" id=\"ndb-mir\"> ver la imagen en el espejo (P)</label>\n          </div></div>\n        <div><div class=\"readout\" id=\"ndb-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">N\u00facleos de \\(^{60}\\)Co con spin \\(\\vec J\\) hacia arriba emiten electrones con distribuci\u00f3n \\(W(\\theta) = 1 + a\\,\\frac{v}{c}\\cos\\theta\\). En el espejo el momento \\(\\vec p\\) se invierte pero \\(\\vec J\\) (vector axial, como un giro) no. Si la paridad se conservara, ambas im\u00e1genes deber\u00edan ser igualmente posibles, lo que exige \\(a = 0\\). Wu midi\u00f3 \\(a \\approx -1\\).</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"z\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"ndb-zv\"></canvas></div>\n          <div class=\"controls\">\n            <label class=\"slider\">eventos <input type=\"range\" id=\"ndb-n\" min=\"200\" max=\"20000\" step=\"100\" value=\"3000\"><b></b></label>\n            <label class=\"slider\">resoluci\u00f3n (GeV) <input type=\"range\" id=\"ndb-r\" min=\"0.2\" max=\"4\" step=\"0.1\" value=\"1.5\"><b></b></label>\n            <button class=\"btn\" id=\"ndb-gen\">Nueva muestra</button>\n            <label class=\"btn ghost\" style=\"cursor:pointer\">Cargar CSV de CERN Open Data<input type=\"file\" id=\"ndb-file\" accept=\".csv,text/csv\" style=\"display:none\"></label>\n          </div></div>\n        <div><div class=\"readout\" id=\"ndb-zread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Histograma de la masa invariante de pares \\(\\mu^+\\mu^-\\) y ajuste de una Breit\u2013Wigner convolucionada con la resoluci\u00f3n del detector. La muestra inicial es <b>simulada</b> con los par\u00e1metros del PDG (\\(M_Z\\), \\(\\Gamma_Z\\)), resoluci\u00f3n gaussiana y un fondo exponencial. Puedes cargar el archivo real \u00abZmumu_Run2011A.csv\u00bb de CERN Open Data (CMS, registro 545): se usa la columna <code>M</code> o, si falta, se calcula a partir de <code>E1, px1, py1, pz1, E2, \u2026</code>.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"ndb-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Constante de Fermi</h3><div class=\"eq\">\\[ \\frac{G_F}{\\sqrt2} = \\frac{g_W^2}{8M_W^2c^4}(\\hbar c)^3 \\]</div><p>\\(G_F = 1{,}1664\\times10^{-5}\\ \\text{GeV}^{-2}(\\hbar c)^3\\).</p></div>\n      <div class=\"law\"><h3>Vida del mu\u00f3n</h3><div class=\"eq\">\\[ \\frac{1}{\\tau_\\mu} = \\frac{G_F^2m_\\mu^5c^4}{192\\pi^3\\hbar^7} \\]</div><p>Para el \\(\\tau\\): \\(\\tau_\\tau = \\tau_\\mu(m_\\mu/m_\\tau)^5\\,\\text{BR}(\\tau\\to e\\nu\\bar\\nu)\\).</p></div>\n      <div class=\"law\"><h3>Distribuci\u00f3n de Wu</h3><div class=\"eq\">\\[ W(\\theta) = 1 + a\\,\\frac{\\langle\\vec J\\rangle\\cdot\\vec p}{|\\vec J|\\,E/c},\\quad a \\approx -1 \\]</div><p>\\(\\langle\\vec J\\rangle\\cdot\\vec p\\) es un pseudoescalar: cambia de signo bajo \\(P\\).</p></div>\n      <div class=\"law\"><h3>Supresi\u00f3n de \u03c0 \u2192 e\u03bd</h3><div class=\"eq\">\\[ \\frac{\\Gamma(\\pi\\to e\\nu)}{\\Gamma(\\pi\\to\\mu\\nu)} = \\frac{m_e^2}{m_\\mu^2}\\left(\\frac{m_\\pi^2-m_e^2}{m_\\pi^2-m_\\mu^2}\\right)^{\\!2} = 1{,}28\\times10^{-4} \\]</div><p>Consecuencia de la helicidad en V\u2212A.</p></div>\n      <div class=\"law\"><h3>Matriz CKM (Cabibbo)</h3><div class=\"eq\">\\[ \\begin{pmatrix} d'\\\\ s'\\end{pmatrix} = \\begin{pmatrix}\\cos\\theta_c & \\sin\\theta_c\\\\ -\\sin\\theta_c & \\cos\\theta_c\\end{pmatrix}\\begin{pmatrix} d\\\\ s\\end{pmatrix} \\]</div><p>\\(\\sin\\theta_c = |V_{us}| \\approx 0{,}225\\).</p></div>\n      <div class=\"law\"><h3>Breit\u2013Wigner relativista</h3><div class=\"eq\">\\[ \\sigma(M) \\propto \\frac{M^2\\Gamma_Z^2}{(M^2 - M_Z^2)^2 + M^2\\Gamma_Z^2} \\]</div><p>\\(M_Z = 91{,}188\\) GeV, \\(\\Gamma_Z = 2{,}495\\) GeV; \\(N_\\nu = \\Gamma_{\\text{inv}}/\\Gamma_{\\nu\\bar\\nu}\\).</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"ndb-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>A partir de \\(\\tau_\\mu = 2{,}197\\ \\mu\\)s, estima la vida media del lept\u00f3n \\(\\tau\\) (\\(m_\\tau = 1776{,}9\\) MeV), sabiendo que decae a \\(e\\nu\\bar\\nu\\) un 17,8 % de las veces. (Basado en Griffiths, \u00a79.3.)</b></p>\n      <ol><li>El ritmo parcial \\(\\tau\\to e\\bar\\nu_e\\nu_\\tau\\) tiene la misma forma que el del mu\u00f3n: \\(\\Gamma_e(\\tau) = \\dfrac{G_F^2m_\\tau^5c^4}{192\\pi^3\\hbar^7}\\) (universalidad lept\u00f3nica).</li><li>Dividiendo: \\(\\dfrac{\\Gamma_e(\\tau)}{\\Gamma(\\mu)} = \\left(\\dfrac{m_\\tau}{m_\\mu}\\right)^5 = \\left(\\dfrac{1776{,}9}{105{,}66}\\right)^5 = (16{,}82)^5 = 1{,}344\\times10^6\\).</li><li>Vida total: \\(\\tau_\\tau = \\dfrac{\\text{BR}_e}{\\Gamma_e(\\tau)} = \\text{BR}_e\\,\\dfrac{\\tau_\\mu}{1{,}344\\times10^6} = 0{,}178\\cdot\\dfrac{2{,}197\\times10^{-6}}{1{,}344\\times10^6}\\ \\text{s}\\).</li><li>\\(\\tau_\\tau = 2{,}91\\times10^{-13}\\) s. Medido: \\(2{,}903\\times10^{-13}\\) s.</li></ol>\n      <p>Que la misma \\(G_F\\) describa muones, taus y neutrones es la universalidad de la interacci\u00f3n d\u00e9bil: los tres sienten el mismo W.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-feynman\"><small>\u2190 Anterior</small>Diagramas de Feynman</a><a class=\"next\" href=\"#np-neutrinos-me\"><small>Siguiente \u2192</small>Neutrinos y Modelo Est\u00e1ndar</a></div>\n  <p class=\"note\">Contenido de referencia: Griffiths, <i>Introduction to Elementary Particles</i>, 2.\u00aa ed., caps. 4 y 9. Valores: Particle Data Group. Datos reales opcionales: CERN Open Data (CMS). Redacci\u00f3n y simulaciones propias.</p>\n</section>\n\n<!-- ============ NP \u00b7 NEUTRINOS Y MODELO EST\u00c1NDAR ============ -->\n<section class=\"view\" data-view=\"np-neutrinos-me\">\n  <div class=\"eyebrow\">F\u00edsica nuclear y de part\u00edculas \u00b7 Unidad VI \u00b7 Interacciones y Modelo Est\u00e1ndar</div>\n  <h1>Oscilaciones de neutrinos y el Modelo Est\u00e1ndar</h1>\n  <p class=\"lead\">Durante d\u00e9cadas se midieron menos neutrinos solares de los esperados. La soluci\u00f3n fue que los neutrinos cambian de sabor mientras viajan, lo que solo es posible si tienen masa. Es la primera f\u00edsica comprobada m\u00e1s all\u00e1 del Modelo Est\u00e1ndar, cuyo panorama completo cierra este curso.</p>\n  <div class=\"toc\"><a href=\"#nne-res\" data-scroll>Resumen</a><a href=\"#nne-lab\" data-scroll>Visualiza</a><a href=\"#nne-leyes\" data-scroll>Leyes y f\u00f3rmulas</a><a href=\"#nne-ej\" data-scroll>Ejemplo</a></div>\n\n  <div class=\"block\" id=\"nne-res\">\n    <h2><span class=\"ico\">\u2261</span>Resumen</h2>\n    <ul class=\"keypoints\">\n      <li><b>Sabor y masa.</b> Los neutrinos se producen y detectan con sabor definido (\\(\\nu_e, \\nu_\\mu, \\nu_\\tau\\)), pero se propagan como estados de masa definida (\\(\\nu_1, \\nu_2, \\nu_3\\)): \\(|\\nu_\\alpha\\rangle = \\sum_i U_{\\alpha i}|\\nu_i\\rangle\\). \\(U\\) es la matriz PMNS, unitaria.</li>\n      <li><b>Dos sabores.</b> Con un \u00e1ngulo de mezcla \\(\\theta\\), cada componente acumula una fase distinta, y \\(P(\\nu_\\alpha\\to\\nu_\\beta) = \\sin^22\\theta\\,\\sin^2\\!\\left(\\dfrac{1{,}267\\,\\Delta m^2[\\text{eV}^2]\\,L[\\text{km}]}{E[\\text{GeV}]}\\right)\\). Si \\(\\Delta m^2 = 0\\) no hay oscilaci\u00f3n.</li>\n      <li><b>Longitud de oscilaci\u00f3n.</b> \\(L_{\\text{osc}} = 2{,}48\\ \\text{km}\\cdot E[\\text{GeV}]/\\Delta m^2[\\text{eV}^2]\\). Cada experimento elige \\(L/E\\) para quedar cerca del primer m\u00e1ximo.</li>\n      <li><b>Evidencias.</b> Neutrinos solares (Homestake, Super-Kamiokande; SNO en 2001 midi\u00f3 el flujo total por corriente neutra y coincidi\u00f3 con el modelo solar), atmosf\u00e9ricos (Super-K 1998: faltan \\(\\nu_\\mu\\) que vienen desde abajo), de reactores (KamLAND, Daya Bay) y de aceleradores (T2K, NOvA). Premio Nobel 2015.</li>\n      <li><b>Par\u00e1metros.</b> \\(\\Delta m^2_{21} \\approx 7{,}4\\times10^{-5}\\ \\text{eV}^2\\), \\(|\\Delta m^2_{31}| \\approx 2{,}5\\times10^{-3}\\ \\text{eV}^2\\), \\(\\theta_{12} \\approx 33^\\circ\\), \\(\\theta_{23} \\approx 49^\\circ\\), \\(\\theta_{13} \\approx 8{,}6^\\circ\\). Siguen abiertos el ordenamiento de masas, la fase de violaci\u00f3n de CP y la escala absoluta (KATRIN: \\(m_\\nu < 0{,}45\\) eV).</li>\n      <li><b>Modelo Est\u00e1ndar.</b> Grupo de simetr\u00eda \\(SU(3)_c\\times SU(2)_L\\times U(1)_Y\\). Doce fermiones en tres generaciones (6 quarks, 6 leptones), 12 bosones de gauge (fot\u00f3n, \\(W^\\pm\\), \\(Z\\), 8 gluones) y el bos\u00f3n de Higgs (125 GeV, descubierto en el LHC en 2012).</li>\n      <li><b>Lo que falta.</b> El Modelo Est\u00e1ndar no explica las masas de los neutrinos (ni si son de Dirac o de Majorana), la materia oscura, la asimetr\u00eda materia-antimateria del universo ni la gravedad cu\u00e1ntica.</li>\n    </ul>\n  </div>\n\n  <div class=\"block\" id=\"nne-lab\">\n    <h2><span class=\"ico\">\u25ce</span>Visualiza</h2>\n    <div class=\"tabs\"><button data-t=\"osc\" class=\"on\">Oscilaci\u00f3n</button><button data-t=\"me\">Part\u00edculas del Modelo Est\u00e1ndar</button></div>\n    <div class=\"tabpane on\" data-pane=\"osc\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nne-cv\"></canvas></div>\n          <div class=\"controls\">\n            <select class=\"np-sel\" id=\"nne-pre\"><option value=\"t2k\">T2K (295 km, 0,6 GeV)</option><option value=\"kam\">KamLAND (180 km, 4 MeV)</option><option value=\"db\">Daya Bay (1,6 km, 4 MeV)</option><option value=\"atm\">Atmosf\u00e9ricos (1 GeV)</option></select>\n            <label class=\"slider\">sin\u00b22\u03b8 <input type=\"range\" id=\"nne-s\" min=\"0\" max=\"1\" step=\"0.01\" value=\"0.99\"><b></b></label>\n            <label class=\"slider\">\u0394m\u00b2 (10\u207b\u00b3 eV\u00b2) <input type=\"range\" id=\"nne-dm\" min=\"0.03\" max=\"5\" step=\"0.01\" value=\"2.5\"><b></b></label>\n            <label class=\"slider\">E (GeV) <input type=\"range\" id=\"nne-E\" min=\"0.001\" max=\"5\" step=\"0.001\" value=\"0.6\"><b></b></label>\n            <label class=\"np-chk\"><input type=\"checkbox\" id=\"nne-av\"> promediar sobre un espectro de \u00b120 % en E</label>\n          </div></div>\n        <div><div class=\"readout\" id=\"nne-read\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Probabilidad de supervivencia \\(P(\\nu_\\alpha\\to\\nu_\\alpha)\\) (azul) y de aparici\u00f3n \\(P(\\nu_\\alpha\\to\\nu_\\beta)\\) (naranja) frente a la distancia. La l\u00ednea vertical marca la distancia del experimento elegido. Al promediar en energ\u00eda, a distancias grandes la oscilaci\u00f3n se borra y \\(P \\to 1 - \\tfrac12\\sin^22\\theta\\).</p></div>\n      </div>\n    </div>\n    <div class=\"tabpane\" data-pane=\"me\">\n      <div class=\"two\">\n        <div><div class=\"canvas-box\"><canvas id=\"nne-mv\"></canvas></div></div>\n        <div><div class=\"readout\" id=\"nne-mread\"></div>\n          <p class=\"hint\" style=\"margin-top:12px\">Haz clic en una part\u00edcula. Columnas: tres generaciones de quarks y leptones, y los bosones. El \u00e1rea de cada c\u00edrculo crece con el logaritmo de la masa (de \\(<0{,}45\\) eV a 173 GeV, 12 \u00f3rdenes de magnitud).</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nne-leyes\">\n    <h2><span class=\"ico\">\u00a7</span>Leyes y f\u00f3rmulas</h2>\n    <div class=\"laws\">\n      <div class=\"law\"><h3>Mezcla de dos sabores</h3><div class=\"eq\">\\[ \\begin{pmatrix}\\nu_\\alpha\\\\ \\nu_\\beta\\end{pmatrix} = \\begin{pmatrix}\\cos\\theta & \\sin\\theta\\\\ -\\sin\\theta & \\cos\\theta\\end{pmatrix}\\begin{pmatrix}\\nu_1\\\\ \\nu_2\\end{pmatrix} \\]</div><p>Generalizaci\u00f3n: matriz PMNS \\(3\\times3\\) con tres \u00e1ngulos y una fase.</p></div>\n      <div class=\"law\"><h3>Probabilidad de oscilaci\u00f3n</h3><div class=\"eq\">\\[ P(\\nu_\\alpha\\to\\nu_\\beta) = \\sin^22\\theta\\,\\sin^2\\!\\left(\\frac{\\Delta m^2c^4L}{4\\hbar cE}\\right) \\]</div><p>En unidades pr\u00e1cticas: \\(1{,}267\\,\\Delta m^2[\\text{eV}^2]L[\\text{km}]/E[\\text{GeV}]\\).</p></div>\n      <div class=\"law\"><h3>Longitud de oscilaci\u00f3n</h3><div class=\"eq\">\\[ L_{\\text{osc}} = \\frac{4\\pi\\hbar cE}{\\Delta m^2c^4} = 2{,}48\\ \\text{km}\\,\\frac{E[\\text{GeV}]}{\\Delta m^2[\\text{eV}^2]} \\]</div><p>Primer m\u00e1ximo de aparici\u00f3n en \\(L_{\\text{osc}}/2\\).</p></div>\n      <div class=\"law\"><h3>Fase de propagaci\u00f3n</h3><div class=\"eq\">\\[ E_i \\approx pc + \\frac{m_i^2c^4}{2pc}\\ \\Rightarrow\\ \\Delta\\phi = \\frac{\\Delta m^2c^4L}{2\\hbar cE} \\]</div><p>Neutrinos ultrarrelativistas, mismo momento.</p></div>\n      <div class=\"law\"><h3>Unitariedad PMNS</h3><div class=\"eq\">\\[ \\sum_i |U_{\\alpha i}|^2 = 1,\\qquad \\sum_\\beta P(\\nu_\\alpha\\to\\nu_\\beta) = 1 \\]</div><p>La probabilidad total se conserva: los neutrinos no desaparecen, cambian de sabor.</p></div>\n      <div class=\"law\"><h3>Simetr\u00eda del Modelo Est\u00e1ndar</h3><div class=\"eq\">\\[ SU(3)_c\\times SU(2)_L\\times U(1)_Y \\xrightarrow{\\ \\langle\\phi\\rangle\\ } SU(3)_c\\times U(1)_{\\text{em}} \\]</div><p>El vac\u00edo del Higgs (\\(v = 246\\) GeV) rompe la simetr\u00eda electrod\u00e9bil y da masa a W y Z.</p></div>\n    </div>\n  </div>\n\n  <div class=\"block\" id=\"nne-ej\">\n    <h2><span class=\"ico\">\u270e</span>Ejemplo resuelto</h2>\n    <div class=\"example\">\n      <p><b>Halla la longitud de oscilaci\u00f3n de neutrinos atmosf\u00e9ricos de 1 GeV con \\(\\Delta m^2 = 2{,}5\\times10^{-3}\\ \\text{eV}^2\\). \u00bfPor qu\u00e9 Super-Kamiokande ve menos \\(\\nu_\\mu\\) desde abajo que desde arriba? (Basado en Griffiths, \u00a711.1.)</b></p>\n      <ol><li>\\(L_{\\text{osc}} = 2{,}48\\ \\text{km}\\times\\dfrac{1}{2{,}5\\times10^{-3}} = 992\\ \\text{km}\\). El primer m\u00ednimo de supervivencia est\u00e1 en \\(L_{\\text{osc}}/2 \\approx 500\\) km.</li><li>Los neutrinos que llegan desde arriba se producen en la atm\u00f3sfera a \\(\\sim15\\) km: \\(L \\ll L_{\\text{osc}}\\), casi no oscilan.</li><li>Los que vienen desde abajo atraviesan la Tierra: \\(L \\approx 12\\,700\\) km \\(\\approx 13\\,L_{\\text{osc}}\\). Tras muchas oscilaciones, promediadas sobre el espectro de energ\u00edas, \\(\\langle P(\\nu_\\mu\\to\\nu_\\mu)\\rangle = 1 - \\tfrac12\\sin^22\\theta_{23} \\approx 0{,}5\\).</li><li>Resultado: llegan aproximadamente la mitad de los \\(\\nu_\\mu\\) esperados desde abajo, mientras los \\(\\nu_e\\) no muestran d\u00e9ficit (los \\(\\nu_\\mu\\) se convierten sobre todo en \\(\\nu_\\tau\\)).</li></ol>\n      <p>Esa asimetr\u00eda arriba-abajo, publicada en 1998, fue la primera prueba concluyente de que los neutrinos tienen masa.</p>\n    </div>\n  </div>\n\n  <div class=\"pager\"><a href=\"#np-debil\"><small>\u2190 Anterior</small>Interacci\u00f3n d\u00e9bil</a><a class=\"next\" href=\"#nuclear-particulas\"><small>Volver \u2192</small>F\u00edsica nuclear y de part\u00edculas</a></div>\n  <p class=\"note\">Contenido de referencia: Griffiths, <i>Introduction to Elementary Particles</i>, 2.\u00aa ed., caps. 9\u201311. Par\u00e1metros: Particle Data Group (2024). Redacci\u00f3n y simulaciones propias.</p>\n</section>\n";[...tmp.children].forEach(n=>anchor.parentNode.insertBefore(n,anchor));}

/* ---------- formato ---------- */
function nf(x,d=2){if(!isFinite(x))return x>0?'∞':'−∞';const s=(Math.abs(x)<0.5*10**-d?0:x).toFixed(d);return s.replace('-','−').replace('.',',');}
function sci(x,d=3){ // d cifras significativas
  if(x===0)return '0';if(!isFinite(x))return '∞';
  const e=Math.floor(Math.log10(Math.abs(x)));
  if(e>=-3&&e<5)return nf(x,Math.max(0,d-1-e));
  const m=x/10**e;return nf(m,d-1)+'×10<sup>'+String(e).replace('-','−')+'</sup>';}
const row=(k,v)=>`<div><span class="k">${k}</span> = <b>${v}</b></div>`;
const rowT=t=>`<div class="k" style="margin-top:6px">${t}</div>`;
const sep='<div style="border-top:1px solid var(--line);margin:6px 0"></div>';

/* ---------- canvas ---------- */
function fit(cv,aspect,maxH,minH){
  const w=cv.parentElement.clientWidth||600;let h=Math.round(w*aspect);
  if(maxH)h=Math.min(h,maxH);if(minH)h=Math.max(h,minH);
  const dpr=window.devicePixelRatio||1;
  if(cv._w!==w||cv._h!==h||cv._d!==dpr){cv.width=Math.round(w*dpr);cv.height=Math.round(h*dpr);cv.style.height=h+'px';cv._w=w;cv._h=h;cv._d=dpr;}
  const ctx=cv.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);
  return {ctx,w,h};
}
const vis=el=>el&&el.offsetParent!==null&&el.parentElement.clientWidth>10;
function niceStep(span,n){const raw=span/n,p=10**Math.floor(Math.log10(raw)),m=raw/p;return (m<1.5?1:m<3.5?2:m<7.5?5:10)*p;}
function ticks(a,b,n=5){const s=niceStep(b-a,n),out=[];for(let v=Math.ceil(a/s-1e-9)*s;v<=b+1e-9;v+=s)out.push(Math.abs(v)<s*1e-9?0:v);return out;}
/* ejes: o={l,t,w,h,xr,yr,xl,yl,xt,yt,xf,yf,logy} */
function axes(ctx,o){
  const X=x=>o.l+(x-o.xr[0])/(o.xr[1]-o.xr[0])*o.w;
  const Y=o.logy?(y=>o.t+o.h-(Math.log10(y)-o.yr[0])/(o.yr[1]-o.yr[0])*o.h):(y=>o.t+o.h-(y-o.yr[0])/(o.yr[1]-o.yr[0])*o.h);
  ctx.save();ctx.font='11px Inter, sans-serif';ctx.lineWidth=1;
  const xt=o.xt||ticks(o.xr[0],o.xr[1],Math.max(3,Math.round(o.w/80)));
  const yt=o.yt||(o.logy?null:ticks(o.yr[0],o.yr[1],Math.max(3,Math.round(o.h/50))));
  const dg=t=>t&&t.length>1?Math.max(0,-Math.floor(Math.log10(Math.abs(t[1]-t[0]))+1e-9)):1;
  const xf=o.xf||(v=>nf(v,dg(xt)));const yf=o.yf||(v=>nf(v,dg(yt)));
  ctx.strokeStyle=K.gr;ctx.fillStyle=K.mut;ctx.textAlign='center';ctx.textBaseline='top';
  xt.forEach(v=>{const x=X(v);ctx.beginPath();ctx.moveTo(x,o.t);ctx.lineTo(x,o.t+o.h);ctx.stroke();ctx.fillText(xf(v),x,o.t+o.h+4);});
  ctx.textAlign='right';ctx.textBaseline='middle';
  if(o.logy){for(let e=Math.ceil(o.yr[0]);e<=o.yr[1];e++){const y=Y(10**e);ctx.beginPath();ctx.moveTo(o.l,y);ctx.lineTo(o.l+o.w,y);ctx.stroke();ctx.fillText('10'+String(e).replace('-','−').split('').map(c=>'⁰¹²³⁴⁵⁶⁷⁸⁹'['0123456789'.indexOf(c)]||'⁻').join(''),o.l-5,y);}}
  else yt.forEach(v=>{const y=Y(v);ctx.beginPath();ctx.moveTo(o.l,y);ctx.lineTo(o.l+o.w,y);ctx.stroke();ctx.fillText(yf(v),o.l-5,y);});
  ctx.strokeStyle=K.ax;ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(o.l,o.t);ctx.lineTo(o.l,o.t+o.h);ctx.lineTo(o.l+o.w,o.t+o.h);ctx.stroke();
  ctx.font='600 12px Inter, sans-serif';ctx.fillStyle=K.ink;
  if(o.xl){ctx.textAlign='right';ctx.textBaseline='bottom';ctx.fillText(o.xl,o.l+o.w,o.t+o.h-4);}
  if(o.yl){ctx.textAlign='left';ctx.textBaseline='top';ctx.fillText(o.yl,o.l+6,o.t+2);}
  ctx.restore();
  return {X,Y,o};
}
function clipBox(ctx,o){ctx.save();ctx.beginPath();ctx.rect(o.l,o.t,o.w,o.h);ctx.clip();}
function curve(ctx,A,f,x0,x1,col,lw=2.5,dash=null,n=400){
  ctx.save();clipBox(ctx,A.o);ctx.strokeStyle=col;ctx.lineWidth=lw;ctx.lineJoin='round';if(dash)ctx.setLineDash(dash);
  ctx.beginPath();let pen=false;
  for(let i=0;i<=n;i++){const x=x0+(x1-x0)*i/n,y=f(x);
    if(!isFinite(y)||(A.o.logy&&y<=0)){pen=false;continue;}
    let py=A.Y(y);py=Math.max(-5e3,Math.min(5e3,py));
    if(pen)ctx.lineTo(A.X(x),py);else{ctx.moveTo(A.X(x),py);pen=true;}}
  ctx.stroke();ctx.restore();ctx.restore();
}
function dot(ctx,x,y,r,col,stroke){ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.fillStyle=col;ctx.fill();if(stroke){ctx.lineWidth=2;ctx.strokeStyle=stroke;ctx.stroke();}}
function label(ctx,t,x,y,col=K.ink,align='left',base='middle',font='600 12px Inter, sans-serif'){
  ctx.save();ctx.font=font;ctx.textAlign=align;ctx.textBaseline=base;ctx.lineWidth=4;ctx.strokeStyle='rgba(255,255,255,.92)';ctx.lineJoin='round';ctx.strokeText(t,x,y);ctx.fillStyle=col;ctx.fillText(t,x,y);ctx.restore();}
function arrow(ctx,x1,y1,x2,y2,col,lw=2.5,dash){
  const dx=x2-x1,dy=y2-y1,L=Math.hypot(dx,dy);if(L<1)return;const ux=dx/L,uy=dy/L,hd=Math.min(11,L*.45);
  ctx.save();ctx.strokeStyle=col;ctx.fillStyle=col;ctx.lineWidth=lw;ctx.lineCap='round';if(dash)ctx.setLineDash(dash);
  ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2-ux*hd*.8,y2-uy*hd*.8);ctx.stroke();ctx.setLineDash([]);
  ctx.beginPath();ctx.moveTo(x2,y2);ctx.lineTo(x2-ux*hd-uy*hd*.5,y2-uy*hd+ux*hd*.5);ctx.lineTo(x2-ux*hd+uy*hd*.5,y2-uy*hd-ux*hd*.5);ctx.closePath();ctx.fill();ctx.restore();}
/* color de una longitud de onda visible (nm) */
function wlRGB(l,a=1){
  let r=0,g=0,b=0;
  if(l>=380&&l<440){r=-(l-440)/60;b=1;}else if(l<490){g=(l-440)/50;b=1;}else if(l<510){g=1;b=-(l-510)/20;}
  else if(l<580){r=(l-510)/70;g=1;}else if(l<645){r=1;g=-(l-645)/65;}else if(l<=780){r=1;}
  let f=l<380||l>780?0:l<420?.3+.7*(l-380)/40:l>700?.3+.7*(780-l)/80:1;
  const c=v=>Math.round(255*Math.pow(v*f,.8));return `rgba(${c(r)},${c(g)},${c(b)},${a})`;}

/* ---------- controles ---------- */
function sl(sec,id,fmt,cb){const el=sec.querySelector('#'+id),b=el.parentElement.querySelector('b');
  const up=()=>{if(b)b.textContent=fmt?fmt(+el.value):el.value;};el.addEventListener('input',()=>{up();cb&&cb();});up();
  return ()=>+el.value;}
function segm(sec,id,attr,cb){const c=sec.querySelector('#'+id);let v=c.querySelector('button.on').dataset[attr];
  c.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;c.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));v=b.dataset[attr];cb&&cb(v);});
  return ()=>v;}
function drag(cv,pick,move,end){
  let on=null;const pos=e=>{const r=cv.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top];};
  cv.addEventListener('pointerdown',e=>{const p=pos(e);on=pick(p[0],p[1]);if(on!=null){cv.setPointerCapture(e.pointerId);move(on,p[0],p[1]);e.preventDefault();}});
  cv.addEventListener('pointermove',e=>{if(on==null)return;const p=pos(e);move(on,p[0],p[1]);});
  const up=()=>{if(on!=null&&end)end(on);on=null;};cv.addEventListener('pointerup',up);cv.addEventListener('pointercancel',up);}

function line(ctx,x1,y1,x2,y2,col,lw=2,dash){ctx.save();ctx.strokeStyle=col;ctx.lineWidth=lw;if(dash)ctx.setLineDash(dash);ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.restore();}
function poly(ctx,pts,col,lw=2,dash,fill){ctx.save();ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));
  if(fill){ctx.closePath();ctx.fillStyle=fill;ctx.fill();}if(col){ctx.strokeStyle=col;ctx.lineWidth=lw;ctx.lineJoin='round';if(dash)ctx.setLineDash(dash);ctx.stroke();}ctx.restore();}
const DEG=Math.PI/180;
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));

/* ---------- registro de laboratorios ---------- */
const LABS={};
/* ================= UNIDAD I · PROPIEDADES DEL NÚCLEO ================= */
const HC=197.327, MN=939.565, MP=938.272, MH=938.783, ME=0.511, ALPHA=1/137.036, E2=1.44, U=931.494;
const lg=x=>Math.log10(x);
function tFmt(s){ // tiempo en s → texto legible
  if(!isFinite(s))return '∞';
  const y=3.156e7;
  if(s<1e-6)return sci(s*1e9,2)+' ns';if(s<1e-3)return nf(s*1e6,2)+' µs';if(s<1)return nf(s*1e3,2)+' ms';
  if(s<120)return nf(s,2)+' s';if(s<7200)return nf(s/60,1)+' min';if(s<2*86400)return nf(s/3600,1)+' h';
  if(s<y)return nf(s/86400,1)+' d';return sci(s/y,3)+' años';}

LABS['np-tamano']=function(sec){
  const cv=$('#nta-cv',sec),rd=$('#nta-read',sec),fv=$('#nta-fv',sec),frd=$('#nta-fread',sec);
  const gA=sl(sec,'nta-A',v=>v,()=>draw()),ga=sl(sec,'nta-a',v=>nf(v,2),()=>draw()),gr=sl(sec,'nta-r0',v=>nf(v,2),()=>draw()),gE=sl(sec,'nta-E',v=>v,()=>draw());
  const rho=(r,R,a)=>1/(1+Math.exp((r-R)/a));
  function norm(R,a){let s=0;const n=600,rm=R+12*a+2,h=rm/n;for(let i=0;i<=n;i++){const r=i*h;s+=(i%n?1:.5)*4*Math.PI*r*r*rho(r,R,a)*h;}return s;}
  function FF(q,R,a,N){if(q<1e-6)return 1;let s=0;const n=600,rm=R+12*a+2,h=rm/n;for(let i=1;i<=n;i++){const r=i*h;s+=(i%n?1:.5)*rho(r,R,a)*r*Math.sin(q*r)*h;}return 4*Math.PI*s/(q*N);}
  const FU=(q,R)=>{const x=q*R;return x<1e-4?1:3*(Math.sin(x)-x*Math.cos(x))/(x*x*x);};
  function drawR(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,400,270);
    const A=gA(),a=ga(),R=gr()*Math.cbrt(A),N=norm(R,a),Z=Math.round(A/(2+0.0157*A**(2/3))),r0=Z/N;
    const xm=Math.max(10,R+6*a+2);
    const P=axes(ctx,{l:52,t:54,w:w-68,h:h-96,xr:[0,xm],yr:[0,0.1],xl:'r (fm)',yl:'ρ (e/fm³)'});
    // esfera uniforme
    const ru=3*Z/(4*Math.PI*R**3);ctx.save();clipBox(ctx,P.o);line(ctx,P.X(0),P.Y(ru),P.X(R),P.Y(ru),K.ax,2,[6,4]);line(ctx,P.X(R),P.Y(ru),P.X(R),P.Y(0),K.ax,2,[6,4]);ctx.restore();ctx.restore();
    curve(ctx,P,r=>r0*rho(r,R,a),0,xm,K.a,3);
    const r90=R-a*Math.log(9),r10=R+a*Math.log(9);
    [r90,r10].forEach(x=>line(ctx,P.X(x),P.o.t,P.X(x),P.o.t+P.o.h,K.b,1.4,[3,3]));
    label(ctx,'t',P.X(R),P.o.t+10,K.b,'center');
    // tamaños a escala
    const nucs=[['⁴He',4],['¹⁶O',16],['⁵⁶Fe',56],['²⁰⁸Pb',208],['A='+A,A]];const sc=Math.min(3.2,(w-100)/(nucs.reduce((s,n)=>s+2*1.2*Math.cbrt(n[1]),0)+30));let x=60;
    nucs.forEach((n,i)=>{const rr=1.2*Math.cbrt(n[1])*sc;x+=rr;ctx.beginPath();ctx.arc(x,26,Math.min(rr,22),0,TAU);ctx.fillStyle=i===4?'rgba(217,72,15,.25)':'rgba(36,83,201,.18)';ctx.fill();ctx.strokeStyle=i===4?K.b:K.a;ctx.lineWidth=1.5;ctx.stroke();label(ctx,n[0],x,26,K.ink,'center','middle','600 10px Inter, sans-serif');x+=Math.min(rr,22)+8;});
    const rms=(()=>{let s=0;const n=600,rm=R+12*a+2,hh=rm/n;for(let i=0;i<=n;i++){const r=i*hh;s+=(i%n?1:.5)*4*Math.PI*r**4*rho(r,R,a)*hh;}return Math.sqrt(s/N);})();
    rd.innerHTML=row('Z (valle de estabilidad)',Z)+row('R = R₀A^1/3',nf(R,2)+' fm')+row('espesor t = 4,4 a',nf(4*Math.log(3)*a,2)+' fm')+row('ρ₀ de carga',nf(r0,4)+' e/fm³')+row('ρ₀ nucleones ≈ ρ₀A/Z',nf(r0*A/Z,3)+' fm⁻³')+sep+
      row('radio cuadrático medio',nf(rms,2)+' fm')+row('esfera uniforme √(3/5) R',nf(Math.sqrt(.6)*R,2)+' fm')+rowT('La densidad central casi no cambia con A: es la saturación nuclear.');}
  function drawF(){if(!vis(fv))return;const {ctx,w,h}=fit(fv,.62,400,270);
    const A=gA(),a=ga(),R=gr()*Math.cbrt(A),N=norm(R,a),E=gE(),qmax=Math.min(2*E/HC,3.2);
    const P=axes(ctx,{l:52,t:30,w:w-68,h:h-70,xr:[0,qmax],yr:[-6,0],logy:true,xl:'q (fm⁻¹)',yl:'|F(q)|²'});
    curve(ctx,P,q=>FU(q,R)**2,1e-3,qmax,K.ax,2,[5,4],500);
    curve(ctx,P,q=>FF(q,R,a,N)**2,1e-3,qmax,K.a,3,null,300);
    // eje superior: ángulo
    ctx.save();ctx.font='11px Inter, sans-serif';ctx.fillStyle=K.mut;ctx.textAlign='center';
    [20,40,60,90,120,180].forEach(t=>{const q=2*E*Math.sin(t*Math.PI/360)/HC;if(q<=qmax){const x=P.X(q);ctx.fillText(t+'°',x,P.o.t-14);line(ctx,x,P.o.t-6,x,P.o.t,K.ax,1);}});ctx.restore();
    const q1=4.493/R,t1=2*Math.asin(Math.min(1,q1*HC/(2*E)))*180/Math.PI;
    if(q1<qmax)line(ctx,P.X(q1),P.o.t,P.X(q1),P.o.t+P.o.h,K.b,1.4,[3,3]);
    frd.innerHTML=row('p c del electrón',nf(E,0)+' MeV')+row('λ̄ = ħ/p',nf(HC/E,3)+' fm')+row('q máximo (θ = 180°)',nf(2*E/HC,2)+' fm⁻¹')+sep+
      row('1.er cero (esfera) qR = 4,493',nf(q1,3)+' fm⁻¹')+row('ángulo del 1.er mínimo',q1*HC/(2*E)<1?nf(t1,1)+'°':'inaccesible')+rowT(q1*HC/(2*E)<1?'El ángulo del primer mínimo mide R directamente (Hofstadter, Nobel 1961).':'Energía insuficiente para ver el primer mínimo: sube E.');}
  function draw(){drawR();drawF();}
  return {draw};
};

/* ---------- datos B/A experimentales (AME2020, MeV) ---------- */
const BEXP=[[2,1,1.112],[3,2,2.573],[4,2,7.074],[6,3,5.332],[7,3,5.606],[9,4,6.463],[12,6,7.680],[14,7,7.476],[16,8,7.976],[20,10,8.032],[24,12,8.261],[28,14,8.448],[32,16,8.493],[40,20,8.551],[48,20,8.667],[56,26,8.790],[58,28,8.732],[62,28,8.795],[64,30,8.736],[88,38,8.733],[90,40,8.710],[120,50,8.505],[138,56,8.393],[140,58,8.376],[184,74,8.005],[197,79,7.916],[208,82,7.867],[232,90,7.615],[235,92,7.591],[238,92,7.570]];
function semf(A,Z,c){const N=A-Z;let d=0;if(A%2===0)d=(Z%2===0?1:-1)*c.ap*A**-0.75;
  return {v:c.av*A,s:-c.as*A**(2/3),c:-c.ac*Z*(Z-1)/Math.cbrt(A),a:-c.aa*(A-2*Z)**2/A,p:d,get B(){return this.v+this.s+this.c+this.a+this.p;}};}
const BSE=(A,Z,c)=>{if(Z<0||Z>A)return -1e9;return semf(A,Z,c).B;};
const MAT=(A,Z,c)=>Z*MH+(A-Z)*MN-BSE(A,Z,c);

LABS['np-enlace']=function(sec){
  const cv=$('#nen-cv',sec),rd=$('#nen-read',sec),ch=$('#nen-ch',sec),crd=$('#nen-cread',sec);
  const gv=sl(sec,'nen-av',v=>nf(v,1),()=>draw()),gs=sl(sec,'nen-as',v=>nf(v,1),()=>draw()),gc=sl(sec,'nen-ac',v=>nf(v,2),()=>draw()),ga=sl(sec,'nen-aa',v=>nf(v,1),()=>draw()),gA=sl(sec,'nen-A',v=>v,()=>draw());
  const gm=segm(sec,'nen-mode','m',()=>draw());let sel={Z:26,N:30};
  const C=()=>({av:gv(),as:gs(),ac:gc(),aa:ga(),ap:34});
  const Z0=(A,c)=>A/(2+c.ac/(2*c.aa)*A**(2/3));
  const bestZ=(A,c)=>{let bz=1,bb=-1e9;const z0=Math.round(Z0(A,c));for(let z=Math.max(1,z0-3);z<=Math.min(A,z0+3);z++){const B=BSE(A,z,c);if(B>bb){bb=B;bz=z;}}return bz;};
  function drawBA(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,400,280);const c=C();
    const P=axes(ctx,{l:44,t:14,w:w-60,h:h-46,xr:[0,250],yr:[0,11],xl:'A',yl:'B/A (MeV)'});
    const part=(A,k)=>{A=Math.round(A);if(A<4)return NaN;const r=semf(A,bestZ(A,c),c);return (k===0?r.v+r.s:k===1?r.v+r.s+r.c:r.B)/A;};
    curve(ctx,P,A=>part(A,0),4,250,K.r,1.8,[5,4],246);curve(ctx,P,A=>part(A,1),4,250,'#c92a2a',1.8,[5,4],246);
    curve(ctx,P,A=>part(A,2),4,250,K.a,3,null,246);
    label(ctx,'volumen + superficie',P.X(26),P.Y(part(26,0))-10,K.r,'left','middle','600 10px Inter, sans-serif');
    label(ctx,'+ Coulomb',P.X(200),P.Y(part(200,1))-10,'#c92a2a','left','middle','600 10px Inter, sans-serif');
    let chi=0;BEXP.forEach(([A,Z,b])=>{dot(ctx,P.X(A),P.Y(b),4.2,K.b,'#fff');if(A>=12){const d=BSE(A,Z,c)/A-b;chi+=d*d;}});
    const A=gA(),Z=bestZ(A,c),r=semf(A,Z,c);
    line(ctx,P.X(A),P.o.t,P.X(A),P.o.t+P.o.h,K.ink,1.2,[3,3]);dot(ctx,P.X(A),P.Y(r.B/A),6,K.a,'#fff');
    rd.innerHTML=row('A, Z más ligado (Z₀)',A+', '+Z+' ('+nf(Z0(A,c),2)+')')+row('volumen a_vA',nf(r.v,1)+' MeV')+row('superficie',nf(r.s,1)+' MeV')+row('Coulomb',nf(r.c,1)+' MeV')+row('asimetría',nf(r.a,1)+' MeV')+row('apareamiento δ',nf(r.p,2)+' MeV')+sep+
      row('B total',nf(r.B,1)+' MeV')+row('B/A',nf(r.B/A,3)+' MeV')+row('desviación cuadrática media (A ≥ 12)',nf(Math.sqrt(chi/BEXP.filter(b=>b[0]>=12).length),3)+' MeV');}
  let G=null;
  function mode(A,Z,c){const B=BSE(A,Z,c);if(B<=0)return null;const N=A-Z;
    const Sn=B-BSE(A-1,Z,c),Sp=B-BSE(A-1,Z-1,c);if(Sn<0||Sp<0)return null;
    const M=MAT(A,Z,c);const bm=Z<A&&MAT(A,Z+1,c)<M,bp=Z>1&&MAT(A,Z-1,c)<M;
    let Qa=-1;if(A>8&&Z>2){Qa=M-MAT(A-4,Z-2,c)-(2*MH+2*MN-28.296);}
    return {B,M,bm,bp,Qa,Sn,Sp};}
  function drawCh(){if(!vis(ch))return;const {ctx,w,h}=fit(ch,.62,420,280);const c=C(),m=gm();
    const Nm=160,Zm=104,cs=Math.min((w-50)/Nm,(h-40)/Zm),ox=36,oy=h-26;G={cs,ox,oy};
    ctx.fillStyle=K.gr;ctx.fillRect(ox,oy-Zm*cs,Nm*cs,Zm*cs);
    for(let Z=1;Z<Zm;Z++)for(let N=0;N<Nm;N++){const A=Z+N;if(A<4)continue;const d=mode(A,Z,c);if(!d)continue;
      let col;if(m==='ba'){const t=Math.max(0,Math.min(1,(d.B/A-6.5)/2.4));col=`hsl(${240-200*t},70%,${62-18*t}%)`;}
      else col=d.bm?'#5b8def':d.bp?'#e8590c':(d.Qa>4?'#f2c94c':'#1c2230');
      ctx.fillStyle=col;ctx.fillRect(ox+N*cs,oy-(Z+1)*cs,Math.max(1,cs),Math.max(1,cs));}
    line(ctx,ox,oy,ox+Zm*cs,oy-Zm*cs,'#1c2230',1.2,[4,3]);
    const pts=[];for(let A=4;A<=264;A++){const z=Z0(A,c);if(z<Zm&&A-z<Nm)pts.push([ox+(A-z)*cs,oy-z*cs]);}poly(ctx,pts,'#fff',1.6);
    ctx.strokeStyle=K.ink;ctx.lineWidth=1.5;ctx.strokeRect(ox+sel.N*cs-2,oy-(sel.Z+1)*cs-2,cs+4,cs+4);
    ctx.save();ctx.font='11px Inter, sans-serif';ctx.fillStyle=K.mut;ctx.textAlign='center';for(let N=0;N<=Nm;N+=40)ctx.fillText(N,ox+N*cs,oy+12);ctx.textAlign='right';for(let Z=0;Z<=Zm;Z+=20)ctx.fillText(Z,ox-4,oy-Z*cs);ctx.restore();
    label(ctx,'N',ox+Nm*cs-6,oy-8,K.ink,'right');label(ctx,'Z',ox+4,oy-Zm*cs+8,K.ink,'left');
    [2,8,20,28,50,82,126].forEach(n=>{if(n<Nm)line(ctx,ox+n*cs,oy,ox+n*cs,oy-Zm*cs,'rgba(28,34,48,.12)',1);if(n<Zm)line(ctx,ox,oy-n*cs,ox+Nm*cs,oy-n*cs,'rgba(28,34,48,.12)',1);});
    const A=sel.Z+sel.N,d=mode(A,sel.Z,c);
    crd.innerHTML=row('núcleo seleccionado','Z = '+sel.Z+', N = '+sel.N+', A = '+A)+(d?row('B (fórmula)',nf(d.B,1)+' MeV')+row('B/A',nf(d.B/A,3)+' MeV')+row('S_n, S_p',nf(d.Sn,2)+', '+nf(d.Sp,2)+' MeV')+sep+
      row('predicción',d.bm?'β⁻ (Q = '+nf(d.M-MAT(A,sel.Z+1,c),2)+' MeV)':d.bp?'β⁺/CE (ΔM = '+nf(d.M-MAT(A,sel.Z-1,c),2)+' MeV)':d.Qa>4?'α (Q = '+nf(d.Qa,2)+' MeV)':'estable frente a β'+(d.Qa>0?' (Q_α = '+nf(d.Qa,2)+' MeV, α lenta)':''))
      :rowT('Fuera de las líneas de goteo: según la fórmula, este núcleo no está ligado.'))+
      (gm()==='dec'?rowT('<span style="color:#5b8def">■</span> β⁻ · <span style="color:#e8590c">■</span> β⁺/CE · <span style="color:#d4a72c">■</span> α (Q &gt; 4 MeV) · <b>■</b> estable'):rowT('Color: B/A de 6,5 (azul) a 8,9 MeV (rojo).'));}
  ch.addEventListener('click',e=>{if(!G)return;const r=ch.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;
    const N=Math.floor((x-G.ox)/G.cs),Z=Math.floor((G.oy-y)/G.cs);if(N>=0&&Z>=1&&N<160&&Z<104){sel={Z,N};drawCh();}});
  function draw(){drawBA();drawCh();}
  return {draw};
};

LABS['np-fuerza']=function(sec){
  const cv=$('#nfu-cv',sec),rd=$('#nfu-read',sec),yv=$('#nfu-yv',sec),yrd=$('#nfu-yread',sec);
  const gV=sl(sec,'nfu-V',v=>nf(v,1),()=>draw()),gR=sl(sec,'nfu-R',v=>nf(v,2),()=>draw()),gm=sl(sec,'nfu-m',v=>v,()=>draw());
  const mu=(MP*MN)/(MP+MN);
  function solve(V0,R){const f=B=>{const k=Math.sqrt(2*mu*(V0-B))/HC,kap=Math.sqrt(2*mu*B)/HC;return k/Math.tan(k*R)+kap;};
    const x0=Math.sqrt(2*mu*V0)/HC*R;if(x0<=Math.PI/2)return null;
    // raíz con kR en (π/2, π]: buscar B en (0,V0) donde kR ∈ (π/2,π)
    let hi=V0-1e-9,lo=1e-9;const kOf=B=>Math.sqrt(2*mu*(V0-B))/HC*R;
    // restringir a la primera rama: kR<π
    const Bpi=V0-(Math.PI*HC/R)**2/(2*mu);if(Bpi>lo)lo=Bpi+1e-9;
    if(f(lo)*f(hi)>0)return null;
    for(let i=0;i<100;i++){const m=(lo+hi)/2;if(f(lo)*f(m)<=0)hi=m;else lo=m;}
    return (lo+hi)/2;}
  function drawP(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,400,270);const V0=gV(),R=gR();
    const B=solve(V0,R),xm=Math.max(12,R*4);
    const P=axes(ctx,{l:46,t:14,w:w-62,h:h-46,xr:[0,xm],yr:[-V0*1.1,V0*0.55],xl:'r (fm)',yl:'V (MeV)'});
    poly(ctx,[[P.X(0),P.Y(-V0)],[P.X(R),P.Y(-V0)],[P.X(R),P.Y(0)],[P.X(xm),P.Y(0)]],K.ink,2.5);
    const Vmin=Math.PI**2*HC**2/(8*mu*R*R);
    if(B){const k=Math.sqrt(2*mu*(V0-B))/HC,kap=Math.sqrt(2*mu*B)/HC,Bc=Math.sin(k*R)*Math.exp(kap*R);
      const u=r=>r<R?Math.sin(k*r):Bc*Math.exp(-kap*r);
      let I1=0,I2=0;const n=2000,rm=R+12/kap;for(let i=0;i<n;i++){const r=(i+.5)*rm/n,v=u(r)**2*rm/n;if(r<R)I1+=v;else I2+=v;}
      const amp=V0*0.45;line(ctx,P.X(0),P.Y(-B),P.X(xm),P.Y(-B),K.b,1.6,[5,4]);label(ctx,'E = −'+nf(B,3)+' MeV',P.X(xm)-4,P.Y(-B)-10,K.b,'right');
      ctx.save();clipBox(ctx,P.o);ctx.beginPath();ctx.moveTo(P.X(R),P.Y(-B));for(let i=0;i<=200;i++){const r=R+(xm-R)*i/200;ctx.lineTo(P.X(r),P.Y(-B+amp*u(r)));}ctx.lineTo(P.X(xm),P.Y(-B));ctx.closePath();ctx.fillStyle='rgba(36,83,201,.15)';ctx.fill();ctx.restore();ctx.restore();
      curve(ctx,P,r=>-B+amp*u(r),0,xm,K.a,3);
      rd.innerHTML=row('energía de ligadura B',nf(B,3)+' MeV')+row('k (dentro)',nf(k,4)+' fm⁻¹')+row('kR',nf(k*R,3)+' rad')+row('κ (fuera)',nf(kap,4)+' fm⁻¹')+row('alcance 1/κ',nf(1/kap,2)+' fm')+sep+
        row('probabilidad fuera del pozo',nf(100*I2/(I1+I2),1)+' %')+row('V₀ mínimo para ligar',nf(Vmin,2)+' MeV')+rowT(Math.abs(B-2.224)<0.02?'¡Reproduce el deuterón real (2,224 MeV)!':'Ajusta V₀ para obtener B = 2,224 MeV.');}
    else rd.innerHTML=row('V₀ mínimo para ligar',nf(Vmin,2)+' MeV')+rowT('No hay estado ligado: V₀R² &lt; π²ħ²/8μ. Haz el pozo más profundo o más ancho.');}
  function drawY(){if(!vis(yv))return;const {ctx,w,h}=fit(yv,.62,400,270);const m=gm(),a=m>0?HC/m:Infinity;
    const P=axes(ctx,{l:46,t:14,w:w-62,h:h-46,xr:[0,5],yr:[0,1.1],xl:'r (fm)',yl:'|r V(r)| (relativo)'});
    curve(ctx,P,()=>1,0,5,K.ax,2,[6,4]);curve(ctx,P,r=>Math.exp(-r/a),0,5,K.a,3);
    if(isFinite(a)&&a<5){line(ctx,P.X(a),P.Y(0),P.X(a),P.Y(1/Math.E),K.b,1.5,[3,3]);label(ctx,'a = ħ/mc',P.X(a)+4,P.Y(1/Math.E)-10,K.b,'left');}
    const ref=[[0,'fotón (Coulomb)'],[139.6,'pion π'],[548,'mesón η'],[775,'mesón ρ'],[783,'mesón ω']];const near=ref.reduce((p,q)=>Math.abs(q[0]-m)<Math.abs(p[0]-m)?q:p);
    yrd.innerHTML=row('masa del mesón',m+' MeV/c²')+row('alcance a = ħc/mc²',isFinite(a)?nf(a,3)+' fm':'∞')+row('V(2 fm)/V_Coulomb(2 fm)',nf(Math.exp(-2/a),4))+sep+rowT('Más cercano: '+near[1]+'. '+(m<200?'Alcance de la parte atractiva de la fuerza nuclear.':m>600?'Alcance del núcleo repulsivo (intercambio de ω).':'Alcance intermedio.'));}
  function draw(){drawP();drawY();}
  return {draw};
};

/* ================= UNIDAD II · MODELOS NUCLEARES ================= */
const LL='spdfghij';
function shellLevels(s){const kap=0.0637,muv=[0,0,0,0.35,0.625,0.63,0.448,0.434],out=[];
  for(let N=0;N<8;N++)for(let l=N;l>=0;l-=2){const n=(N-l)/2+1;(l>0?[2*l+1,2*l-1]:[1]).forEach(j2=>{const ls=j2===2*l+1?l/2:-(l+1)/2;
    const sh=(N>=6&&!(N===6&&j2===13))?0.3*s:0;out.push({E:N+1.5-kap*muv[N]*(l*(l+1)-N*(N+3)/2)-2*s*kap*ls+sh,nm:n+LL[l],j2,l,g:j2+1,N});});}
  return out.sort((a,b)=>a.E-b.E);}
LABS['np-capas']=function(sec){
  const cv=$('#nca-cv',sec),rd=$('#nca-read',sec);
  const gs=sl(sec,'nca-s',v=>nf(v,2),()=>draw()),gn=sl(sec,'nca-n',v=>v,()=>draw());
  function draw(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.85,560,360);const s=gs(),nn=gn();
    const all=shellLevels(s);const lv=[];{let c=0;for(const L of all){lv.push(L);c+=L.g;if(c>=126)break;}}const Emin=1.2,Emax=lv[lv.length-1].E+0.25;
    const yE=E=>h-18-(E-Emin)/(Emax-Emin)*(h-30),x0=60,x1=Math.min(w*.55,x0+150);
    let cum=0,left=nn,last=null;
    let ly=1e9;const LY=lv.map(L=>{const y=yE(L.E);ly=Math.min(y,ly-12);return ly;});
    lv.forEach((L,i)=>{const y=yE(L.E);line(ctx,x0,y,x1,y,L.l%2?K.b:K.a,2.4);line(ctx,x1,y,x1+4,LY[i],K.ax,1);
      label(ctx,L.nm+'_'+L.j2+'/2',x1+6,LY[i],K.ink,'left','middle','600 11px Inter, sans-serif');label(ctx,'('+L.g+')',x1+64,LY[i],K.mut,'left','middle','11px Inter, sans-serif');
      const k=Math.max(0,Math.min(L.g,left));for(let q=0;q<L.g;q++){const xx=x0+6+q*Math.min(9,(x1-x0-12)/L.g);ctx.beginPath();ctx.arc(xx,y-5,3,0,TAU);
        if(q<k){ctx.fillStyle=(left-q===1&&q===k-1)?K.b:K.ink;ctx.fill();}else{ctx.strokeStyle=K.ax;ctx.lineWidth=1;ctx.stroke();}}
      if(left>0&&left<=L.g)last={L,k:left};left-=L.g;cum+=L.g;
      const nx=all[i+1];if(nx&&nx.E-L.E>0.3){const ym=Math.max(10,(yE(nx.E)+y)/2);label(ctx,String(cum),x0-8,ym,K.r,'right','middle','700 13px Inter, sans-serif');line(ctx,x0-4,ym,x1+110,ym,'rgba(43,138,62,.35)',1,[2,3]);}});
    label(ctx,'E/ħω',8,10,K.mut,'left','middle','600 11px Inter, sans-serif');
    let msg='';const magic=[2,8,20,28,50,82,126];
    if(last){const L=last.L,par=L.l%2?'−':'+';
      if(nn%2===0)msg=row('J^π del estado fundamental','0⁺ (todos apareados)');
      else msg=row('último nucleón',L.nm+L.j2+'/2 (ℓ = '+L.l+')')+row('J^π predicho',L.j2+'/2'+par)+(last.k===L.g?rowT('Es un hueco en un nivel lleno: mismo j^π que una partícula.'):'');}
    const gl=[];all.reduce((c,L,i)=>{c+=L.g;const nx=all[i+1];if(nx&&nx.E-L.E>0.3&&c<=126)gl.push(c);return c;},0);
    rd.innerHTML=row('nucleones',nn)+msg+sep+row('capas cerradas (huecos &gt; 0,3 ħω)',gl.join(', '))+(gl.includes(114)?rowT('114: hueco que el modelo predice para protones (la "isla de estabilidad" de los superpesados), aún no confirmado.'):'')+rowT(magic.includes(nn)?'¡'+nn+' es un número mágico!':'Ejemplos: 9 → ¹⁷O (5/2⁺), 21 → ⁴¹Ca (7/2⁻), 7 → ¹⁵N (1/2⁻), 83 → ²⁰⁹Bi (9/2⁻).');}
  return {draw};
};

LABS['np-colectivos']=function(sec){
  const cv=$('#nco-cv',sec),rd=$('#nco-read',sec),ev=$('#nco-ev',sec),erd=$('#nco-eread',sec),sel=$('#nco-nuc',sec),rot=$('#nco-rot',sec);
  const gb=sl(sec,'nco-b',v=>nf(v,2),()=>draw()),gA=sl(sec,'nco-A',v=>v,()=>draw());let ang=0;
  const NUC=[['²³⁸U',[0,44.9,148.4,307.2,518.3]],['¹⁶⁶Er',[0,80.6,265.0,545.4,911.2]],['¹⁶⁴Dy',[0,73.4,242.2,501.3,843.7]],['¹⁵²Sm',[0,121.8,366.5,706.9,1125.4]],['¹¹⁴Cd',[0,558.4,1283.7],{tri:[1134.5,1209.7,1283.7]}],['¹⁰⁶Pd',[0,511.9,1229.3],{tri:[1133.8,1128.0,1229.3]}]];
  sel.innerHTML=NUC.map((n,i)=>`<option value="${i}">${n[0]}</option>`).join('');sel.onchange=()=>draw();
  const Y20=c=>Math.sqrt(5/(16*Math.PI))*(3*c*c-1);
  function drawF(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,380,260);const b=gb(),A=gA(),R=1.2*Math.cbrt(A);
    const cx=w*.42,cy=h/2,sc=Math.min(w*.32,h*.4)/(R*(1+Math.abs(b)*0.9));
    ctx.beginPath();ctx.arc(cx,cy,R*sc,0,TAU);ctx.strokeStyle=K.ax;ctx.setLineDash([5,4]);ctx.lineWidth=1.5;ctx.stroke();ctx.setLineDash([]);
    ctx.beginPath();for(let i=0;i<=200;i++){const th=TAU*i/200,r=R*(1+b*Y20(Math.cos(th)))*sc,ph=th+ang;const x=cx+r*Math.sin(ph),y=cy-r*Math.cos(ph);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}
    ctx.closePath();ctx.fillStyle='rgba(36,83,201,.16)';ctx.fill();ctx.strokeStyle=K.a;ctx.lineWidth=3;ctx.stroke();
    const ex=Math.sin(ang),ey=-Math.cos(ang),L=R*sc*1.5;line(ctx,cx-ex*L,cy-ey*L,cx+ex*L,cy+ey*L,K.b,1.4,[4,4]);
    arrow(ctx,cx+R*sc*1.25,cy+30,cx+R*sc*1.25,cy-30,K.r,2);label(ctx,'eje de rotación ⊥',cx+R*sc*1.25+6,cy,K.r,'left');
    const Z=Math.round(A/(2+0.0157*A**(2/3))),c=1+b*Y20(1),e=1+b*Y20(0),Q0=3/Math.sqrt(5*Math.PI)*R*R*Z*b*(1+0.16*b)/100;
    const Ir=0.4*A*931.5*R*R*(1+0.31*b),e2r=6*HC*HC/(2*Ir)*1000;
    rd.innerHTML=row('R promedio',nf(R,2)+' fm')+row('semieje polar / ecuatorial',nf(c/e,3))+row('forma',Math.abs(b)<0.05?'casi esférica':b>0?'prolata (cigarro)':'oblata (disco)')+row('Q₀ (Z = '+Z+')',nf(Q0,2)+' b')+sep+
      row('ħ²/2𝓘 rígido',nf(HC*HC/(2*Ir)*1000,2)+' keV')+row('E(2⁺) rígido · real ≈ 2×',nf(e2r,1)+' · ≈ '+nf(2*e2r,0)+' keV');}
  function drawE(){if(!vis(ev))return;const {ctx,w,h}=fit(ev,.62,380,260);const n=NUC[+sel.value],L=n[1],e2=L[1];
    const rotE=[0,2,4,6,8].map(J=>e2/6*J*(J+1)),vib=[0,e2,2*e2,3*e2,4*e2];const Em=Math.max(...L,...rotE.slice(0,L.length))*1.12;
    const y=E=>h-22-E/Em*(h-44),cols=[[w*.08,w*.3,'medido'],[w*.38,w*.6,'rotor'],[w*.68,w*.9,'vibrador']];
    cols.forEach(([a,b,t])=>label(ctx,t,(a+b)/2,12,K.mut,'center'));
    L.forEach((E,i)=>{line(ctx,cols[0][0],y(E),cols[0][1],y(E),K.ink,2.5);label(ctx,(2*i)+'⁺',cols[0][0]-4,y(E),K.ink,'right','middle','600 11px Inter, sans-serif');label(ctx,nf(E,1),cols[0][1]+2,y(E)-7,K.mut,'left','middle','10px Inter, sans-serif');});
    if(n[2])n[2].tri.forEach((E,i)=>{line(ctx,cols[0][0]+8,y(E)+(i-1)*5,cols[0][1]-8,y(E)+(i-1)*5,K.f,1.6,[3,2]);});
    rotE.slice(0,L.length).forEach((E,i)=>{line(ctx,cols[1][0],y(E),cols[1][1],y(E),K.a,2.5);label(ctx,nf(E,0),cols[1][1]+2,y(E)-7,K.a,'left','middle','10px Inter, sans-serif');});
    vib.slice(0,L.length).forEach((E,i)=>{if(y(E)>14){line(ctx,cols[2][0],y(E),cols[2][1],y(E),K.b,2.5);label(ctx,i===2?'0⁺,2⁺,4⁺':'',cols[2][1]+2,y(E)-7,K.b,'left','middle','10px Inter, sans-serif');}});
    const R42=L[2]/L[1];
    erd.innerHTML=row('E(2⁺)',nf(e2,1)+' keV')+row('E(4⁺)',nf(L[2],1)+' keV')+row('R₄/₂ = E(4⁺)/E(2⁺)',nf(R42,2))+row('ħ²/2𝓘 = E(2⁺)/6',nf(e2/6,2)+' keV')+sep+
      rowT(R42>3?'R₄/₂ ≈ 3,33: rotor deformado.':R42<2.6?'R₄/₂ ≈ 2: vibrador esférico. Líneas naranjas: triplete de dos fonones (0⁺, 2⁺, 4⁺) cerca de 2E(2⁺).':'Caso de transición.');}
  function draw(){drawF();drawE();}
  return {draw,tick(dt){if(rot.checked){ang+=dt*0.8;drawF();}}};
};

/* ================= UNIDAD III · DESINTEGRACIÓN ================= */
LABS['np-decaimiento']=function(sec){
  const cv=$('#nde-cv',sec),rd=$('#nde-read',sec),mv=$('#nde-mv',sec),mrd=$('#nde-mread',sec);
  const ga=sl(sec,'nde-ta',v=>nf(10**v,v<0?2:1)+' h',()=>draw()),gb=sl(sec,'nde-tb',v=>nf(10**v,v<0?2:1)+' h',()=>draw()),gq=segm(sec,'nde-q','q',()=>draw());
  const gn=sl(sec,'nde-n0',v=>v,()=>reset()),gt=sl(sec,'nde-th',v=>nf(v,1)+' s',()=>reset());$('#nde-go',sec).onclick=()=>reset();
  function chain(){const tA=10**ga(),tB=10**gb(),la=Math.LN2/tA,lb=Math.LN2/tB;
    const NB=t=>Math.abs(la-lb)<1e-12?la*t*Math.exp(-la*t):la/(lb-la)*(Math.exp(-la*t)-Math.exp(-lb*t));
    return {tA,tB,la,lb,NA:t=>Math.exp(-la*t),NB,NC:t=>1-Math.exp(-la*t)-NB(t)};}
  function drawC(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,400,270);const c=chain(),q=gq();
    const tm=c.tA/c.tB>20?12*c.tB:4*Math.max(c.tA,c.tB);
    const f=q==='a'?{A:t=>c.la*c.NA(t),B:t=>c.lb*c.NB(t)}:{A:c.NA,B:c.NB,C:c.NC};
    let ym=0;for(let i=0;i<=200;i++){const t=tm*i/200;ym=Math.max(ym,f.A(t),f.B(t));}
    const P=axes(ctx,{l:50,t:14,w:w-66,h:h-46,xr:[0,tm],yr:[0,ym*1.08],xl:'t (h)',yl:q==='a'?'𝒜 (relativa)':'N/N_A0'});
    if(f.C)curve(ctx,P,f.C,0,tm,K.r,2.5);curve(ctx,P,f.A,0,tm,K.a,3);curve(ctx,P,f.B,0,tm,K.b,3);
    const tmax=Math.abs(c.la-c.lb)<1e-12?1/c.la:Math.log(c.lb/c.la)/(c.lb-c.la);
    if(tmax<tm){line(ctx,P.X(tmax),P.o.t,P.X(tmax),P.o.t+P.o.h,K.ink,1.2,[3,3]);label(ctx,'t_máx',P.X(tmax)+4,P.o.t+30,K.ink,'left');}
    label(ctx,'A',P.X(tm*.03),P.Y(f.A(tm*.03))-10,K.a);label(ctx,'B',P.X(tmax<tm?tmax:tm*.5),P.Y(f.B(tmax<tm?tmax:tm*.5))-12,K.b);if(f.C)label(ctx,'C',P.X(tm*.92),P.Y(f.C(tm*.92))-10,K.r);
    const r=c.la<c.lb?c.lb/(c.lb-c.la):null,regime=c.tA/c.tB>50?'equilibrio secular (𝒜_B → 𝒜_A)':c.la<c.lb?'equilibrio transitorio (𝒜_B/𝒜_A → '+nf(r,3)+')':'sin equilibrio: el hijo vive más que el padre';
    rd.innerHTML=row('t½(A), t½(B)',nf(c.tA,2)+' h, '+nf(c.tB,2)+' h')+row('λ_A, λ_B',sci(c.la)+', '+sci(c.lb)+' h⁻¹')+row('t_máx de N_B',nf(tmax,2)+' h')+row('𝒜_B/𝒜_A al final',nf(c.lb*c.NB(tm)/(c.la*c.NA(tm)),3))+sep+rowT(regime);}
  let cells=[],t=0,hist=[],lam=0,N0=0,acc=0;
  function reset(){N0=gn();lam=Math.LN2/gt();cells=new Array(N0).fill(1);t=0;hist=[[0,N0]];acc=0;drawM();}
  function step(dt){if(!cells.length)return;const p=1-Math.exp(-lam*dt);let n=0;for(let i=0;i<cells.length;i++){if(cells[i]&&Math.random()<p)cells[i]=0;n+=cells[i];}t+=dt;acc+=dt;if(acc>0.1){hist.push([t,n]);acc=0;}}
  function drawM(){if(!vis(mv))return;const {ctx,w,h}=fit(mv,.62,400,270);const n=cells.reduce((a,b)=>a+b,0);
    const gh=h*.42,cols=Math.ceil(Math.sqrt(N0*(w-20)/gh)),rows=Math.ceil(N0/cols),cs=Math.min((w-20)/cols,gh/rows);
    cells.forEach((c,i)=>{ctx.fillStyle=c?K.a:'#e3ddcf';ctx.fillRect(10+(i%cols)*cs,6+Math.floor(i/cols)*cs,cs-1,cs-1);});
    const tm=Math.max(5*gt(),t);const P=axes(ctx,{l:46,t:gh+20,w:w-62,h:h-gh-50,xr:[0,tm],yr:[0,N0*1.05],xl:'t (s)',yl:'N'});
    ctx.save();clipBox(ctx,P.o);ctx.beginPath();for(let i=0;i<=100;i++){const x=tm*i/100,y=N0*Math.exp(-lam*x)+Math.sqrt(N0*Math.exp(-lam*x));i?ctx.lineTo(P.X(x),P.Y(y)):ctx.moveTo(P.X(x),P.Y(y));}
    for(let i=100;i>=0;i--){const x=tm*i/100,y=N0*Math.exp(-lam*x)-Math.sqrt(N0*Math.exp(-lam*x));ctx.lineTo(P.X(x),P.Y(y));}ctx.fillStyle='rgba(154,161,176,.25)';ctx.fill();ctx.restore();ctx.restore();
    curve(ctx,P,x=>N0*Math.exp(-lam*x),0,tm,K.ax,2,[5,4]);poly(ctx,hist.map(([a,b])=>[P.X(a),P.Y(b)]),K.a,2.5);
    mrd.innerHTML=row('t',nf(t,1)+' s')+row('sobreviven',n+' de '+N0)+row('esperado N₀e^(−λt)',nf(N0*Math.exp(-lam*t),1)+' ± '+nf(Math.sqrt(N0*Math.exp(-lam*t)),1))+row('actividad λN',nf(lam*n,1)+' Bq');}
  reset();
  function draw(){drawC();drawM();}
  return {draw,tick(dt){if(!vis(mv))return;if(cells.some(c=>c)){step(dt);drawM();}}};
};

const ALFA=[['²³²Th',90,232,4.082,1.405e10*3.156e7],['²³⁸U',92,238,4.270,4.468e9*3.156e7],['²³⁴U',92,234,4.858,2.455e5*3.156e7],['²³⁰Th',90,230,4.770,7.54e4*3.156e7],['²²⁶Ra',88,226,4.871,1600*3.156e7],['²²²Rn',86,222,5.590,3.8235*86400],['²¹⁸Po',84,218,6.115,186],['²¹⁴Po',84,214,7.833,164.3e-6],['²¹⁰Po',84,210,5.407,138.376*86400],['²¹²Po',84,212,8.954,0.299e-6],['²⁴¹Am',95,241,5.638,432.2*3.156e7],['²³⁹Pu',94,239,5.245,24110*3.156e7],['²²⁰Rn',86,220,6.405,55.6],['²¹⁶Po',84,216,6.906,0.145]];
function gamow(Zp,Ap,Q,V0=35){const Zd=Zp-2,Ad=Ap-4,m=3727.379*Ad/(Ad+4),R=1.2*(Math.cbrt(Ad)+Math.cbrt(4)),b=2*Zd*E2/Q,x=Math.min(1,R/b);
  const G=Math.sqrt(2*m*Q)/HC*b*(Math.acos(Math.sqrt(x))-Math.sqrt(x*(1-x)));const v=Math.sqrt(2*(Q+V0)/m),f=v*2.998e23/(2*R);
  return {Zd,m,R,b,G,f,VR:2*Zd*E2/R,lam:f*Math.exp(-2*G),t:Math.LN2/(f*Math.exp(-2*G)),v};}
LABS['np-alfa']=function(sec){
  const cv=$('#nal-cv',sec),rd=$('#nal-read',sec),gv=$('#nal-gv',sec),grd=$('#nal-gread',sec);
  const gZ=sl(sec,'nal-Z',v=>v,()=>draw()),gA=sl(sec,'nal-A',v=>v,()=>draw()),gQ=sl(sec,'nal-Q',v=>nf(v,2),()=>draw());
  function drawB(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,400,270);const g=gamow(gZ(),gA(),gQ()),Q=gQ();
    const xm=Math.min(140,Math.max(g.b*1.25,30));
    const P=axes(ctx,{l:46,t:14,w:w-62,h:h-46,xr:[0,xm],yr:[-40,Math.max(g.VR*1.1,Q+5)],xl:'r (fm)',yl:'V (MeV)'});
    poly(ctx,[[P.X(0),P.Y(-35)],[P.X(g.R),P.Y(-35)],[P.X(g.R),P.Y(g.VR)]],K.ink,2.5);curve(ctx,P,r=>2*g.Zd*E2/r,g.R,xm,K.ink,2.5);
    line(ctx,P.X(0),P.Y(Q),P.X(xm),P.Y(Q),K.b,1.8,[6,4]);label(ctx,'Q = '+nf(Q,2)+' MeV',P.X(xm)-4,P.Y(Q)-10,K.b,'right');
    ctx.save();clipBox(ctx,P.o);ctx.fillStyle='rgba(217,72,15,.12)';ctx.beginPath();ctx.moveTo(P.X(g.R),P.Y(Q));for(let i=0;i<=80;i++){const r=g.R+(g.b-g.R)*i/80;ctx.lineTo(P.X(r),P.Y(Math.max(Q,2*g.Zd*E2/r)));}ctx.lineTo(P.X(g.b),P.Y(Q));ctx.fill();ctx.restore();ctx.restore();
    // función de onda esquemática
    const amp=Math.min(8,(g.VR-Q)*0.25),kin=Math.sqrt(2*g.m*(Q+35))/HC,kout=Math.sqrt(2*g.m*Q)/HC;
    const kap=r=>Math.sqrt(Math.max(0,2*g.m*(2*g.Zd*E2/r-Q)))/HC;let acc=0,pr=g.R;const tail=Math.exp(-3);
    const pts=[];for(let i=0;i<=500;i++){const r=xm*i/500;let y;
      if(r<g.R)y=amp*Math.sin(kin*r*0.25);else if(r<g.b){acc+=kap(r)*(r-pr);pr=r;y=amp*Math.sin(kin*g.R*0.25)*Math.exp(-3*acc/g.G);}else{y=amp*Math.sin(kin*g.R*0.25)*tail*Math.cos(kout*(r-g.b)*0.6)*1.6;}
      pts.push([P.X(r),P.Y(Q+y)]);}
    poly(ctx,pts,K.a,2.2);label(ctx,'R',P.X(g.R),P.Y(-35)+12,K.ink,'center');label(ctx,'b',P.X(g.b),P.Y(Q)+12,K.b,'center');
    rd.innerHTML=row('hijo: Z′, A′',g.Zd+', '+(gA()-4))+row('T_α = Q(A−4)/A',nf(Q*(gA()-4)/gA(),3)+' MeV')+row('R (contacto)',nf(g.R,2)+' fm')+row('V(R) altura de barrera',nf(g.VR,1)+' MeV')+row('b (punto de retorno)',nf(g.b,1)+' fm')+sep+
      row('factor de Gamow G',nf(g.G,2))+row('P = e^(−2G)',sci(Math.exp(-2*g.G)))+row('f = v/2R',sci(g.f)+' s⁻¹')+row('t½ estimado',tFmt(g.t));}
  function drawG(){if(!vis(gv))return;const {ctx,w,h}=fit(gv,.62,400,270);
    const P=axes(ctx,{l:50,t:14,w:w-66,h:h-46,xr:[26,46],yr:[-8,20],xl:'Z′/√Q',yl:'log₁₀ t½ (s)'});
    [[84,212,K.a],[92,236,K.r]].forEach(([Z,A,col])=>curve(ctx,P,x=>{const Q=((Z-2)/x)**2;return Math.log10(gamow(Z,A,Q).t);},26,46,col,2.4,null,200));
    ALFA.forEach(([n,Z,A,Q,t])=>{const x=(Z-2)/Math.sqrt(Q),y=Math.log10(t);const odd=A%2===1;dot(ctx,P.X(x),P.Y(y),5,odd?K.w:K.b,'#fff');label(ctx,n,P.X(x)+7,P.Y(y)-6,K.mut,'left','middle','10px Inter, sans-serif');});
    label(ctx,'teoría, Z′ = 82',P.X(27),P.Y(-6),K.a,'left');label(ctx,'teoría, Z′ = 90',P.X(36),P.Y(-6.5),K.r,'left');
    grd.innerHTML=row('rango de t½','de 0,3 µs (²¹²Po) a 1,4×10¹⁰ años (²³²Th)')+row('rango de Q','de 4,1 a 9,0 MeV')+sep+rowT('<span style="color:#d9480f">●</span> par-par · <span style="color:#c92a2a">●</span> A impar (impedidas).')+rowT('La teoría usa V₀ = 35 MeV y R₀ = 1,2 fm, sin ajustar nada más.');}
  function draw(){drawB();drawG();}
  return {draw};
};

function fermiF(Z,T,sgn){const E=T+ME,pc=Math.sqrt(T*(T+2*ME)),beta=pc/E;if(Z===0)return 1;const x=-sgn*2*Math.PI*Z*ALPHA/beta;return Math.abs(x)<1e-9?1:x/(1-Math.exp(-x));}
LABS['np-beta']=function(sec){
  const cv=$('#nbe-cv',sec),rd=$('#nbe-read',sec),kv=$('#nbe-kv',sec),krd=$('#nbe-kread',sec),zz=$('#nbe-z',sec);
  const gQ=sl(sec,'nbe-Q',v=>v,()=>draw()),gZ=sl(sec,'nbe-Z',v=>v,()=>draw()),gs=segm(sec,'nbe-s','s',()=>draw()),gm=sl(sec,'nbe-m',v=>nf(v,1),()=>draw());zz.onchange=()=>draw();
  function drawS(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,400,270);const Q=gQ()/1000,Z=gZ(),s=+gs();
    const N=(T,F)=>{if(T<=0||T>=Q)return 0;const pc=Math.sqrt(T*(T+2*ME));return (F?fermiF(Z,T,s):1)*pc*(T+ME)*(Q-T)**2;};
    let mx=0,mx0=0,S=0,ST=0,Tp=0;const n=600;for(let i=1;i<n;i++){const T=Q*i/n,v=N(T,1);if(v>mx){mx=v;Tp=T;}mx0=Math.max(mx0,N(T,0));S+=v;ST+=v*T;}
    const P=axes(ctx,{l:46,t:14,w:w-62,h:h-46,xr:[0,gQ()],yr:[0,1.08],xl:'T (keV)',yl:'N(T) (relativo)'});
    curve(ctx,P,x=>N(x/1000,0)/mx0,0,gQ(),K.ax,2,[5,4]);curve(ctx,P,x=>N(x/1000,1)/mx,0,gQ(),K.a,3);
    line(ctx,P.X(ST/S*1000),P.o.t,P.X(ST/S*1000),P.o.t+P.o.h,K.b,1.4,[3,3]);label(ctx,'⟨T⟩',P.X(ST/S*1000)+4,P.o.t+10,K.b,'left');
    rd.innerHTML=row('proceso',(s<0?'β⁻':'β⁺')+', Z′ = '+Z)+row('T_máx = Q',nf(gQ(),0)+' keV')+row('T más probable',nf(Tp*1000,0)+' keV')+row('⟨T⟩',nf(ST/S*1000,0)+' keV ('+nf(100*ST/S/Q,0)+' % de Q)')+sep+
      row('F(Z′) a T = Q/2',nf(fermiF(Z,Q/2,s),3))+rowT('El neutrino se lleva en promedio Q − ⟨T⟩ = '+nf((Q-ST/S)*1000,0)+' keV.');}
  function drawK(){if(!vis(kv))return;const {ctx,w,h}=fit(kv,.62,400,270);const Q=18.59e-3,m=gm()*1e-6,z=zz.checked;
    const K0=(T,mm)=>{const d=Q-T;if(d<mm)return 0;return Math.sqrt(d*Math.sqrt(d*d-mm*mm));};
    if(z){const P=axes(ctx,{l:50,t:14,w:w-66,h:h-46,xr:[-30,4],yr:[0,32],xl:'T − Q (eV)',yl:'K (relativo)'});
      curve(ctx,P,x=>K0(Q+x*1e-6,0)*1e6,-30,4,K.ax,2,[5,4],600);curve(ctx,P,x=>K0(Q+x*1e-6,m)*1e6,-30,4,K.a,3,null,1200);
      if(m>0){line(ctx,P.X(-m*1e6),P.o.t,P.X(-m*1e6),P.o.t+P.o.h,K.b,1.4,[3,3]);label(ctx,'Q − m_νc²',P.X(-m*1e6)-4,P.o.t+10,K.b,'right');}}
    else{const P=axes(ctx,{l:50,t:14,w:w-66,h:h-46,xr:[0,20],yr:[0,1.05],xl:'T (keV)',yl:'K (relativo)'});
      curve(ctx,P,x=>K0(x*1e-3,0)/Q,0,20,K.ax,2,[5,4]);curve(ctx,P,x=>K0(x*1e-3,m)/Q,0,20,K.a,3,null,800);}
    // fracción de desintegraciones en el último eV
    let tot=0;const n=4000;for(let i=1;i<n;i++){const T=Q*i/n,pc=Math.sqrt(T*(T+2*ME));tot+=fermiF(2,T,-1)*pc*(T+ME)*(Q-T)**2*Q/n;}
    const pcQ=Math.sqrt(Q*(Q+2*ME)),cq=fermiF(2,Q,-1)*pcQ*(Q+ME),frac=cq*(1e-6)**3/3/tot;
    krd.innerHTML=row('Q del tritio',nf(Q*1e6/1000,2)+' keV')+row('m_νc² elegido',nf(gm(),1)+' eV')+row('nuevo extremo',nf((Q-m)*1e6/1000,4)+' keV')+sep+
      row('fracción en el último eV',sci(frac))+rowT('Solo ~2 de cada 10¹³ desintegraciones caen en el último eV: por eso medir m_ν exige fuentes intensísimas y espectrómetros enormes.');}
  function draw(){drawS();drawK();}
  return {draw};
};

const WEIS={E:[null,(A,E)=>1.0e14*A**(2/3)*E**3,(A,E)=>7.3e7*A**(4/3)*E**5,(A,E)=>34*A*A*E**7,(A,E)=>1.1e-5*A**(8/3)*E**9],M:[null,(A,E)=>5.6e13*E**3,(A,E)=>3.5e7*A**(2/3)*E**5,(A,E)=>16*A**(4/3)*E**7,(A,E)=>4.5e-6*A*A*E**9]};
LABS['np-gamma']=function(sec){
  const cv=$('#nga-cv',sec),rd=$('#nga-read',sec);
  const gJi=sl(sec,'nga-Ji',v=>jf(v),()=>draw()),gJf=sl(sec,'nga-Jf',v=>jf(v),()=>draw()),gE=sl(sec,'nga-E',v=>v,()=>draw()),gA=sl(sec,'nga-A',v=>v,()=>draw());
  const gpi=segm(sec,'nga-pi','p',()=>draw()),gpf=segm(sec,'nga-pf','p',()=>draw());
  function jf(v){return v%1?(2*v)+'/2':String(v);}
  function draw(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.7,420,290);const Ji=gJi(),Jf=gJf(),pi=+gpi(),pf=+gpf(),E=gE()/1000,A=gA();
    const ok=((Ji*2)%2)===((Jf*2)%2);const list=[];
    if(ok){const Lmin=Math.max(1,Math.abs(Ji-Jf)),Lmax=Ji+Jf,d=pi*pf;
      for(let L=Lmin;L<=Math.min(Lmax,4);L++){const pe=L%2?-1:1;['E','M'].forEach(t=>{const p=t==='E'?pe:-pe;if(p===d){const lam=WEIS[t][L](A,E);list.push({n:t+L,lam,t:Math.LN2/lam});}});}}
    // esquema de niveles
    const xl=20,xr=Math.min(130,w*.25),yi=40,yf=h-40;line(ctx,xl,yi,xr,yi,K.ink,3);line(ctx,xl,yf,xr,yf,K.ink,3);
    label(ctx,jf(Ji)+(pi>0?'⁺':'⁻'),xr+4,yi,K.ink,'left');label(ctx,jf(Jf)+(pf>0?'⁺':'⁻'),xr+4,yf,K.ink,'left');
    arrow(ctx,(xl+xr)/2,yi+4,(xl+xr)/2,yf-4,list.length?K.f:K.ax,2.5,list.length?null:[4,4]);label(ctx,gE()+' keV',(xl+xr)/2+6,(yi+yf)/2,K.f,'left');
    if(!list.length){label(ctx,!ok?'J entero ↔ semientero: imposible':(Ji===0&&Jf===0?'0 → 0: prohibida (solo conversión interna)':'ningún multipolo con L ≤ 4'),xr+40,h/2,K.w,'left');rd.innerHTML=rowT(!ok?'Un fotón lleva momento angular entero: J_i y J_f deben ser ambos enteros o ambos semienteros.':Ji===0&&Jf===0?'0⁺ → 0⁺: un fotón no puede llevar L = 0. Decae por conversión interna o, si E &gt; 1022 keV, creando un par e⁺e⁻.':'Se requiere L ≥ 5: transición extremadamente lenta.');return;}
    list.sort((a,b)=>b.lam-a.lam);
    const P=axes(ctx,{l:xr+70,t:14,w:w-xr-86,h:h-46,xr:[-18,12],yr:[0,list.length+0.5],xl:'log₁₀ t½ (s)',yt:[],yf:()=>''});
    list.forEach((it,i)=>{const y=list.length-i,lt=Math.log10(it.t);ctx.fillStyle=i===0?K.r:'rgba(36,83,201,.55)';const x0=P.X(-18),x1=P.X(Math.max(-18,Math.min(12,lt)));ctx.fillRect(x0,P.Y(y)-9,x1-x0,18);label(ctx,it.n,x0-6,P.Y(y),K.ink,'right');label(ctx,tFmt(it.t),x1+4,P.Y(y),K.mut,'left','middle','10px Inter, sans-serif');});
    const d=list[0];const ER=E*E/(2*A*931.5)*1e6;
    rd.innerHTML=row('multipolos permitidos',list.map(x=>x.n).join(', '))+row('dominante',d.n)+row('t½ de Weisskopf',tFmt(d.t))+row('ancho Γ = ħλ',sci(6.582e-16*d.lam)+' eV')+sep+
      row('retroceso E_R = E²/2Mc²',nf(ER,3)+' eV')+rowT(d.t>1e-3?'Vida media larga: es un isómero nuclear.':'Transición rápida; la mezcla '+(list.length>1?list[0].n+'+'+list[1].n+' es posible.':'tiene un solo multipolo.'));}
  return {draw};
};

/* ================= UNIDAD IV · REACCIONES ================= */
LABS['np-reacciones']=function(sec){
  const cv=$('#nre-cv',sec),rd=$('#nre-read',sec),bv=$('#nre-bv',sec),brd=$('#nre-bread',sec);
  const gT=sl(sec,'nre-T',v=>nf(v,1),()=>{traj=null;draw();}),gZ=sl(sec,'nre-Z',v=>v,()=>{traj=null;draw();});
  const gER=sl(sec,'nre-ER',v=>nf(v,2),()=>draw()),gG=sl(sec,'nre-G',v=>v,()=>draw());
  let traj=null;
  function build(){const T=gT(),Z=gZ();let A=2*Z;while(A<300&&A/(2+0.0157*A**(2/3))<Z)A++;const d=2*Z*E2/T,R=1.2*(Math.cbrt(A)+Math.cbrt(4)),W=Math.max(3.2*d,3*R);
    const out=[];const nb=15;for(let i=0;i<nb;i++){const b=(i-(nb-1)/2)/((nb-1)/2)*W*0.95+1e-3;
      let x=-1.6*W,y=b,vx=1,vy=0,pts=[[x,y]],hit=false,rmin=1e9;
      for(let k=0;k<6000;k++){const r=Math.hypot(x,y);rmin=Math.min(rmin,r);if(r<R){hit=true;break;}
        const dt=Math.min(0.02*r,W/200);const a=(d/2)/(r*r*r);
        const ax=a*x,ay=a*y;vx+=ax*dt;vy+=ay*dt;x+=vx*dt;y+=vy*dt;pts.push([x,y]);if(Math.abs(x)>1.7*W||Math.abs(y)>1.7*W)break;}
      out.push({b,pts,hit,th:Math.atan2(vy,vx)});}
    return {T,Z,A,d,R,W,out};}
  function drawR(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,400,270);if(!traj)traj=build();const t=traj;
    const sc=Math.min(w,h)/(2.6*t.W),cx=w/2,cy=h/2;const X=x=>cx+x*sc,Y=y=>cy-y*sc;
    ctx.beginPath();ctx.arc(cx,cy,t.R*sc,0,TAU);ctx.fillStyle='rgba(217,72,15,.25)';ctx.fill();ctx.strokeStyle=K.b;ctx.lineWidth=1.5;ctx.stroke();
    ctx.beginPath();ctx.arc(cx,cy,t.d*sc,0,TAU);ctx.strokeStyle=K.ax;ctx.setLineDash([4,4]);ctx.stroke();ctx.setLineDash([]);
    t.out.forEach(o=>poly(ctx,o.pts.map(p=>[X(p[0]),Y(p[1])]),o.hit?K.w:K.a,1.6));
    label(ctx,'d',X(t.d*0.71)+4,Y(t.d*0.71)-4,K.mut,'left');
    const b90=t.d/2,sr=t.R/t.d;
    rd.innerHTML=row('blanco',`Z = ${t.Z}, A ≈ ${t.A}`)+row('distancia mínima frontal d',nf(t.d,1)+' fm')+row('radio de contacto R',nf(t.R,1)+' fm')+row('d / R',nf(t.d/t.R,2))+sep+
      row('b para θ = 90°',nf(b90,1)+' fm')+row('σ(θ &gt; 90°) = π(d/2)²',nf(Math.PI*b90*b90/100,3)+' b')+rowT(t.d>t.R?'Coulomb puro: Rutherford vale a todos los ángulos.':'d &lt; R: las trayectorias rojas tocan el núcleo; la fuerza nuclear modifica la dispersión a ángulos grandes.');}
  function drawB(){if(!vis(bv))return;const {ctx,w,h}=fit(bv,.62,400,270);const ER=gER(),G=gG()/1000;
    const lb=E=>HC/Math.sqrt(2*MN*E*1e-6),pk=E=>4*Math.PI*lb(E)**2/100*0.06*0.94;
    const sig=E=>pk(ER)*(G*G/4)/((E-ER)**2+G*G/4)*Math.sqrt(ER/E)+2.7*Math.sqrt(0.0253/E);
    const P=axes(ctx,{l:50,t:14,w:w-66,h:h-46,xr:[Math.log10(ER/8),Math.log10(ER*6)],yr:[-1,5],logy:true,xl:'E (eV)',yl:'σ (b)',xf:v=>nf(10**v,v<0?2:1)});
    curve(ctx,P,x=>2.7*Math.sqrt(0.0253/10**x),P.o.xr[0],P.o.xr[1],K.ax,2,[5,4]);curve(ctx,P,x=>sig(10**x),P.o.xr[0],P.o.xr[1],K.a,3,null,3000);
    const tau=6.582e-16/G;
    brd.innerHTML=row('E_R',nf(ER,2)+' eV')+row('Γ (total)',nf(G*1000,0)+' meV')+row('λ̄ = ħ/p',nf(lb(ER),0)+' fm')+row('pico ≈ 4πλ̄² Γ_nΓ_γ/Γ²',sci(pk(ER))+' b')+sep+
      row('vida del núcleo compuesto τ = ħ/Γ',sci(tau)+' s')+rowT('Γ_n/Γ = 0,06 y Γ_γ/Γ = 0,94 (típico de ²³⁸U). λ̄ ≫ R: el neutrón "ve" mucho más que el núcleo geométrico.');}
  function draw(){drawR();drawB();}
  return {draw};
};

LABS['np-fision-fusion']=function(sec){
  const cv=$('#nff-cv',sec),rd=$('#nff-read',sec),gv=$('#nff-gv',sec),grd=$('#nff-gread',sec),sr=$('#nff-r',sec);
  const gk=sl(sec,'nff-k',v=>nf(v,2),()=>reset()),gT=sl(sec,'nff-T',v=>nf(v,1),()=>drawG());sr.onchange=()=>drawG();$('#nff-go',sec).onclick=()=>reset();
  let gen=[],pop=0,acc=0,dots=[];
  function reset(){gen=[20];pop=20;acc=0;dots=Array.from({length:20},()=>[Math.random(),Math.random()]);drawC();}
  function next(){const k=gk(),p=Math.min(1,k/3);let n=0;for(let i=0;i<pop;i++)for(let j=0;j<3;j++)if(Math.random()<p)n++;pop=n;gen.push(n);
    dots=Array.from({length:Math.min(n,400)},()=>[Math.random(),Math.random()]);}
  function drawC(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,400,280);const k=gk(),top=h*.36;
    ctx.fillStyle='rgba(36,83,201,.06)';ctx.fillRect(8,6,w-16,top-12);dots.forEach(([x,y])=>dot(ctx,12+x*(w-24),10+y*(top-20),2.4,K.b));
    const P=axes(ctx,{l:50,t:top+8,w:w-66,h:h-top-38,xr:[0,40],yr:[0,4],logy:true,xl:'generación',yl:'neutrones'});
    curve(ctx,P,n=>20*k**n,0,40,K.ax,2,[5,4]);poly(ctx,gen.map((v,i)=>[P.X(i),P.Y(Math.max(v,1))]),K.a,2.5);gen.forEach((v,i)=>{if(v>0)dot(ctx,P.X(i),P.Y(v),2.5,K.a);});
    rd.innerHTML=row('k',nf(k,2)+(k<0.999?' (subcrítico)':k>1.001?' (supercrítico)':' (crítico)'))+row('generación',gen.length-1)+row('neutrones vivos',pop>9999?'&gt; 10⁴':pop)+row('esperado 20·kⁿ',sci(20*k**(gen.length-1)))+sep+
      rowT(pop===0?'La cadena se extinguió.':pop>9999?'Crecimiento explosivo: con tiempos de generación de ~10 ns, un núcleo supercrítico sin neutrones retardados no se puede controlar.':'Con k = 1 exacto la población fluctúa y tarde o temprano se extingue: en un reactor se compensa con muchísimos neutrones.');}
  const REA={pp:{z:1,mu:469.14,n:'p + p'},dt:{z:1,mu:1124.6,n:'D + T'},pc:{z:6,mu:865.6,n:'p + ¹²C'}};
  function drawG(){if(!vis(gv))return;const {ctx,w,h}=fit(gv,.62,400,270);const r=REA[sr.value],kT=gT();
    const EG=2*r.mu*(Math.PI*ALPHA*r.z)**2*1000,E0=Math.cbrt(EG*kT*kT/4),D=4*Math.sqrt(E0*kT/3),xm=Math.max(2.2*E0,8*kT);
    const prod=E=>Math.exp(-E/kT-Math.sqrt(EG/E)),pm=prod(E0);
    const P=axes(ctx,{l:46,t:14,w:w-62,h:h-46,xr:[0,xm],yr:[0,1.08],xl:'E (keV)',yl:'relativo'});
    curve(ctx,P,E=>Math.exp(-E/kT),0,xm,K.ax,2.5);curve(ctx,P,E=>Math.exp(-Math.sqrt(EG/E))/Math.exp(-Math.sqrt(EG/xm)),1e-3,xm,K.a,2.5);
    curve(ctx,P,E=>prod(E)/pm,1e-3,xm,K.b,3.2);line(ctx,P.X(E0),P.o.t,P.X(E0),P.o.t+P.o.h,K.b,1.2,[3,3]);label(ctx,'E₀',P.X(E0)+4,P.o.t+10,K.b,'left');
    grd.innerHTML=row('reacción',r.n)+row('E_G = 2μc²(παZ₁Z₂)²',EG>2000?nf(EG/1000,2)+' MeV':nf(EG,0)+' keV')+row('kT',nf(kT,2)+' keV ('+sci(kT/8.617e-8)+' K)')+row('pico E₀',nf(E0,2)+' keV = '+nf(E0/kT,1)+' kT')+row('ancho Δ = 4√(E₀kT/3)',nf(D,2)+' keV')+sep+
      row('factor e^(−3E₀/kT)',sci(Math.exp(-3*E0/kT)))+rowT('Cuanto mayor Z₁Z₂, más alto el pico y menor el ritmo: por eso el ciclo CNO solo domina en estrellas más calientes que el Sol.');}
  reset();
  function draw(){drawC();drawG();}
  return {draw,tick(dt){if(!vis(cv))return;acc+=dt;if(acc>0.55&&pop>0&&pop<1e4&&gen.length<41){acc=0;next();drawC();}}};
};

/* ================= UNIDAD V · PARTÍCULAS ================= */
const QK={u:{Q:2/3,I:.5,S:0,B:1/3},d:{Q:-1/3,I:-.5,S:0,B:1/3},s:{Q:-1/3,I:0,S:-1,B:1/3},U:{Q:-2/3,I:-.5,S:0,B:-1/3},D:{Q:1/3,I:.5,S:0,B:-1/3},S:{Q:1/3,I:0,S:1,B:-1/3}};
const QN={u:'u',d:'d',s:'s',U:'ū',D:'d̄',S:'s̄'};
const MULT={
  ps:{t:'Nonete de mesones pseudoescalares 0⁻',p:[[-.5,1,'K⁰',497.6,'ds̄'],[.5,1,'K⁺',493.7,'us̄'],[-1,0,'π⁻',139.6,'dū'],[0,0,'π⁰ · η · η′',135.0,'(uū−dd̄)/√2 …'],[1,0,'π⁺',139.6,'ud̄'],[-.5,-1,'K⁻',493.7,'sū'],[.5,-1,'K̄⁰',497.6,'sd̄']]},
  oct:{t:'Octete de bariones 1/2⁺',p:[[-.5,1,'n',939.6,'udd'],[.5,1,'p',938.3,'uud'],[-1,0,'Σ⁻',1197.4,'dds'],[0,0,'Σ⁰ · Λ',1192.6,'uds'],[1,0,'Σ⁺',1189.4,'uus'],[-.5,-1,'Ξ⁻',1321.7,'dss'],[.5,-1,'Ξ⁰',1314.9,'uss']]},
  dec:{t:'Decuplete de bariones 3/2⁺',p:[[-1.5,1,'Δ⁻',1232,'ddd'],[-.5,1,'Δ⁰',1232,'udd'],[.5,1,'Δ⁺',1232,'uud'],[1.5,1,'Δ⁺⁺',1232,'uuu'],[-1,0,'Σ*⁻',1387.2,'dds'],[0,0,'Σ*⁰',1383.7,'uds'],[1,0,'Σ*⁺',1382.8,'uus'],[-.5,-1,'Ξ*⁻',1535.0,'dss'],[.5,-1,'Ξ*⁰',1531.8,'uss'],[0,-2,'Ω⁻',1672.5,'sss']]}};
LABS['np-simetrias']=function(sec){
  const cv=$('#nsi-cv',sec),rd=$('#nsi-read',sec);let built=[];
  const gm=segm(sec,'nsi-m','m',()=>{built=[];draw();});
  $('#nsi-q',sec).addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const q=b.dataset.q;if(q==='x')built=[];else if(built.length<3)built.push(q);draw();});
  function qn(){const r={Q:0,I:0,S:0,B:0};built.forEach(q=>{for(const k in r)r[k]+=QK[q][k];});r.Y=r.B+r.S;return r;}
  function draw(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.7,420,290);
    let m=gm();const n=qn(),nq=built.filter(q=>q===q.toLowerCase()).length,na=built.length-nq;
    let kind=null;if(built.length===2&&nq===1&&na===1)kind='ps';else if(built.length===3&&nq===3)kind=(built.every(q=>q===built[0]))?'dec':m==='ps'?'oct':m;
    if(kind&&kind!==m){m=kind;$$('#nsi-m button',sec).forEach(b=>b.classList.toggle('on',b.dataset.m===m));}
    const M=MULT[m];const Ymin=m==='dec'?-2:-1;
    const P=axes(ctx,{l:46,t:20,w:w-62,h:h-52,xr:[-2,2],yr:[Ymin-.6,1.6],xl:'I₃',yl:'Y',xt:[-1.5,-1,-.5,0,.5,1,1.5],yt:m==='dec'?[-2,-1,0,1]:[-1,0,1],xf:v=>v%1?(v>0?'':'−')+Math.abs(2*v)+'/2':nf(v,0),yf:v=>nf(v,0)});
    const pts=M.p.map(p=>[P.X(p[0]),P.Y(p[1])]);
    if(m!=='dec'){const hx=[[-.5,1],[.5,1],[1,0],[.5,-1],[-.5,-1],[-1,0],[-.5,1]];poly(ctx,hx.map(p=>[P.X(p[0]),P.Y(p[1])]),K.ax,1.5,[4,4]);}
    else poly(ctx,[[-1.5,1],[1.5,1],[0,-2],[-1.5,1]].map(p=>[P.X(p[0]),P.Y(p[1])]),K.ax,1.5,[4,4]);
    M.p.forEach((p,i)=>{const hit=kind&&Math.abs(p[0]-n.I)<1e-6&&Math.abs(p[1]-n.Y)<1e-6;dot(ctx,pts[i][0],pts[i][1],hit?13:9,hit?K.b:K.a,'#fff');
      label(ctx,p[2],pts[i][0],pts[i][1]-20,K.ink,'center');label(ctx,nf(p[3],0),pts[i][0],pts[i][1]+19,K.mut,'center','middle','10px Inter, sans-serif');});
    if(m==='dec'){[[1,1232],[0,1384.6],[-1,1533.4],[-2,1672.5]].forEach(([Y,ms])=>label(ctx,'⟨M⟩ = '+nf(ms,0),P.X(1.95),P.Y(Y),K.r,'right','middle','600 10px Inter, sans-serif'));}
    const cand=kind?M.p.filter(p=>Math.abs(p[0]-n.I)<1e-6&&Math.abs(p[1]-n.Y)<1e-6).map(p=>p[2]).join(' / '):'';
    const fr=v=>{const s=Math.round(v*3);if(s%3===0)return String(s/3).replace('-','−');return (s<0?'−':'')+Math.abs(s)+'/3';};
    const hf=v=>v%1?(v<0?'−':'')+Math.abs(2*v)+'/2':String(v).replace('-','−');
    rd.innerHTML=`<div style="font-weight:600;margin-bottom:6px">${M.t}</div>`+row('quarks',built.length?built.map(q=>QN[q]).join(' '):'—')+
      (built.length?row('carga Q',fr(n.Q))+row('número bariónico B',fr(n.B))+row('extrañeza S',n.S)+row('I₃',hf(n.I))+row('Y = B + S',fr(n.Y))+row('I₃ + Y/2',fr(n.I+n.Y/2)):'')+sep+
      rowT(kind?(cand?'Es: <b>'+cand+'</b>.':'Combinación válida, fuera de este multiplete.'):built.length?'Los hadrones son q q̄ (mesón) o q q q (barión): sigue añadiendo o borra.':'Construye un hadrón con los botones.')+
      (m==='dec'?rowT('Espaciado del decuplete ≈ 147 MeV por quark s: predice M(Ω⁻) ≈ 1680 MeV.'):'');}
  return {draw};
};

/* diagramas de Feynman: líneas en coordenadas [0,1]² */
const FD=[
  {n:'Dispersión de Møller e⁻e⁻ → e⁻e⁻',i:'electromagnética (QED)',o:'α² en σ (2 vértices)',L:[['f',.05,.12,.5,.3,'e⁻'],['f',.5,.3,.95,.12,'e⁻'],['f',.05,.88,.5,.7,'e⁻'],['f',.5,.7,.95,.88,'e⁻'],['g',.5,.3,.5,.7,'γ']],c:['vértice 1: e⁻ → e⁻ + γ (Q: −1 = −1 + 0) ✓','vértice 2: e⁻ + γ → e⁻ ✓','propagador 1/q²: canal t, gran σ a ángulos pequeños']},
  {n:'Aniquilación e⁺e⁻ → μ⁺μ⁻',i:'electromagnética (QED)',o:'α² en σ',L:[['f',.05,.12,.35,.5,'e⁻'],['f',.35,.5,.05,.88,'e⁺'],['g',.35,.5,.65,.5,'γ*'],['f',.95,.88,.65,.5,'μ⁺'],['f',.65,.5,.95,.12,'μ⁻']],c:['vértice 1: e⁻ + e⁺ → γ* (Q: 0, L_e: 0) ✓','vértice 2: γ* → μ⁻ + μ⁺ (L_μ: 0) ✓','canal s: el fotón virtual tiene q² = s &gt; 0']},
  {n:'Efecto Compton e⁻γ → e⁻γ',i:'electromagnética (QED)',o:'α² en σ',L:[['g',.05,.15,.38,.5,'γ'],['f',.05,.85,.38,.5,'e⁻'],['f',.38,.5,.62,.5,'e⁻*'],['g',.62,.5,.95,.15,'γ'],['f',.62,.5,.95,.85,'e⁻']],c:['vértice 1: e⁻ absorbe γ ✓','electrón virtual fuera de la capa de masa','vértice 2: emite γ ✓ (hay un segundo diagrama, canal u)']},
  {n:'Aniquilación e⁺e⁻ → γγ',i:'electromagnética (QED)',o:'α² en σ',L:[['f',.05,.12,.5,.3,'e⁻'],['f',.5,.3,.5,.7,'e*'],['f',.5,.7,.05,.88,'e⁺'],['g',.5,.3,.95,.12,'γ'],['g',.5,.7,.95,.88,'γ']],c:['vértice 1: e⁻ → e* + γ ✓','vértice 2: e* + e⁺ → γ ✓','un solo fotón no puede: no conservaría el 4-momento']},
  {n:'Desintegración β del neutrón (udd → uud)',i:'débil (corriente cargada)',o:'G_F² en Γ',L:[['f',.05,.12,.95,.12,'u',1],['f',.05,.24,.95,.24,'d',1],['f',.05,.38,.45,.38,'d'],['f',.45,.38,.95,.38,'u'],['w',.45,.38,.65,.72,'W⁻'],['f',.65,.72,.95,.92,'e⁻'],['f',.95,.6,.65,.72,'ν̄ₑ']],c:['vértice 1: d → u + W⁻ (Q: −1/3 = 2/3 − 1) ✓','vértice 2: W⁻ → e⁻ + ν̄ₑ (L_e: 0 = 1 − 1) ✓','quarks u y d espectadores; W virtual con q² ≪ M_W²']},
  {n:'Desintegración del muón μ⁻ → e⁻ ν̄ₑ ν_μ',i:'débil (corriente cargada)',o:'G_F² en Γ ∝ m_μ⁵',L:[['f',.05,.5,.4,.5,'μ⁻'],['f',.4,.5,.95,.25,'ν_μ'],['w',.4,.5,.65,.75,'W⁻'],['f',.65,.75,.95,.95,'e⁻'],['f',.95,.6,.65,.75,'ν̄ₑ']],c:['vértice 1: μ⁻ → ν_μ + W⁻ (L_μ: 1 = 1) ✓','vértice 2: W⁻ → e⁻ + ν̄ₑ (L_e: 0) ✓','proceso puramente leptónico: mide G_F']},
  {n:'Corriente neutra ν_μ e⁻ → ν_μ e⁻',i:'débil (corriente neutra)',o:'G_F² en σ',L:[['f',.05,.12,.5,.3,'ν_μ'],['f',.5,.3,.95,.12,'ν_μ'],['w',.5,.3,.5,.7,'Z⁰'],['f',.05,.88,.5,.7,'e⁻'],['f',.5,.7,.95,.88,'e⁻']],c:['vértice 1: ν_μ → ν_μ + Z⁰ ✓','vértice 2: e⁻ + Z⁰ → e⁻ ✓','sin cambio de carga: vista en Gargamelle (1973)']},
  {n:'Dispersión quark-quark u d → u d',i:'fuerte (QCD)',o:'α_s² en σ',L:[['f',.05,.12,.5,.3,'u'],['f',.5,.3,.95,.12,'u'],['q',.5,.3,.5,.7,'g'],['f',.05,.88,.5,.7,'d'],['f',.5,.7,.95,.88,'d']],c:['vértice 1: u_rojo → u_azul + g(rojo-antiazul) ✓','vértice 2: d_azul + g → d_rojo ✓','se conserva el color; el sabor no cambia']}];
function fline(ctx,t,x1,y1,x2,y2,col){
  if(t==='f'){line(ctx,x1,y1,x2,y2,col,2.4);const mx=(x1+x2)/2,my=(y1+y2)/2,ang=Math.atan2(y2-y1,x2-x1);ctx.save();ctx.translate(mx,my);ctx.rotate(ang);ctx.beginPath();ctx.moveTo(7,0);ctx.lineTo(-6,-6);ctx.lineTo(-6,6);ctx.closePath();ctx.fillStyle=col;ctx.fill();ctx.restore();return;}
  const L=Math.hypot(x2-x1,y2-y1),ux=(x2-x1)/L,uy=(y2-y1)/L,nx=-uy,ny=ux;ctx.save();ctx.strokeStyle=col;ctx.lineWidth=2.2;ctx.beginPath();
  if(t==='q'){const n=Math.max(4,Math.round(L/14));for(let i=0;i<=n*24;i++){const s=i/(n*24),ph=s*n*TAU,x=x1+ux*(L*s-5*Math.cos(ph)+5)+nx*6*Math.sin(ph),y=y1+uy*(L*s-5*Math.cos(ph)+5)+ny*6*Math.sin(ph);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}}
  else{const n=Math.max(3,Math.round(L/16));for(let i=0;i<=200;i++){const s=i/200,a=(t==='w'?7:5)*Math.sin(s*n*TAU);const x=x1+ux*L*s+nx*a,y=y1+uy*L*s+ny*a;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}}
  ctx.stroke();ctx.restore();}
LABS['np-feynman']=function(sec){
  const cv=$('#nfe-cv',sec),rd=$('#nfe-read',sec),rv=$('#nfe-rv',sec),rrd=$('#nfe-rread',sec),ps=$('#nfe-p',sec),qcd=$('#nfe-qcd',sec);
  ps.innerHTML=FD.map((d,i)=>`<option value="${i}">${d.n}</option>`).join('');ps.onchange=()=>draw();qcd.onchange=()=>draw();
  const gs=sl(sec,'nfe-s',v=>nf(v,1),()=>draw()),gn=sl(sec,'nfe-nc',v=>v,()=>draw());
  function drawD(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,380,260);const d=FD[+ps.value];const X=x=>30+x*(w-60),Y=y=>14+y*(h-28);
    const vtx=new Set();d.L.forEach(l=>{const col=l[0]==='f'?(l[6]?K.ax:K.a):l[0]==='g'?K.b:l[0]==='w'?K.d:K.r;fline(ctx,l[0],X(l[1]),Y(l[2]),X(l[3]),Y(l[4]),col);
      const mx=(X(l[1])+X(l[3]))/2,my=(Y(l[2])+Y(l[4]))/2,ang=Math.atan2(Y(l[4])-Y(l[2]),X(l[3])-X(l[1]));label(ctx,l[5],mx-Math.sin(ang)*14,my+Math.cos(ang)*14-0,K.ink,'center');
      if(!l[6]){[[l[1],l[2]],[l[3],l[4]]].forEach(p=>{if(p[0]>0.1&&p[0]<0.9)vtx.add(p.join());});}});
    vtx.forEach(s=>{const [x,y]=s.split(',').map(Number);dot(ctx,X(x),Y(y),5,K.ink);});
    arrow(ctx,X(0)-10,h-8,X(.25),h-8,K.ax,1.5);label(ctx,'tiempo',X(.27),h-8,K.mut,'left');
    rd.innerHTML=`<div style="font-weight:600;margin-bottom:6px">${d.n}</div>`+row('interacción',d.i)+row('vértices',vtx.size)+row('orden',d.o)+sep+d.c.map(t=>rowT('• '+t)).join('');}
  const thr=[[3.73,'c'],[10.56,'b']],RES=[[3.097,'J/ψ'],[3.686,'ψ′'],[9.460,'Υ'],[10.023,''],[10.355,'']];
  function Rof(s,nc,q){const Qs=[4/9,1/9,1/9];if(s>3.73)Qs.push(4/9);if(s>10.56)Qs.push(1/9);const nf_=Qs.length;const as=12*Math.PI/((33-2*nf_)*Math.log(s*s/0.04));return nc*Qs.reduce((a,b)=>a+b,0)*(q?1+as/Math.PI:1);}
  function drawR(){if(!vis(rv))return;const {ctx,w,h}=fit(rv,.62,380,260);const nc=gn(),q=qcd.checked,s0=gs();
    const P=axes(ctx,{l:40,t:14,w:w-56,h:h-46,xr:[1,40],yr:[0,6],xl:'√s (GeV)',yl:'R'});
    [[2,3,2.2,.2],[4.6,9,3.6,.3],[11,40,3.9,.2]].forEach(([a,b,v,e])=>{ctx.fillStyle='rgba(154,161,176,.3)';ctx.fillRect(P.X(a),P.Y(v+e),P.X(b)-P.X(a),P.Y(v-e)-P.Y(v+e));});
    RES.forEach(([m,n])=>{line(ctx,P.X(m),P.Y(0),P.X(m),P.Y(6),'rgba(217,72,15,.55)',2);if(n)label(ctx,n,P.X(m)+3,P.Y(5.6),K.b,'left','middle','600 10px Inter, sans-serif');});
    curve(ctx,P,s=>Rof(s,nc,q),1.2,40,K.a,3,null,800);line(ctx,P.X(s0),P.o.t,P.X(s0),P.o.t+P.o.h,K.ink,1.2,[3,3]);
    const sig=86.8/(s0*s0);
    rrd.innerHTML=row('√s',nf(s0,1)+' GeV')+row('quarks accesibles',s0<3.73?'u, d, s':s0<10.56?'u, d, s, c':'u, d, s, c, b')+row('R predicho',nf(Rof(s0,nc,q),2))+row('σ(e⁺e⁻ → μ⁺μ⁻)',sci(sig)+' nb')+row('σ(e⁺e⁻ → hadrones)',sci(sig*Rof(s0,nc,q))+' nb')+sep+
      rowT(nc===3?'Con 3 colores la curva cae dentro de las bandas medidas.':'Con N_c = '+nc+' la predicción no coincide con los datos.');}
  function draw(){drawD();drawR();}
  return {draw};
};

