LABS['np-debil']=function(sec){
  const cv=$('#ndb-cv',sec),rd=$('#ndb-read',sec),zv=$('#ndb-zv',sec),zrd=$('#ndb-zread',sec),mir=$('#ndb-mir',sec);
  const ga=sl(sec,'ndb-a',v=>nf(v,2),()=>{up=0;dn=0;parts=[];}),gn=sl(sec,'ndb-n',v=>v,()=>gen()),gr=sl(sec,'ndb-r',v=>nf(v,1),()=>{fitZ();drawZ();});
  mir.onchange=()=>{up=0;dn=0;parts=[];};$('#ndb-gen',sec).onclick=()=>gen();
  let parts=[],up=0,dn=0,acc=0;const beta=0.6;
  function emit(){const a=ga(),sgn=mir.checked?-1:1;let c;do{c=2*Math.random()-1;}while(Math.random()*(1+Math.abs(a)*beta)>1+a*beta*c);
    c*=sgn;const s=Math.sqrt(1-c*c)*(Math.random()<.5?-1:1);parts.push({x:0,y:0,vx:s,vy:c,t:0});if(c>0.707)up++;else if(c<-0.707)dn++;}
  function drawW(){if(!vis(cv))return;const {ctx,w,h}=fit(cv,.62,380,260);const cx=w/2,cy=h/2,R=Math.min(w,h)*.42,mirr=mir.checked;
    ctx.fillStyle='rgba(36,83,201,.05)';ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,R,-Math.PI*.75,-Math.PI*.25);ctx.fill();ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,R,Math.PI*.25,Math.PI*.75);ctx.fill();
    parts.forEach(p=>dot(ctx,cx+p.x*R,cy-p.y*R,2.2,K.b));
    ctx.beginPath();ctx.arc(cx,cy,14,0,TAU);ctx.fillStyle=K.a;ctx.fill();
    arrow(ctx,cx,cy+8,cx,cy-46,K.ink,3);label(ctx,'J',cx+8,cy-44,K.ink,'left');
    ctx.save();ctx.strokeStyle=K.ink;ctx.lineWidth=1.6;ctx.beginPath();ctx.ellipse(cx,cy-30,16,5,0,0.2,Math.PI*1.8);ctx.stroke();ctx.restore();
    label(ctx,'↑ '+up,cx,cy-R-2,K.ink,'center');label(ctx,'↓ '+dn,cx,cy+R+2,K.ink,'center');
    if(mirr)label(ctx,'IMAGEN EN EL ESPEJO (P)',10,14,K.w,'left');
    const A=(up+dn)?(up-dn)/(up+dn):0;
    rd.innerHTML=row('electrones hacia arriba (θ &lt; 45°)',up)+row('electrones hacia abajo (θ &gt; 135°)',dn)+row('asimetría medida (↑−↓)/(↑+↓)',nf(A,3))+row('esperado',nf((mirr?-1:1)*ga()*beta*0.854,3))+sep+
      rowT(Math.abs(ga())<0.01?'Con a = 0 el mundo y su reflejo son indistinguibles: paridad conservada.':mirr?'En el espejo los electrones salen a favor de J. Ese mundo no existe: la naturaleza solo realiza el original.':'Los electrones salen preferentemente opuestos a J (a &lt; 0): esto distingue el experimento de su imagen.');}
  // ---- resonancia Z ----
  const MZ=91.1876,GZ=2.4952,LO=60,HI=120,NB=60;let data=[],src='sim',fitR=null;
  function gauss(){let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(TAU*v);}
  function gen(){const N=gn(),res=gr();data=[];src='sim';
    for(let i=0;i<N;i++){let m;if(Math.random()<0.93){do{m=MZ+GZ/2*Math.tan(Math.PI*(Math.random()-.5));}while(m<40||m>140);m+=res*gauss();}else{m=LO-Math.log(1-Math.random()*(1-Math.exp(-(HI-LO)/25)))*25;}
      if(m>=LO&&m<HI)data.push(m);}
    fitZ();drawZ();}
  function hist(){const H=new Array(NB).fill(0);data.forEach(m=>{const k=Math.floor((m-LO)/(HI-LO)*NB);if(k>=0&&k<NB)H[k]++;});return H;}
  function voigt(m,M,G,s){let S=0,W=0;for(let k=-12;k<=12;k++){const x=k/4*s,g=Math.exp(-x*x/(2*s*s));const mm=m-x;S+=g*(mm*mm*G*G)/((mm*mm-M*M)**2+mm*mm*G*G);W+=g;}return S/W;}
  function fitZ(){const H=hist(),s=gr(),bw=(HI-LO)/NB,ctr=H.map((_,i)=>LO+(i+.5)*bw),bg=ctr.map(m=>Math.exp(-(m-LO)/25));let best=null;const grid=[];
    for(let M=89;M<=93.0001;M+=0.05)for(let G=0.5;G<=5.0001;G+=0.1){const f=ctr.map(m=>voigt(m,M,G,s));
      let a11=0,a12=0,a22=0,b1=0,b2=0;H.forEach((n,i)=>{const wgt=1/Math.max(1,n);a11+=f[i]*f[i]*wgt;a12+=f[i]*bg[i]*wgt;a22+=bg[i]*bg[i]*wgt;b1+=n*f[i]*wgt;b2+=n*bg[i]*wgt;});
      const det=a11*a22-a12*a12;let A=(b1*a22-b2*a12)/det,B=(a11*b2-a12*b1)/det;if(B<0){B=0;A=b1/a11;}if(A<0)A=0;
      let chi=0;H.forEach((n,i)=>{const mu=A*f[i]+B*bg[i];chi+=(n-mu)**2/Math.max(1,n);});grid.push([M,G,chi]);if(!best||chi<best.chi)best={M,G,A,B,chi};}
    const ok=grid.filter(g=>g[2]<best.chi+1);best.dM=(Math.max(...ok.map(g=>g[0]))-Math.min(...ok.map(g=>g[0])))/2;best.dG=(Math.max(...ok.map(g=>g[1]))-Math.min(...ok.map(g=>g[1])))/2;fitR=best;}
  function drawZ(){if(!vis(zv))return;const {ctx,w,h}=fit(zv,.62,400,270);const H=hist(),mx=Math.max(5,...H)*1.15,bw=(HI-LO)/NB;
    const P=axes(ctx,{l:50,t:14,w:w-66,h:h-46,xr:[LO,HI],yr:[0,mx],xl:'M(μ⁺μ⁻) (GeV)',yl:'eventos / GeV'});
    H.forEach((n,i)=>{const x0=P.X(LO+i*bw),x1=P.X(LO+(i+1)*bw);ctx.fillStyle='rgba(36,83,201,.35)';ctx.fillRect(x0+.5,P.Y(n),x1-x0-1,P.Y(0)-P.Y(n));});
    if(fitR){const f=fitR,s=gr();curve(ctx,P,m=>f.A*voigt(m,f.M,f.G,s)+f.B*Math.exp(-(m-LO)/25),LO,HI,K.b,2.6,null,300);curve(ctx,P,m=>f.B*Math.exp(-(m-LO)/25),LO,HI,K.ax,1.6,[4,4]);}
    const f=fitR;zrd.innerHTML=row('muestra',src==='sim'?'simulada (parámetros del PDG)':'datos reales cargados')+row('eventos en 60–120 GeV',data.length)+(f?row('M_Z ajustada',nf(f.M,2)+' ± '+nf(Math.max(f.dM,0.025),2)+' GeV')+row('Γ_Z ajustado',nf(f.G,1)+' ± '+nf(Math.max(f.dG,0.05),1)+' GeV')+row('χ²/gl',nf(f.chi/(NB-4),2)):'')+sep+
      row('PDG',`M_Z = ${MZ} GeV, Γ_Z = ${GZ} GeV`)+rowT('El ancho medido mezcla Γ_Z con la resolución del detector: si la resolución supuesta es incorrecta, Γ ajustado se desvía.');}
  $('#ndb-file',sec).addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{
    const lines=String(r.result).split(/\r?\n/).filter(Boolean),hd=lines[0].split(',').map(s=>s.trim());const ix=n=>hd.indexOf(n);const out=[];
    for(let i=1;i<lines.length;i++){const c=lines[i].split(',').map(Number);let m=ix('M')>=0?c[ix('M')]:NaN;
      if(!isFinite(m)&&ix('E1')>=0&&ix('px2')>=0){const E=c[ix('E1')]+c[ix('E2')],px=c[ix('px1')]+c[ix('px2')],py=c[ix('py1')]+c[ix('py2')],pz=c[ix('pz1')]+c[ix('pz2')];m=Math.sqrt(Math.max(0,E*E-px*px-py*py-pz*pz));}
      if(isFinite(m)&&m>=LO&&m<HI)out.push(m);}
    if(out.length<50){zrd.innerHTML=rowT('No se encontraron suficientes eventos entre 60 y 120 GeV en el archivo (se busca la columna M o E1, px1… E2, px2…).');return;}
    data=out;src='real';fitZ();drawZ();};r.readAsText(f);});
  gen();
  function draw(){drawW();drawZ();}
  return {draw,tick(dt){if(!vis(cv))return;acc+=dt;while(acc>0.03){acc-=0.03;emit();}parts.forEach(p=>{p.t+=dt;p.x+=p.vx*dt*.6;p.y+=p.vy*dt*.6;});parts=parts.filter(p=>p.x*p.x+p.y*p.y<1);drawW();}};
};

